def check_pptx_state__5a12aa46(result, expected, **options):
    """Check PowerPoint slide state for variation 7.
    
    Args:
        result: dict with slide state from getter
        expected: dict with expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    total_checks = 0
    if 'background_color' in expected:
        total_checks += 1
        result_bg = result.get('background_color', '').upper()
        expected_bg = expected['background_color'].upper()
        if result_bg == expected_bg:
            score += 1.0
    if 'notes_text' in expected:
        total_checks += 1
        result_notes = result.get('notes', '').strip()
        expected_notes = expected['notes_text'].strip()
        if result_notes == expected_notes:
            score += 1.0
    title_fmt = result.get('title_formatting', {})
    if 'title_bold' in expected:
        total_checks += 1
        if title_fmt.get('bold') == expected['title_bold']:
            score += 1.0
    if 'title_italic' in expected:
        total_checks += 1
        if title_fmt.get('italic') == expected['title_italic']:
            score += 1.0
    if 'title_underline' in expected:
        total_checks += 1
        is_underlined = title_fmt.get('underline') is True
        if is_underlined == expected['title_underline']:
            score += 1.0
    if 'font_size' in expected:
        total_checks += 1
        result_size = title_fmt.get('size')
        expected_size_emu = expected['font_size'] * 12700
        if result_size and abs(result_size - expected_size_emu) < 1000:
            score += 1.0
    if 'font_name' in expected:
        total_checks += 1
        if title_fmt.get('name') == expected['font_name']:
            score += 1.0
    if 'title_color' in expected:
        total_checks += 1
        result_color = (title_fmt.get('color') or '').upper()
        expected_color = expected['title_color'].upper()
        if result_color == expected_color:
            score += 1.0
    if 'alignment' in expected:
        total_checks += 1
        from pptx.enum.text import PP_ALIGN
        result_align = title_fmt.get('alignment')
        align_map = {'left': PP_ALIGN.LEFT, 'center': PP_ALIGN.CENTER, 'right': PP_ALIGN.RIGHT}
        expected_align = align_map.get(expected['alignment'].lower())
        if result_align is None:
            result_align = PP_ALIGN.LEFT
        if result_align == expected_align:
            score += 1.0
    return score / total_checks if total_checks > 0 else 0.0

def check_pptx_image_size__e9bc18b68240a0264d167fda8a8b171a(result, expected, **options):
    """Check if a PowerPoint slide contains an image with the expected size and identity.

    Args:
        result: dict from getter with image information
        expected: dict with 'slide_index', 'expected_width_cm', 'expected_height_cm',
                  and optionally 'expected_image_hash' for image identity verification
        **options: Additional options (tolerance)

    Returns:
        float: Score between 0.0 and 1.0
    """
    tolerance = options.get('tolerance', 0.01)
    expected_width = expected.get('expected_width_cm')
    expected_height = expected.get('expected_height_cm')
    expected_image_hash = expected.get('expected_image_hash')
    if not result or 'image_count' not in result:
        return 0.0
    if result['image_count'] == 0:
        return 0.0
    images = result.get('images', [])
    for img in images:
        width_cm = img['width_cm']
        height_cm = img['height_cm']
        width_match = abs(width_cm - expected_width) / expected_width <= tolerance
        height_match = abs(height_cm - expected_height) / expected_height <= tolerance
        if width_match and height_match:
            if expected_image_hash:
                image_hash = img.get('image_hash')
                if image_hash == expected_image_hash:
                    return 1.0
            else:
                return 1.0
    return 0.0

