def check_pptx_property__c07be2dd(result, expected, **options):
    """
    Compare paragraph property against expected value.

    Args:
        result: Property value from getter
        expected: Expected value or dict of expected values
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass)
    """
    if result is None:
        return 0.0
    property_type = expected.get('property', 'underline')
    expected_value = expected.get('value')
    if property_type in ['level', 'alignment']:
        if isinstance(result, int):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type in ['bold', 'italic', 'underline']:
        if isinstance(result, bool):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type == 'color':
        if isinstance(result, list) and len(result) == 3:
            expected_rgb = expected_value
            if isinstance(expected_rgb, list) and len(expected_rgb) == 3:
                return 1.0 if result == expected_rgb else 0.0
        return 0.0
    elif property_type == 'bold_italic':
        if isinstance(result, dict):
            bold_match = result.get('bold', False) == expected_value
            italic_match = result.get('italic', False) == expected_value
            return 1.0 if bold_match and italic_match else 0.0
        return 0.0
    return 0.0

def check_ppt_shape_widths__f2a2245c2f4efc764899cdccfd0c20be(result, expected, **options):
    """Compare shape widths against expected values.

    Args:
        result: Dict mapping slide_shape keys to actual width values in cm
        expected: Dict with 'widths' key containing expected width values
        **options: Additional options (e.g., 'tolerance' for acceptable difference)

    Returns:
        float: Score between 0.0 and 1.0
    """
    tolerance = options.get('tolerance', 0.5)
    expected_widths = expected.get('widths', {})
    if not expected_widths:
        return 0.0
    total_checks = len(expected_widths)
    correct_count = 0
    for (key, expected_width) in expected_widths.items():
        actual_width = result.get(key)
        if actual_width is not None:
            diff = abs(actual_width - expected_width)
            if diff <= tolerance:
                correct_count += 1
    return correct_count / total_checks if total_checks > 0 else 0.0

def check_pptx_pic_text__81412d8b(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if picture dimension and text font sizes match expected values.

    Returns:
        float: Score between 0.0 and 1.0
            0.5: Picture dimension correct
            1.0: Both picture dimension and all text fonts correct
    """
    if 'error' in result:
        return 0.0
    tolerance_cm = options.get('tolerance_cm', 0.2)
    tolerance_pt = options.get('tolerance_pt', 1.0)
    picture_check_dim = expected.get('picture_check', 'width')
    expected_pic_value = expected.get('picture_value_cm', 25.0)
    expected_font_size = expected.get('font_size_pt', 28.0)
    score = 0.0
    result_key = f'picture_{picture_check_dim}_cm'
    actual_pic_value = result.get(result_key)
    if actual_pic_value is not None:
        if abs(actual_pic_value - expected_pic_value) <= tolerance_cm:
            score += 0.5
    font_sizes = result.get('font_sizes', [])
    if font_sizes:
        all_match = all((abs(fs - expected_font_size) <= tolerance_pt for fs in font_sizes))
        if all_match:
            score += 0.5
    return score

