def check_pptx_shape_dims__00324bb6(result_file_path, expected, **options):
    """
    Check if specific shapes in the PPTX file have expected dimensions.
    
    Args:
        result_file_path: Path to the result PPTX file
        expected: Dictionary with "checks" key containing list of dimension checks
                  Each check has: slide (0-indexed), shape_idx, property (width/height), value_cm
        **options: Additional options (tolerance, etc.)
    
    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        prs = Presentation(result_file_path)
        checks = expected.get('checks', [])
        if not checks:
            return 0.0
        tolerance = options.get('tolerance', 0.005)

        def cm_to_emu(cm):
            """Convert centimeters to EMU (English Metric Units)"""
            return int(cm * 360000)

        def is_approximately_equal(val1, val2, tolerance=tolerance):
            """Compare two values with tolerance"""
            if val1 == val2:
                return True
            if val1 == 0 and val2 == 0:
                return True
            if val1 == 0 or val2 == 0:
                return False
            return abs(val1 - val2) / max(abs(val1), abs(val2)) <= tolerance
        for check in checks:
            slide_idx = check['slide']
            shape_idx = check['shape_idx']
            property_name = check['property']
            expected_cm = check['value_cm']
            if slide_idx >= len(prs.slides):
                return 0.0
            slide = prs.slides[slide_idx]
            if shape_idx >= len(slide.shapes):
                return 0.0
            shape = slide.shapes[shape_idx]
            expected_emu = cm_to_emu(expected_cm)
            actual_emu = getattr(shape, property_name)
            if not is_approximately_equal(actual_emu, expected_emu, tolerance):
                return 0.0
        return 1.0
    except Exception as e:
        return 0.0

