def check_ppt_slide_note__8ba174e0(result, expected, **options):
    """Check PowerPoint slide count, last slide title, and first slide note.

    Args:
        result: dict from getter with slide_count, last_slide_title, first_slide_note
        expected: dict with expected values (from rules)
        **options: Additional options

    Returns:
        float: Score 0.0-1.0 with partial credit
    """
    score = 0.0
