def check_pptx_font_color__7491f6c6(pptx_file, expected, **options):
    """Check if all text runs on a specific slide have the target font color.

    Args:
        pptx_file: Path to the PPTX file
        expected: Dict with 'slide_idx' and 'target_color' keys
        **options: Additional options

    Returns:
        float: 1.0 if all text runs match target color, 0.0 otherwise
    """
    try:
        slide_idx = expected.get('slide_idx', 2)
        target_color = expected.get('target_color', 'FF0000').upper()
        prs = Presentation(pptx_file)
        if slide_idx >= len(prs.slides):
            logger.error(f'Slide index {slide_idx} out of range (total slides: {len(prs.slides)})')
            return 0.0
        slide = prs.slides[slide_idx]
        total_runs = 0
        checked_runs = 0
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for para in shape.text_frame.paragraphs:
                    for run in para.runs:
                        if not run.text or not run.text.strip():
                            continue
                        total_runs += 1
                        if not hasattr(run.font.color, 'type'):
                            logger.debug(f'Run has no color type attribute, failing')
                            return 0.0
                        color_type = run.font.color.type
                        if color_type == MSO_COLOR_TYPE.RGB:
                            if hasattr(run.font.color, 'rgb'):
                                actual_color = run.font.color.rgb
                                actual_hex = '{:02X}{:02X}{:02X}'.format(actual_color.r, actual_color.g, actual_color.b)
                                checked_runs += 1
                                if actual_hex != target_color:
                                    logger.debug(f'Color mismatch: expected {target_color}, got {actual_hex}')
                                    return 0.0
                            else:
                                logger.debug(f'RGB color type but no rgb attribute, failing')
                                return 0.0
                        else:
                            logger.debug(f'Run has non-RGB color type: {color_type}, failing')
                            return 0.0
        if total_runs == 0:
            logger.warning('No text runs found on slide')
            return 0.0
        if checked_runs == 0:
            logger.error('No runs were checked (all had non-RGB colors)')
            return 0.0
        if checked_runs != total_runs:
            logger.debug(f'Not all runs were checked: {checked_runs}/{total_runs}')
            return 0.0
        return 1.0
    except Exception as e:
        logger.error(f'Error checking font color: {e}')
        return 0.0

def check_pptx_textbox_alignments__badca355bd4fc0b3c6698dd76f06efb2(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if textbox alignments match expected values.

    Args:
        result: Dict mapping individual textbox keys to alignment strings
            (e.g., {'slide_3_tb_0': 'left', 'slide_3_tb_1': 'left', 'slide_3_tb_2': 'left'})
        expected: Dict with 'alignments' key containing expected textbox->alignment mapping
        **options: Additional options (partial_credit: bool)

    Returns:
        Score between 0.0 and 1.0
    """
    expected_alignments = expected.get('alignments', {})
    partial_credit = options.get('partial_credit', True)
    if not expected_alignments:
        return 0.0
    total_textboxes = len(expected_alignments)
    correct = 0
    for (textbox_key, expected_align) in expected_alignments.items():
        actual_align = result.get(textbox_key, '')
        if actual_align == expected_align:
            correct += 1
    if partial_credit:
        return correct / total_textboxes if total_textboxes > 0 else 0.0
    else:
        return 1.0 if correct == total_textboxes else 0.0

