def check_slide1_bg_color__8e3e9ced833f642248fe82328a810a63(result, expected, **options):
    """Check if slide 1 has the expected background color.

    Args:
        result: Path to the PPTX file
        expected: Dict with 'rgb' key containing target RGB color and 'slide_index' for the slide

    Returns:
        float: Score between 0.0 and 1.0 based on color distance
    """
    if not result:
        return 0.0
    slide_index = expected.get('slide_index', 0)
    target_rgb = expected['rgb']

    def get_rgb_from_color(color):
        try:
            if hasattr(color, 'rgb'):
                return color.rgb
            else:
                return None
        except:
            return None
    try:
        prs = Presentation(result)
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        fill = slide.background.fill
        if fill.type == 1:
            color_rgb = get_rgb_from_color(fill.fore_color)
            if color_rgb is None:
                return 0.0
            (r1, g1, b1) = color_rgb
            (r2, g2, b2) = target_rgb
            distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
            max_distance = sqrt(255 ** 2 + 255 ** 2 + 255 ** 2)
            similarity = 1 - distance / max_distance
            threshold = options.get('threshold', 0.9)
            return 1.0 if similarity >= threshold else similarity
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                color_rgb = get_rgb_from_color(master_fill.fore_color)
                if color_rgb is None:
                    return 0.0
                (r1, g1, b1) = color_rgb
                (r2, g2, b2) = target_rgb
                distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
                max_distance = sqrt(255 ** 2 + 255 ** 2 + 255 ** 2)
                similarity = 1 - distance / max_distance
                threshold = options.get('threshold', 0.9)
                return 1.0 if similarity >= threshold else similarity
        return 0.0
    except Exception as e:
        return 0.0

def check_pptx_image_size__4039f95d(result_file, expected, **options):
    """
    Check if PPTX file has an image with expected dimensions on specified slide.
    
    Args:
        result_file: Path to the PPTX file
        expected: Dictionary with rules containing:
            - slide_index: 0-based slide index
            - expected_width_cm: Expected width in cm
            - expected_height_cm: Expected height in cm
            - tolerance_cm: Tolerance in cm (default 0.05)
        **options: Additional options
        
    Returns:
        float: 1.0 if image found with matching size, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_index = expected.get('slide_index', 0)
        expected_width_cm = expected.get('expected_width_cm', 0)
        expected_height_cm = expected.get('expected_height_cm', 0)
        tolerance_cm = expected.get('tolerance_cm', 0.05)
        if slide_index >= len(prs.slides):
            logger.error(f'Slide index {slide_index} out of range (presentation has {len(prs.slides)} slides)')
            return 0.0
        slide = prs.slides[slide_index]
        expected_width_emu = expected_width_cm * 360000
        expected_height_emu = expected_height_cm * 360000
        tolerance_emu = tolerance_cm * 360000
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.PICTURE or shape.shape_type == 13:
                width_match = abs(shape.width - expected_width_emu) <= tolerance_emu
                height_match = abs(shape.height - expected_height_emu) <= tolerance_emu
                if width_match and height_match:
                    actual_width_cm = shape.width / 360000
                    actual_height_cm = shape.height / 360000
                    logger.info(f'Found matching image on slide {slide_index + 1}: {actual_width_cm:.2f}cm x {actual_height_cm:.2f}cm (expected {expected_width_cm}cm x {expected_height_cm}cm)')
                    return 1.0
        logger.error(f'No image with dimensions {expected_width_cm}cm x {expected_height_cm}cm found on slide {slide_index + 1}')
        return 0.0
    except Exception as e:
        logger.error(f'Error checking image size: {e}')
        return 0.0

def check_pptx_modifications__0f59da9a(result_file, expected, **options):
    """
    Check PowerPoint modifications for variation 7.

    Verifies:
    - All image widths on a specified slide match expected width
    - All text font sizes on a specified slide match expected size

    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with slide indices and expected values
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (0.5 points for images, 0.5 for text)
    """
    try:
        prs = Presentation(result_file)
        score = 0.0
        tolerance_cm = options.get('tolerance_cm', 0.5)
        tolerance_pt = options.get('tolerance_pt', 2.0)
        if 'image_slide_idx' in expected and 'expected_width_cm' in expected:
            image_slide_idx = expected['image_slide_idx']
            if image_slide_idx < len(prs.slides):
                slide = prs.slides[image_slide_idx]
                images = [shape for shape in slide.shapes if shape.shape_type == 13]
                if images:
                    all_images_match = True
                    for img in images:
                        width_cm = img.width / 360000
                        expected_width = expected['expected_width_cm']
                        if abs(width_cm - expected_width) > tolerance_cm:
                            all_images_match = False
                            break
                        if 'expected_height_cm' in expected:
                            height_cm = img.height / 360000
                            expected_height = expected['expected_height_cm']
                            if abs(height_cm - expected_height) > tolerance_cm:
                                all_images_match = False
                                break
                    if all_images_match:
                        score += 0.5
                else:
                    pass
        if 'text_slide_idx' in expected and 'expected_font_size' in expected:
            text_slide_idx = expected['text_slide_idx']
            expected_font_size = expected['expected_font_size']
            if text_slide_idx < len(prs.slides):
                slide = prs.slides[text_slide_idx]
                text_shapes = [shape for shape in slide.shapes if hasattr(shape, 'text_frame')]
                if text_shapes:
                    all_text_match = True
                    text_runs_checked = 0
                    for shape in text_shapes:
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                if run.font.size is not None:
                                    text_runs_checked += 1
                                    font_size_pt = run.font.size.pt
                                    if abs(font_size_pt - expected_font_size) > tolerance_pt:
                                        all_text_match = False
                                        break
                            if not all_text_match:
                                break
                        if not all_text_match:
                            break
                    if all_text_match and text_runs_checked > 0:
                        score += 0.5
                else:
                    pass
        return score
    except Exception as e:
        print(f'Error checking PPTX: {e}')
        return 0.0

def check_pptx_slides__0b3229fd(result, expected, **options):
    """
    Check if 3 consecutive slides are identical.

    Args:
        result: Dict from getter with 'slides' list
        expected: Dict with 'total_slides', 'slide_idx', 'count' keys

    Returns:
        Score from 0.0 to 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    result_count = result.get('total_slides', 0)
    expected_count = expected.get('total_slides', 0)
    check_idx = expected.get('slide_idx', -1)
    expected_dupe_count = expected.get('count', 3)
    score = 0.0
    if result_count == expected_count:
        score += 0.5
    slides = result.get('slides', [])
    if check_idx >= 0 and check_idx + expected_dupe_count - 1 < len(slides):
        hashes = [slides[check_idx + i].get('text_hash') for i in range(expected_dupe_count)]
        if len(set(hashes)) == 1:
            score += 0.5
    return score

