def check_pptx_has_image__11b877a27a380575d5bab482e21af6e1(result, expected, **options):
    """
    Check if PPTX file contains at least one image.

    Args:
        result: Path to the result PPTX file (from getter)
        expected: Expected rules dict with 'has_image' key
        **options: Additional options

    Returns:
        float: 1.0 if image presence matches expected, 0.0 otherwise
    """
    if not result:
        logger.error('No result file path')
        return 0.0
    expected_has_image = expected.get('has_image', True) if isinstance(expected, dict) else True
    try:
        pres = Presentation(result)
        images_found = False
        for slide in pres.slides:
            images = [shape for shape in slide.shapes if shape.shape_type == 13]
            if images:
                images_found = True
                logger.info(f'Found {len(images)} image(s) in presentation')
                break
        if expected_has_image and images_found:
            logger.info('Image presence matches expected (has_image=True, images found)')
            return 1.0
        elif not expected_has_image and (not images_found):
            logger.info('Image presence matches expected (has_image=False, no images found)')
            return 1.0
        else:
            if expected_has_image:
                logger.error('Expected images but none found')
            else:
                logger.error('Expected no images but found some')
            return 0.0
    except Exception as e:
        logger.error(f'Error reading PPTX file: {e}')
        return 0.0

def check_pptx_state__e6eecf51(result, expected, **options):
    """Check PowerPoint slide state for variation 1.
    
    Args:
        result: dict with slide state from getter
        expected: dict with expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    total_checks = 0
    if 'background_color' in expected:
        total_checks += 1
        result_bg = result.get('background_color', '').upper()
        expected_bg = expected['background_color'].upper()
        if result_bg == expected_bg:
            score += 1.0
    if 'notes_text' in expected:
        total_checks += 1
        result_notes = result.get('notes', '').strip()
        expected_notes = expected['notes_text'].strip()
        if result_notes == expected_notes:
            score += 1.0
    title_fmt = result.get('title_formatting', {})
    if 'title_bold' in expected:
        total_checks += 1
        if title_fmt.get('bold') == expected['title_bold']:
            score += 1.0
    if 'title_italic' in expected:
        total_checks += 1
        if title_fmt.get('italic') == expected['title_italic']:
            score += 1.0
    if 'title_underline' in expected:
        total_checks += 1
        is_underlined = title_fmt.get('underline') is True
        if is_underlined == expected['title_underline']:
            score += 1.0
    if 'font_size' in expected:
        total_checks += 1
        result_size = title_fmt.get('size')
        expected_size_emu = expected['font_size'] * 12700
        if result_size and abs(result_size - expected_size_emu) < 1000:
            score += 1.0
    if 'font_name' in expected:
        total_checks += 1
        if title_fmt.get('name') == expected['font_name']:
            score += 1.0
    if 'title_color' in expected:
        total_checks += 1
        result_color = (title_fmt.get('color') or '').upper()
        expected_color = expected['title_color'].upper()
        if result_color == expected_color:
            score += 1.0
    if 'alignment' in expected:
        total_checks += 1
        from pptx.enum.text import PP_ALIGN
        result_align = title_fmt.get('alignment')
        align_map = {'left': PP_ALIGN.LEFT, 'center': PP_ALIGN.CENTER, 'right': PP_ALIGN.RIGHT}
        expected_align = align_map.get(expected['alignment'].lower())
        if result_align is None:
            result_align = PP_ALIGN.LEFT
        if result_align == expected_align:
            score += 1.0
    return score / total_checks if total_checks > 0 else 0.0

