def check_pptx_table_centered__08b6cf3e(result, expected, **options):
    """Check if the table on a specific slide is centered horizontally.

    Args:
        result: Path to the PPTX file
        expected: Dict with 'slide_index' and 'shape_type' keys
        **options: Additional options

    Returns:
        float: 1.0 if table is centered, 0.0 otherwise
    """
    slide_index = expected.get('slide_index', 2)
    shape_type = expected.get('shape_type', 19)
    tolerance = options.get('tolerance', 200000)
    try:
        prs = Presentation(result)
        slide = prs.slides[slide_index]
        table_shape = None
        for shape in slide.shapes:
            if shape.shape_type == shape_type:
                table_shape = shape
                break
        if table_shape is None:
            return 0.0
        expected_left = (prs.slide_width - table_shape.width) / 2
        actual_left = table_shape.left
        if abs(actual_left - expected_left) <= tolerance:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        return 0.0

def check_pptx_table_header_bold__c4e91f73(result_file, expected, **options):
    """
    Check if first row of table is bold.
    
    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with 'slide_idx', 'shape_idx', and 'row_idx'
        **options: Additional options
        
    Returns:
        float: 1.0 if first row is bold, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 0)
        row_idx = expected.get('row_idx', 0)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if shape.shape_type != MSO_SHAPE_TYPE.TABLE:
            return 0.0
        table = shape.table
        if row_idx >= len(table.rows):
            return 0.0
        for col_idx in range(len(table.columns)):
            cell = table.cell(row_idx, col_idx)
            cell_text = cell.text_frame.text.strip()
            if cell_text:
                has_runs = False
                all_bold = True
                for para in cell.text_frame.paragraphs:
                    if para.text.strip() and (not para.runs):
                        return 0.0
                    for run in para.runs:
                        has_runs = True
                        if not run.font.bold:
                            return 0.0
                if cell_text and (not has_runs):
                    return 0.0
        return 1.0
    except Exception as e:
        return 0.0

