def check_ppt_table_content__2c91f820c9951d53b92190cdccee21ec(result, expected, **options):
    """Compare table content against expected data.

    Args:
        result: Dict with table data from getter
        expected: Dict with expected table data from rules
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, dict):
        return 0.0
    expected_data = expected.get('data', [])
    result_data = result.get('data', [])
    if not expected_data:
        return 0.0
    score = 0.0
    total_checks = 0
    for (row_idx, expected_row) in enumerate(expected_data):
        if row_idx >= len(result_data):
            continue
        for (col_idx, expected_cell) in enumerate(expected_row):
            if col_idx >= len(result_data[row_idx]):
                continue
            total_checks += 1
            if result_data[row_idx][col_idx] == expected_cell:
                score += 1.0
    if total_checks == 0:
        return 0.0
    return score / total_checks

