def check_slide_note_has_any_keyword__9700755acf4986bacd5b2ef2a6c67b2e(result: str, expected: Dict, **options) -> float:
    """
    Check that a slide's speaker notes contain multiple policy-related keywords
    to ensure substantial policy content was added.

    Args:
        result: The actual notes text from the slide
        expected: Rules dict with:
            - 'keywords' list (multiple keywords must match)
            - 'min_keywords' int (minimum number of keywords required, default 3)
            - 'min_length' int (minimum text length, default 20)
            - 'case_sensitive' bool (default False)
        **options: Additional options

    Returns:
        float: 1.0 if notes meet all requirements, 0.0 otherwise
    """
    if not isinstance(result, str):
        return 0.0
    keywords = expected.get('keywords', [])
    case_sensitive = expected.get('case_sensitive', False)
    min_keywords = expected.get('min_keywords', 3)
    min_length = expected.get('min_length', 20)
    if not keywords:
        return 0.0
    if len(result.strip()) < min_length:
        return 0.0
    keyword_count = 0
    for keyword in keywords:
        if case_sensitive:
            if keyword in result:
                keyword_count += 1
        elif keyword.lower() in result.lower():
            keyword_count += 1
    if keyword_count >= min_keywords:
        return 1.0
    return 0.0

def check_pptx_slide4_title_bold_black__9fd03b81(result_file, expected, **options):
    """
    Check if slide 4 title 'Contact Us' is both bold and black.

    Args:
        result_file: Path to the PPTX file
        expected: Not used
        **options: Additional options

    Returns:
        float: Partial credit - 0.5 for bold, 0.5 for black color
    """
    try:
        prs = Presentation(result_file)
        if len(prs.slides) < 4:
            return 0.0
        slide = prs.slides[3]
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip() == 'Contact Us':
                if hasattr(shape, 'text_frame'):
                    all_runs = []
                    for para in shape.text_frame.paragraphs:
                        for run in para.runs:
                            all_runs.append(run)
                    if not all_runs:
                        return 0.0
                    all_bold = all((run.font.bold is True for run in all_runs))
                    all_black = True
                    for run in all_runs:
                        if hasattr(run.font.color, 'rgb'):
                            rgb = run.font.color.rgb
                            if not (rgb[0] < 30 and rgb[1] < 30 and (rgb[2] < 30)):
                                all_black = False
                                break
                        else:
                            all_black = False
                            break
                    score = 0.0
                    if all_bold:
                        score += 0.5
                    if all_black:
                        score += 0.5
                    return score
        return 0.0
    except Exception as e:
        return 0.0

