def check_pptx_formatting__eb1a2c3f(result, expected, **options):
    """Check if text formatting matches expected values.
    
    Args:
        result: Dict of formatting data from getter
        expected: Dict with 'slide_indices' and format-specific expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    check_type = expected.get('check_type', 'bold')
    expected_value = expected.get('expected_value')
    slide_indices = expected.get('slide_indices', [])
    total_runs = 0
    matching_runs = 0
    for (key, fmt) in result.items():
        (slide_idx, shape_idx, para_idx, run_idx) = key
        if slide_idx not in slide_indices:
            continue
        if not fmt['text'].strip():
            continue
        total_runs += 1
        if check_type == 'bold':
            if fmt['bold'] == expected_value:
                matching_runs += 1
        elif check_type == 'italic':
            if fmt['italic'] == expected_value:
                matching_runs += 1
        elif check_type == 'underline':
            actual = fmt['underline']
            if expected_value is True:
                if actual is True:
                    matching_runs += 1
            elif actual is None or actual is False:
                matching_runs += 1
        elif check_type == 'font_size':
            if fmt['size'] is not None and abs(fmt['size'] - expected_value) < 0.5:
                matching_runs += 1
        elif check_type == 'color':
            if fmt['color'] == expected_value:
                matching_runs += 1
        elif check_type == 'alignment':
            align_map = {'CENTER': PP_ALIGN.CENTER, 'RIGHT': PP_ALIGN.RIGHT, 'LEFT': PP_ALIGN.LEFT}
            expected_align = align_map.get(expected_value)
            actual_align = fmt['alignment']
            if actual_align is None:
                actual_align = PP_ALIGN.LEFT
            if actual_align == expected_align:
                matching_runs += 1
        elif check_type == 'bold_italic':
            if fmt['bold'] == expected_value and fmt['italic'] == expected_value:
                matching_runs += 1
        elif check_type == 'size_underline':
            size_match = fmt['size'] is not None and abs(fmt['size'] - expected_value['size']) < 0.5
            underline_match = fmt['underline'] is True if expected_value['underline'] else fmt['underline'] is None or fmt['underline'] is False
            if size_match and underline_match:
                matching_runs += 1
        elif check_type == 'bold_color':
            bold_match = fmt['bold'] == expected_value['bold']
            color_match = fmt['color'] == expected_value['color']
            if bold_match and color_match:
                matching_runs += 1
    if total_runs == 0:
        return 0.0
    return matching_runs / total_runs

