def check_pptx_textbox_alignments__0c1a13c8c36ff1bf8a907986c6c14be7(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if textbox alignments match expected values.

    Args:
        result: Dict mapping slide keys to alignment strings (e.g., {'slide_3': 'left', 'slide_4': 'center'})
        expected: Dict with 'alignments' key containing expected slide->alignment mapping
        **options: Additional options (partial_credit: bool)

    Returns:
        Score between 0.0 and 1.0
    """
    expected_alignments = expected.get('alignments', {})
