def check_pptx_image_size__1abc6b9d(result_file, expected, **options):
    """
    Check if PPTX file has the correct image with expected dimensions on specified slide.

    This function verifies:
    1. An image exists on the specified slide
    2. The image has the expected dimensions (within tolerance)
    3. The image content matches the expected source image 'none.png'

    Args:
        result_file: Path to the PPTX file
        expected: Dictionary with rules containing:
            - slide_index: 0-based slide index
            - expected_width_cm: Expected width in cm
            - expected_height_cm: Expected height in cm
            - tolerance_cm: Tolerance in cm (default 0.05)
            - expected_image_path: Optional path to expected source image (default: /home/user/Desktop/none.png)
        **options: Additional options

    Returns:
        float: 1.0 if image found with matching size and content, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_index = expected.get('slide_index', 0)
        expected_width_cm = expected.get('expected_width_cm', 0)
        expected_height_cm = expected.get('expected_height_cm', 0)
        tolerance_cm = expected.get('tolerance_cm', 0.05)
        expected_image_path = expected.get('expected_image_path', '/home/user/Desktop/none.png')
        if slide_index >= len(prs.slides):
            logger.error(f'Slide index {slide_index} out of range (presentation has {len(prs.slides)} slides)')
            return 0.0
        slide = prs.slides[slide_index]
        expected_width_emu = expected_width_cm * 360000
        expected_height_emu = expected_height_cm * 360000
        tolerance_emu = tolerance_cm * 360000
        expected_image_hash = _get_file_hash(expected_image_path)
        if expected_image_hash is None:
            logger.warning(f'Expected image file not found at {expected_image_path}, skipping content verification')
            verify_content = False
        else:
            verify_content = True
            logger.info(f'Expected image hash: {expected_image_hash}')
        matching_size_count = 0
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.PICTURE or shape.shape_type == 13:
                width_match = abs(shape.width - expected_width_emu) <= tolerance_emu
                height_match = abs(shape.height - expected_height_emu) <= tolerance_emu
                if width_match and height_match:
                    matching_size_count += 1
                    actual_width_cm = shape.width / 360000
                    actual_height_cm = shape.height / 360000
                    logger.info(f'Found image with matching size on slide {slide_index + 1}: {actual_width_cm:.2f}cm x {actual_height_cm:.2f}cm (expected {expected_width_cm}cm x {expected_height_cm}cm)')
                    if verify_content:
                        try:
                            image = shape.image
                            image_blob = image.blob
                            actual_image_hash = _get_image_hash(image_blob)
                            logger.info(f'Actual image hash: {actual_image_hash}')
                            if actual_image_hash == expected_image_hash:
                                logger.info(f"Image content matches expected 'none.png'")
                                return 1.0
                            else:
                                logger.warning(f"Image size matches but content differs from 'none.png'")
                        except Exception as e:
                            logger.error(f'Error verifying image content: {e}')
                    else:
                        return 1.0
        if matching_size_count > 0:
            logger.error(f"Found {matching_size_count} image(s) with matching dimensions but none match the expected 'none.png' content")
        else:
            logger.error(f'No image with dimensions {expected_width_cm}cm x {expected_height_cm}cm found on slide {slide_index + 1}')
        return 0.0
    except Exception as e:
        logger.error(f'Error checking image size and content: {e}')
        return 0.0

