def check_pptx_slide_images__82ff5b7c65e814d931f87d5c248a48c2(result, expected, **options):
    """Check if PowerPoint has correct number of slides with images in correct order.

    Args:
        result: dict from getter with 'slide_count', 'images', and 'slide_shapes'
        expected: dict with 'expected_slide_count' and 'expected_images'
        **options: Additional options (including 'env' for accessing Desktop files)

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_slide_count = expected.get('expected_slide_count', 0)
    expected_images = expected.get('expected_images', [])
    if result['slide_count'] != expected_slide_count:
        return 0.0
    if len(result['images']) != len(expected_images):
        return 0.0
    slide_shapes = result.get('slide_shapes', [])
    for slide_info in slide_shapes:
        shape_types = slide_info.get('shape_types', [])
        if any((shape_type != 13 for shape_type in shape_types)):
            return 0.0
    env = options.get('env')
    if not env:
        return 0.5
    expected_image_hashes = {}
    for expected_img in expected_images:
        image_name = expected_img['expected_image_name']
        desktop_path = f'/home/user/Desktop/{image_name}.png'
        try:
            image_bytes = env.controller.get_file(desktop_path)
            if image_bytes:
                image_hash = hashlib.md5(image_bytes).hexdigest()
                expected_image_hashes[expected_img['expected_slide_idx']] = {'hash': image_hash, 'name': image_name}
        except:
            pass
    score = 0.0
    total_checks = len(expected_images)
    for expected_img in expected_images:
        expected_slide_idx = expected_img['expected_slide_idx']
        images_on_slide = [img for img in result['images'] if img['slide_idx'] == expected_slide_idx]
        if not images_on_slide:
            continue
        expected_hash_info = expected_image_hashes.get(expected_slide_idx)
        if expected_hash_info:
            expected_hash = expected_hash_info['hash']
            for img in images_on_slide:
                if img.get('image_hash') == expected_hash:
                    score += 1.0 / total_checks
                    break
        else:
            score += 0.5 / total_checks
    return score

