def check_pptx_modifications__8cf806f5(result_file, expected, **options):
    """
    Check PowerPoint modifications for variation 1.
    
    Verifies:
    - Image dimensions (width/height) on specified slides
    - Text font sizes on specified slides
    
    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with slide indices and expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0 (partial credit for each requirement)
    """
    try:
        prs = Presentation(result_file)
        score = 0.0
        total_checks = 0
        tolerance_cm = options.get('tolerance_cm', 0.5)
        tolerance_pt = options.get('tolerance_pt', 2.0)
        if 'image_slide_idx' in expected:
            total_checks += 1
            image_slide_idx = expected['image_slide_idx']
            if image_slide_idx < len(prs.slides):
                slide = prs.slides[image_slide_idx]
                images = [shape for shape in slide.shapes if shape.shape_type == 13]
                if images:
                    all_images_match = True
                    for img in images:
                        if 'expected_width_cm' in expected:
                            width_cm = img.width / 360000
                            expected_width = expected['expected_width_cm']
                            if abs(width_cm - expected_width) > tolerance_cm:
                                all_images_match = False
                                break
                        if 'expected_height_cm' in expected:
                            height_cm = img.height / 360000
                            expected_height = expected['expected_height_cm']
                            if abs(height_cm - expected_height) > tolerance_cm:
                                all_images_match = False
                                break
                    if all_images_match:
                        score += 0.5
        if 'text_slide_idx' in expected:
            total_checks += 1
            text_slide_idx = expected['text_slide_idx']
            if text_slide_idx < len(prs.slides):
                slide = prs.slides[text_slide_idx]
                expected_font_size = expected.get('expected_font_size', None)
                if expected_font_size:
                    all_text_match = True
                    text_shapes = [shape for shape in slide.shapes if hasattr(shape, 'text_frame')]
                    for shape in text_shapes:
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                if run.font.size:
                                    font_size_pt = run.font.size.pt
                                    if abs(font_size_pt - expected_font_size) > tolerance_pt:
                                        all_text_match = False
                                        break
                            if not all_text_match:
                                break
                        if not all_text_match:
                            break
                    if all_text_match:
                        score += 0.5
        return score
    except Exception as e:
        print(f'Error checking PPTX: {e}')
        return 0.0

def check_ppt_properties__2b3e9f33(result, expected, **options):
    """
    Check if PPT properties match expected values.

    Args:
        result: Dict with properties from getter
        expected: Dict with expected properties
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    score = 0.0
    total_checks = 0
    for (key, expected_value) in expected.items():
        total_checks += 1
        if key in result:
            actual_value = result[key]
            if key.endswith('_color'):
                if actual_value == expected_value:
                    score += 1.0
            elif isinstance(expected_value, bool):
                actual_normalized = actual_value if actual_value is not None else False
                expected_normalized = expected_value if expected_value is not None else False
                if actual_normalized == expected_normalized:
                    score += 1.0
            elif actual_value == expected_value:
                score += 1.0
    if total_checks == 0:
        return 0.0
    return score / total_checks

