    expected_text = expected.get('text', '')
    expected_size_pt = expected.get('font_size_pt', 0)
    if not result or 'shapes' not in result:
        return 0.0
    for shape in result['shapes']:
        for run in shape.get('runs', []):
            if expected_text.lower() in run.get('text', '').lower():
                actual_size_pt = run.get('font_size_pt')
                if actual_size_pt and abs(actual_size_pt - expected_size_pt) < 1:
                    return 1.0
    return 0.0

