def check_slide_title_bold__ec78028f(result_file, expected, **options):
    """
    Check if the title in specified slides has bold formatting applied.

    Args:
        result_file: Path to the PPTX file
        expected: Rules dictionary containing:
            - 'slides': List of slide indices (0-indexed) to check
            - 'bold': Boolean indicating expected bold state (True/False)
        **options: Additional options

    Returns:
        float: 1.0 if all titles in specified slides match the expected bold state, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_indices = expected.get('slides', [])
        expected_bold = expected.get('bold', True)
        for slide_idx in slide_indices:
            if slide_idx >= len(prs.slides):
                logger.error(f'Slide index {slide_idx} out of range (total slides: {len(prs.slides)})')
                return 0.0
            slide = prs.slides[slide_idx]
            title_shape = None
            if hasattr(slide, 'shapes') and hasattr(slide.shapes, 'title'):
                title_shape = slide.shapes.title
            if title_shape is None:
                for shape in slide.shapes:
                    if hasattr(shape, 'text_frame') and hasattr(shape, 'text'):
                        title_shape = shape
                        break
            if title_shape is None:
                logger.error(f'No title shape found in slide {slide_idx}')
                return 0.0
            if not hasattr(title_shape, 'text_frame'):
                logger.error(f'Title shape in slide {slide_idx} has no text_frame')
                return 0.0
            text_frame = title_shape.text_frame
            for paragraph in text_frame.paragraphs:
                for run in paragraph.runs:
                    run_bold = run.font.bold
                    if expected_bold:
                        if run_bold is not True:
                            logger.debug(f'Slide {slide_idx}: Found run with bold={run_bold}, expected True')
                            return 0.0
                    elif run_bold is True:
                        logger.debug(f'Slide {slide_idx}: Found run with bold={run_bold}, expected False/None')
                        return 0.0
        return 1.0
    except Exception as e:
        logger.error(f'Error checking slide title bold: {e}')
        return 0.0

def check_ppt_title_font__a99a51a5(result, expected, **options):
    """Check if title font name in specified slides matches expected values.

    Args:
        result: Dict from getter - {slide_idx: {property: value}}
        expected: Dict with expected values per slide

    Returns:
        float: Score between 0.0 and 1.0
    """
    target_slides = expected.get('target_slides', [])
    expected_font = expected.get('expected_font', 'Arial')
    if not target_slides:
        return 0.0
    correct_count = 0
    total_count = len(target_slides)
    for slide_idx in target_slides:
        if slide_idx not in result:
            continue
        actual_font = result[slide_idx].get('font_name')
        if actual_font and actual_font.lower() == expected_font.lower():
            correct_count += 1
    return correct_count / total_count if total_count > 0 else 0.0

