def check_slide_content__8890dcab6eb014437adbb9b7df1c7374(result, expected, **options):
    """Check if extracted slide content contains expected key phrases.

    Args:
        result: str from getter (extracted content from docx)
        expected: Dict with 'required_phrases' key containing list of phrases that must appear
        **options: Additional options (not used)

    Returns:
        float: Proportion of required phrases found (0.0 to 1.0)
    """
    if not isinstance(result, str):
        return 0.0
    required_phrases = expected.get('required_phrases', [])
    if not required_phrases:
        return 0.0
    result_normalized = ' '.join(result.lower().split())
    found_count = 0
    for phrase in required_phrases:
        phrase_normalized = ' '.join(phrase.lower().split())
        if phrase_normalized in result_normalized:
            found_count += 1
    return found_count / len(required_phrases)

def check_pptx_image_size__81d1575f(result, expected, **options):
    """
    Check if an image with specific dimensions and name exists in the result.

    Args:
        result: List of image info dicts from getter
        expected: Dict with 'width', 'height' in EMUs, optional 'tolerance', optional 'expected_image_name'
        **options: Additional options

    Returns:
        float: 1.0 if image found with correct size and name, 0.0 otherwise
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    target_width = expected.get('width')
    target_height = expected.get('height')
    tolerance = expected.get('tolerance', 0.01)
    expected_image_name = expected.get('expected_image_name')
    for img in result:
        width = img.get('width', 0)
        height = img.get('height', 0)
        img_name = img.get('name', '').lower()
        if target_width > 0 and target_height > 0:
            width_diff = abs(width - target_width) / target_width
            height_diff = abs(height - target_height) / target_height
            dimensions_match = width_diff <= tolerance and height_diff <= tolerance
            if not expected_image_name:
                if dimensions_match:
                    return 1.0
            else:
                expected_name_lower = expected_image_name.lower()
                name_matches = expected_name_lower in img_name
                if dimensions_match and name_matches:
                    return 1.0
    return 0.0

