def check_pptx_paragraph_exists__64319b588a870966ed443214aba7b471(result: List[Dict], expected: Dict, **options) -> float:
    """Check if specific paragraphs with correct text and level exist.

    Args:
        result: List of paragraph dicts from getter
        expected: Rules dict with 'paragraphs' list

    Returns:
        Score between 0.0 and 1.0
    """
    target_paragraphs = expected.get('paragraphs', [])
    if not target_paragraphs:
        return 0.0
    matched_indices = set()
    score = 0.0
    for target in target_paragraphs:
        target_text = target['text']
        target_level = target['level']
        found = False
        for (idx, para) in enumerate(result):
            if idx not in matched_indices and para['text'] == target_text and (para['level'] == target_level):
                found = True
                matched_indices.add(idx)
                break
        if found:
            score += 1.0 / len(target_paragraphs)
    return score

