def check_pptx_multi_slide__43517c6f7cec20aa300e732d5f7c64aa(result, expected, **options):
    """Check if multiple text conditions are met across different slides.

    Args:
        result: List of lists, where each inner list contains all text from one slide
        expected: Dict with keys:
            - checks: List of dicts, each with 'slide_index' and 'target_text'

    Returns:
        float: Partial credit based on how many checks pass (0.0 to 1.0)
    """
    if not isinstance(result, list):
        return 0.0
    checks = expected.get('checks', [])
    if not checks:
        return 0.0
    passed_checks = 0
    total_checks = len(checks)
    for check in checks:
        slide_index = check.get('slide_index', 0)
        target_text = check.get('target_text', '')
        if slide_index >= len(result):
            continue
        slide_texts = result[slide_index]
        for text in slide_texts:
            if target_text in text:
                passed_checks += 1
                break
    return passed_checks / total_checks

