def check_qt_slider_colours__343f3ef0(actual_config_path, rule):
    """
    Check if VLC volume slider colors are bluish (custom metric for variation 8).
    """
    with open(actual_config_path, 'rb') as file:
        config_file = file.read().decode('utf-8')
    try:
        qt_slider_colours = '153;210;153;20;210;20;255;199;15;245;39;29'
        for line in config_file.split('\n'):
            if 'qt-slider-colours' in line:
                qt_slider_colours = line.split('=')[-1].strip()
        if rule['type'] == 'bluish':

            def is_color_bluish(rgb_values, threshold=150):
                """Check if a color is bluish (B > threshold and B dominates R and G)"""
                (r, g, b) = rgb_values
                return b > threshold and b > r + 50 and (b > g + 50)

            def parse_qt_slider_colours(colours_string):
                """Parse the string of colours into a list of RGB tuples"""
                values = [int(x) for x in colours_string.split(';')]
                colors = list(zip(values[0::3], values[1::3], values[2::3]))
                return colors
            colors = parse_qt_slider_colours(qt_slider_colours)
            for color in colors:
                if not is_color_bluish(color):
                    return 0
            return 1
        else:
            return 0
    except FileNotFoundError:
        logger.error('VLC configuration file not found.')
        return 0
    except Exception as e:
        logger.error(f'An error occurred: {e}')
        return 0

def check_pptx_font_properties__b5dcaa4c(result_file, expected, **options):
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 0)
        expected_font = expected.get('font_name', '')
        expected_bold = expected.get('bold', None)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        for para in shape.text_frame.paragraphs:
            for run in para.runs:
                if expected_font and run.font.name != expected_font:
                    return 0.0
                if expected_bold is not None:
                    if expected_bold and run.font.bold is not True:
                        return 0.0
                    elif not expected_bold and run.font.bold is True:
                        return 0.0
        return 1.0
    except:
        return 0.0

def check_ppt_transitions__15892f6c(result, expected, **options):
    """Check if PowerPoint slides have the expected transition.

    Args:
        result: dict from getter with transitions list
        expected: dict with transition_type and check_all_slides flag (from rules)
        **options: Additional options

    Returns:
        float: Score 0.0-1.0
    """
    transitions = result.get('transitions', [])
    expected_type = expected.get('transition_type', 'fade')
    check_all = expected.get('check_all_slides', True)
    if not transitions:
        return 0.0
    if check_all:
        matching_count = sum((1 for t in transitions if t == expected_type))
        return 1.0 if matching_count == len(transitions) else 0.0
    else:
        return 1.0 if expected_type in transitions else 0.0

