def verify_pptx_changes__80c27333cebeb7353404c7cb598c7b50(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Verify expected changes to PowerPoint slides.
    
    Args:
        result: Dict from getter with slide content
        expected: Dict with expected values (from rules):
            {
                "requirements": [
                    {"slide": 1, "title": "Getting Started"},
                    {"slide": 4, "bg_color": "#90EE90"}
                ]
            }
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    requirements = expected.get('requirements', [])
    if not requirements:
        return 0.0
    score = 0.0
    points_per_req = 1.0 / len(requirements)
    color_tolerance = options.get('color_tolerance', 20)
    for req in requirements:
        slide_idx = req.get('slide')
        if slide_idx is None or slide_idx not in result:
            continue
        content = result[slide_idx]
        req_met = True
        if 'title' in req:
            expected_title = req['title']
            actual_title = content.get('title', '')
            if actual_title is None:
                actual_title = ''
            if expected_title.lower().strip() != actual_title.lower().strip():
                req_met = False
        if 'bg_color' in req and req_met:
            expected_color = req['bg_color'].upper()
            actual_color = content.get('bg_color')
            if actual_color is None:
                req_met = False
            else:
                actual_color = actual_color.upper()

                def hex_to_rgb(hex_str):
                    hex_str = hex_str.lstrip('#')
                    return tuple((int(hex_str[i:i + 2], 16) for i in (0, 2, 4)))
                try:
                    exp_rgb = hex_to_rgb(expected_color)
                    act_rgb = hex_to_rgb(actual_color)
                    diff = sum((abs(e - a) for (e, a) in zip(exp_rgb, act_rgb)))
                    if diff > color_tolerance * 3:
                        req_met = False
                except:
                    req_met = False
        if req_met:
            score += points_per_req
    return min(1.0, score)

