def check_ppt_slide_title__a8b967bd402ad264a1b2d82796f54662(result, expected, **options):
    """Check if PowerPoint slide title matches expected values.

    Args:
        result: Dict from getter with 'text', 'color_rgb', etc.
        expected: Dict with expected values (from rules)
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not expected:
        return 0.0
    score = 0.0
    checks = 0
    if 'text' in expected:
        checks += 1
        if result.get('text', '').strip().lower() == expected['text'].strip().lower():
            score += 1.0
    if 'color_rgb' in expected:
        checks += 1
        result_rgb = result.get('color_rgb')
        expected_rgb = expected['color_rgb']
        if result_rgb and expected_rgb:
            if result_rgb[0] == expected_rgb[0] and result_rgb[1] == expected_rgb[1] and (result_rgb[2] == expected_rgb[2]):
                score += 1.0
    if 'bold' in expected:
        checks += 1
        result_bold = result.get('bold')
        expected_bold = expected['bold']
        if result_bold is True and expected_bold is True or ((result_bold is None or result_bold is False) and (expected_bold is None or expected_bold is False)):
            score += 1.0
    if checks == 0:
        return 0.0
    return score / checks

def check_pptx_slide_images__0378ddab19b99794097efbf87e397824(result, expected, **options):
    """Check if PowerPoint has correct number of slides with images in correct order.

    Args:
        result: dict from getter with 'slide_count', 'images', and 'slide_shapes'
        expected: dict with 'expected_slide_count' and 'expected_images'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_slide_count = expected.get('expected_slide_count', 0)
    expected_images = expected.get('expected_images', [])
    if result['slide_count'] != expected_slide_count:
        return 0.0
    if len(result['images']) != len(expected_images):
        return 0.0
    images_by_slide = {}
    for img in result['images']:
        slide_idx = img['slide_idx']
        if slide_idx not in images_by_slide:
            images_by_slide[slide_idx] = []
        images_by_slide[slide_idx].append(img)
    score = 0.0
    total_checks = len(expected_images)
    for expected_img in expected_images:
        expected_slide_idx = expected_img['expected_slide_idx']
        expected_name = expected_img['expected_image_name'].lower()
        if expected_slide_idx not in images_by_slide:
            continue
        slide_images = images_by_slide[expected_slide_idx]
        if len(slide_images) != 1:
            continue
        result_name = slide_images[0]['image_name'].lower()
        if expected_name in result_name or result_name in expected_name:
            slide_shapes = result.get('slide_shapes', {}).get(expected_slide_idx, {})
            total_shapes = slide_shapes.get('total_shapes', 0)
            image_count = slide_shapes.get('image_count', 0)
            if total_shapes == image_count:
                score += 1.0 / total_checks
    return score

def check_pptx_title_bold__51da4dc2(result_file, expected, **options):
    """
    Check if specific title text on a slide has bold formatting and red border.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing slide_idx, text_to_find, and check_bold flag
        **options: Additional options

    Returns:
        float: 1.0 if both title text is bold and has red border, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        text_to_find = expected.get('text_to_find', '')
        check_bold = expected.get('check_bold', True)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        for shape in slide.shapes:
            if hasattr(shape, 'text') and text_to_find in shape.text:
                bold_check_passed = True
                if check_bold:
                    if hasattr(shape, 'text_frame'):
                        all_bold = True
                        has_runs = False
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                has_runs = True
                                if not run.font.bold:
                                    all_bold = False
                                    break
                            if not all_bold:
                                break
                        if not has_runs or not all_bold:
                            bold_check_passed = False
                border_check_passed = False
                if hasattr(shape, 'line'):
                    line = shape.line
                    if hasattr(line, 'fill') and line.fill.type is not None:
                        if hasattr(line, 'color') and hasattr(line.color, 'rgb'):
                            try:
                                rgb = line.color.rgb
                                if rgb[0] > 200 and rgb[1] < 100 and (rgb[2] < 100):
                                    border_check_passed = True
                            except:
                                pass
                    if hasattr(line, 'width') and line.width is not None and (line.width > 0):
                        try:
                            if hasattr(line.fill, 'fore_color'):
                                rgb = line.fill.fore_color.rgb
                                if rgb[0] > 200 and rgb[1] < 100 and (rgb[2] < 100):
                                    border_check_passed = True
                        except:
                            pass
                if bold_check_passed and border_check_passed:
                    return 1.0
        return 0.0
    except Exception as e:
        return 0.0

