def check_ppt_body_alignment__510fd9e5(result_file, expected, **options):
    """
    Check if text in specified shape has correct alignment.
    
    Args:
        result_file: Path to PPTX file
        expected: Dict with slide_index, shape_index, alignment ("left", "center", "right")
        
    Returns:
        float: 1.0 if alignment matches expectation, 0.0 otherwise
    """
    slide_index = expected.get('slide_index', 0)
    shape_index = expected.get('shape_index', 0)
    expected_alignment = expected.get('alignment', 'left').lower()
    alignment_map = {'left': PP_ALIGN.LEFT, 'center': PP_ALIGN.CENTER, 'right': PP_ALIGN.RIGHT}
    expected_align_enum = alignment_map.get(expected_alignment)
    if expected_align_enum is None:
        return 0.0
    try:
        prs = Presentation(result_file)
        slide = prs.slides[slide_index]
        shape = slide.shapes[shape_index]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        paragraphs = list(shape.text_frame.paragraphs)
        if not paragraphs:
            return 0.0
        for paragraph in paragraphs:
            if paragraph.alignment != expected_align_enum:
                return 0.0
        return 1.0
    except Exception as e:
        print(f'Error checking alignment: {e}')
        return 0.0

def check_slide_aspect_ratio__f6dd5f557dc0a56ec77be15757b662d5(pptx_path, expected, **options):
    """Check if slides have the expected aspect ratio.

    Args:
        pptx_path: Path to the PowerPoint file
        expected: Dict with 'width_ratio' and 'height_ratio' (e.g., {"width_ratio": 4, "height_ratio": 3})
        **options: Additional options including 'tolerance' (default: 0.02)

    Returns:
        float: 1.0 if aspect ratio matches (within tolerance), 0.0 otherwise
    """
    presentation = Presentation(pptx_path)
    slide_height = presentation.slide_height
    slide_width = presentation.slide_width
    expected_width_ratio = expected.get('width_ratio', 4)
    expected_height_ratio = expected.get('height_ratio', 3)
    tolerance = options.get('tolerance', 0.02)
    actual_ratio = slide_width / slide_height
    expected_ratio = expected_width_ratio / expected_height_ratio
    if abs(actual_ratio - expected_ratio) / expected_ratio <= tolerance:
        return 1.0
    return 0.0

