def check_slide_bg_color__d7a7efb9(file_path, expected, **options):
    """
    Check if a specific slide background matches the expected RGB color.

    Args:
        file_path: Path to the PPTX file
        expected: Dict with 'slide_index' (0-based) and 'expected_rgb' (tuple/list of 3 ints)
        **options: Additional options

    Returns:
        float: 1.0 if background matches expected RGB, 0.0 otherwise
    """
    slide_index = expected.get('slide_index', 0)
    expected_rgb = expected.get('expected_rgb', [])
    if isinstance(expected_rgb, list):
        expected_rgb = tuple(expected_rgb)
    try:
        prs = Presentation(file_path)
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        bg_fill = slide.background.fill
        bg_rgb = None
        if bg_fill.type == MSO_FILL_TYPE.SOLID:
            try:
                bg_rgb = tuple(bg_fill.fore_color.rgb)
            except:
                pass
        elif bg_fill.type == 5:
            try:
                master_fill = slide.slide_layout.slide_master.background.fill
                if master_fill.type == MSO_FILL_TYPE.SOLID:
                    bg_rgb = tuple(master_fill.fore_color.rgb)
            except:
                pass
        if bg_rgb is None:
            return 0.0
        if bg_rgb == expected_rgb:
            return 1.0
        else:
            return 0.0
    except Exception:
        return 0.0

