def check_slide_bg_and_notes__ebe0a2e3(result: Dict, expected: Dict, **options) -> float:
    """
    Check if slide has correct background color and notes text (variation 9).

    Args:
        result: Dict with 'background_rgb' and 'notes_text' from getter
        expected: Dict with 'background_rgb' (tuple) and 'expected_notes' (str)
        **options: Additional options like 'color_tolerance'

    Returns:
        float: Score from 0.0 to 1.0 (0.5 for bg only, 0.5 for notes, 1.0 for both)
    """
    score = 0.0
    expected_rgb = expected.get('background_rgb')
    expected_notes = expected.get('expected_notes', '').strip()
    color_tolerance = options.get('color_tolerance', 10)
    result_rgb = result.get('background_rgb')
    if result_rgb and expected_rgb:
        (r1, g1, b1) = result_rgb
        (r2, g2, b2) = expected_rgb
        distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
        if distance <= color_tolerance:
            score += 0.5
    elif result_rgb == expected_rgb:
        score += 0.5
    result_notes = result.get('notes_text', '').strip()
    if result_notes == expected_notes:
        score += 0.5
    return score

def check_pptx_font_sizes__bcd304c2(result, expected, **options):
    """Check if font sizes match expected sizes.

    Args:
        result: List of font sizes from getter
        expected: Dict with 'font_sizes' key (list of expected sizes in points)
        **options: Additional options (tolerance for size comparison)

    Returns:
        float: 1.0 if all match, 0.0 otherwise
    """
    expected_sizes = expected.get('font_sizes', [])
    tolerance = options.get('tolerance', 0.5)
    if len(result) != len(expected_sizes):
        return 0.0
    for (actual, expected_size) in zip(result, expected_sizes):
        if actual is None or expected_size is None:
            if actual != expected_size:
                return 0.0
        elif abs(actual - expected_size) > tolerance:
            return 0.0
    return 1.0

def check_pptx_state__7f279c8d(result, expected, **options):
    """Check PowerPoint slide state for variation 2.
    
    Args:
        result: dict with slide state from getter
        expected: dict with expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    total_checks = 0
    if 'background_color' in expected:
        total_checks += 1
        result_bg = result.get('background_color', '').upper()
        expected_bg = expected['background_color'].upper()
        if result_bg == expected_bg:
            score += 1.0
    if 'notes_text' in expected:
        total_checks += 1
        result_notes = result.get('notes', '').strip()
        expected_notes = expected['notes_text'].strip()
        if result_notes == expected_notes:
            score += 1.0
    title_fmt = result.get('title_formatting', {})
    if 'title_bold' in expected:
        total_checks += 1
        if title_fmt.get('bold') == expected['title_bold']:
            score += 1.0
    if 'title_italic' in expected:
        total_checks += 1
        if title_fmt.get('italic') == expected['title_italic']:
            score += 1.0
    if 'title_underline' in expected:
        total_checks += 1
        is_underlined = title_fmt.get('underline') is True
        if is_underlined == expected['title_underline']:
            score += 1.0
    if 'font_size' in expected:
        total_checks += 1
        result_size = title_fmt.get('size')
        expected_size_emu = expected['font_size'] * 12700
        if result_size and abs(result_size - expected_size_emu) < 1000:
            score += 1.0
    if 'font_name' in expected:
        total_checks += 1
        if title_fmt.get('name') == expected['font_name']:
            score += 1.0
    if 'title_color' in expected:
        total_checks += 1
        result_color = (title_fmt.get('color') or '').upper()
        expected_color = expected['title_color'].upper()
        if result_color == expected_color:
            score += 1.0
    if 'alignment' in expected:
        total_checks += 1
        from pptx.enum.text import PP_ALIGN
        result_align = title_fmt.get('alignment')
        align_map = {'left': PP_ALIGN.LEFT, 'center': PP_ALIGN.CENTER, 'right': PP_ALIGN.RIGHT}
        expected_align = align_map.get(expected['alignment'].lower())
        if result_align is None:
            result_align = PP_ALIGN.LEFT
        if result_align == expected_align:
            score += 1.0
    return score / total_checks if total_checks > 0 else 0.0

