def check_pptx_shapes_swapped__3b2512e8(result_file, expected, **options):
    """
    Check if two shapes have swapped positions.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing 'slide_idx', 'shape1_idx', 'shape2_idx', 'shape1_original_top', 'shape2_original_top'
        **options: Additional options

    Returns:
        float: 1.0 if shapes are swapped, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape1_idx = expected.get('shape1_idx', 0)
        shape2_idx = expected.get('shape2_idx', 0)
        shape1_original_top = expected.get('shape1_original_top')
        shape2_original_top = expected.get('shape2_original_top')
        approximately_tolerance = options.get('approximately_tolerance', 0.005)

        def is_approximately_equal(val1, val2, tolerance=approximately_tolerance):
            """Compare two values with a tolerance."""
            if val1 == val2:
                return True
            if val1 == 0 and val2 == 0:
                return True
            if val1 == 0 or val2 == 0:
                return False
            return abs(val1 - val2) / max(abs(val1), abs(val2)) <= tolerance
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape1_idx >= len(slide.shapes) or shape2_idx >= len(slide.shapes):
            return 0.0
        shape1 = slide.shapes[shape1_idx]
        shape2 = slide.shapes[shape2_idx]
        shape1_at_shape2_pos = is_approximately_equal(shape1.top, shape2_original_top, tolerance=0.1)
        shape2_at_shape1_pos = is_approximately_equal(shape2.top, shape1_original_top, tolerance=0.1)
        if shape1_at_shape2_pos and shape2_at_shape1_pos:
            return 1.0
        return 0.0
    except Exception as e:
        return 0.0

def check_pptx_text_content__462c40a4(result, expected, **options):
    """Check if text content matches expected strings.

    Args:
        result: List of text strings from getter
        expected: Dict with 'texts' key (list of expected strings)
        **options: Additional options (case_sensitive)

    Returns:
        float: 1.0 if all match, 0.0 otherwise
    """
    expected_texts = expected.get('texts', [])
    case_sensitive = options.get('case_sensitive', True)
    if len(result) != len(expected_texts):
        return 0.0
    for (actual, expected_text) in zip(result, expected_texts):
        if case_sensitive:
            if actual != expected_text:
                return 0.0
        elif actual.lower() != expected_text.lower():
            return 0.0
    return 1.0

