def check_pptx_multi_underline__d7b174d7(result_file, expected, **options):
    """Check if multiple texts are underlined (partial credit)"""
    try:
        prs = Presentation(result_file)
        checks = expected.get('checks', [])
        score = 0.0
        per_check_score = 1.0 / len(checks) if checks else 0.0
        for check in checks:
            slide_idx = check.get('slide_index', 0)
            text_to_check = check.get('text_to_check', '')
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            text_shapes = get_all_text_shapes(slide)
            found_underlined = False
            for shape in text_shapes:
                if hasattr(shape, 'text_frame'):
                    text = shape.text_frame.text.strip()
                    if text_to_check in text:
                        for para in shape.text_frame.paragraphs:
                            for run in para.runs:
                                if text_to_check in run.text and run.font.underline:
                                    found_underlined = True
                                    break
                        if found_underlined:
                            break
                if found_underlined:
                    break
            if found_underlined:
                score += per_check_score
        return score
    except Exception as e:
        return 0.0

def check_ppt_body_underline__32236819(result_file, expected, **options):
    """
    Check if ALL text in specified shape is underlined.

    Args:
        result_file: Path to PPTX file
        expected: Dict with slide_index, shape_index, should_be_underlined

    Returns:
        float: 1.0 if all text runs are underlined as expected, 0.0 otherwise
    """
    slide_index = expected.get('slide_index', 0)
    shape_index = expected.get('shape_index', 0)
    should_be_underlined = expected.get('should_be_underlined', True)
    try:
        prs = Presentation(result_file)
        slide = prs.slides[slide_index]
        shape = slide.shapes[shape_index]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        all_underlined = True
        has_text = False
        for paragraph in shape.text_frame.paragraphs:
            for run in paragraph.runs:
                if run.text.strip():
                    has_text = True
                    if not run.font.underline:
                        all_underlined = False
                        break
            if not all_underlined:
                break
        if not has_text:
            all_underlined = False
        return 1.0 if all_underlined == should_be_underlined else 0.0
    except Exception as e:
        print(f'Error checking underline: {e}')
        return 0.0

def check_pptx_textbox_alignments__b2033302e52d0b8158d22a9787c73b9a(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if textbox alignments match expected values.

    Args:
        result: Dict mapping slide keys to alignment strings (e.g., {'slide_3': 'left', 'slide_4': 'center'})
        expected: Dict with 'alignments' key containing expected slide->alignment mapping
        **options: Additional options (partial_credit: bool)

    Returns:
        Score between 0.0 and 1.0
    """
    expected_alignments = expected.get('alignments', {})
    partial_credit = options.get('partial_credit', True)
    if not expected_alignments:
        return 0.0
    total_slides = len(expected_alignments)
    correct = 0
    for (slide_key, expected_align) in expected_alignments.items():
        actual_align = result.get(slide_key, '')
        if actual_align == expected_align:
            correct += 1
    if partial_credit:
        return correct / total_slides if total_slides > 0 else 0.0
    else:
        return 1.0 if correct == total_slides else 0.0

def check_pptx_shape_heights__715d9dd6fa491d76c11177b41ddb49a3(result, expected, **options):
    """Compare actual shape heights against expected heights.

    Args:
        result: Dict mapping shape keys to actual heights in cm
        expected: Dict with 'heights' containing expected height values
        **options: Additional options (tolerance for height comparison)

    Returns:
        float: Score between 0.0 and 1.0 (partial credit for each correct height)
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    expected_heights = expected.get('heights', {})
    if not expected_heights:
        return 0.0
    tolerance_cm = options.get('tolerance_cm', 0.5)
    score = 0.0
    total_checks = len(expected_heights)
    for (shape_key, expected_height) in expected_heights.items():
        actual_height = result.get(shape_key)
        if actual_height is not None:
            if abs(actual_height - expected_height) <= tolerance_cm:
                score += 1.0 / total_checks
    return round(score, 3)

