def check_pptx_image_size_increased__7c7c452e(file1_path, file2_path, **options):
    """
    Check if an image on a specific slide has been enlarged.

    Args:
        file1_path: Path to result PPTX file
        file2_path: Path to expected/original PPTX file (not used, kept for compatibility)
        **options: Options including slide_index, shape_index, original_size, and tolerance

    Returns:
        float: 1.0 if image is larger than original, 0.0 otherwise
    """
    slide_index = options.get('slide_index', 1)
    shape_index = options.get('shape_index', 2)
    original_width = options.get('original_width', 2158920)
    original_height = options.get('original_height', 2158920)
    min_increase_ratio = options.get('min_increase_ratio', 1.3)
    try:
        prs = Presentation(file1_path)
        if len(prs.slides) <= slide_index:
            logger.error(f'Slide {slide_index} does not exist')
            return 0.0
        slide = prs.slides[slide_index]
        if len(slide.shapes) <= shape_index:
            logger.error(f'Shape {shape_index} does not exist on slide {slide_index}')
            return 0.0
        shape = slide.shapes[shape_index]
        if shape.shape_type != 13:
            logger.error(f'Shape {shape_index} is not a picture')
            return 0.0
        width_ratio = shape.width / original_width
        height_ratio = shape.height / original_height
        if width_ratio >= min_increase_ratio and height_ratio >= min_increase_ratio:
            logger.info(f'Image size increased (width ratio={width_ratio:.2f}, height ratio={height_ratio:.2f})')
            return 1.0
        else:
            logger.info(f'Image size not sufficiently increased (width ratio={width_ratio:.2f}, height ratio={height_ratio:.2f}, required={min_increase_ratio})')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking PPTX image size: {e}')
        return 0.0

