def check_pptx_font_size__e04152fb(file_path, expected, **options):
    """
    Check if all text in the PowerPoint has the specified font size.

    Args:
        file_path: Path to the modified PPTX file
        expected: Expected rules with 'font_size_pt' key (in points)
        **options: Additional options (not used)

    Returns:
        float: 1.0 if all text has the specified font size, 0.0 otherwise
    """
    try:
        prs = Presentation(file_path)
        target_size = Pt(expected.get('font_size_pt', 18))
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                    if shape.text.strip():
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                if run.text.strip():
                                    if run.font.size != target_size:
                                        return 0.0
                if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
                    table = shape.table
                    for row in table.rows:
                        for cell in row.cells:
                            if cell.text.strip():
                                for paragraph in cell.text_frame.paragraphs:
                                    for run in paragraph.runs:
                                        if run.text.strip():
                                            if run.font.size != target_size:
                                                return 0.0
        return 1.0
    except Exception as e:
        return 0.0

