def check_pptx_bold__45c2eeb2(result, expected, **options):
    """Check if specific textboxes have bold formatting.
    
    Args:
        result: Path to the PPTX file
        expected: Dict with 'bold_checks' containing list of checks
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        prs = Presentation(result)
        bold_checks = expected.get('bold_checks', [])
        if not bold_checks:
            return 0.0
        score = 0.0
        per_check_score = 1.0 / len(bold_checks)
        for check in bold_checks:
            slide_idx = check['slide_idx']
            shape_idx = check['shape_idx']
            should_be_bold = check['should_be_bold']
            group_shape_idx = check.get('group_shape_idx', None)
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            if shape_idx >= len(slide.shapes):
                continue
            shape = slide.shapes[shape_idx]
            if group_shape_idx is not None:
                if hasattr(shape, 'shapes') and group_shape_idx < len(shape.shapes):
                    shape = shape.shapes[group_shape_idx]
                else:
                    continue
            if not hasattr(shape, 'text_frame'):
                continue
            if shape.text_frame.paragraphs:
                para = shape.text_frame.paragraphs[0]
                if para.runs:
                    run = para.runs[0]
                    is_bold = run.font.bold
                    if is_bold is None:
                        is_bold = False
                    if is_bold == should_be_bold:
                        score += per_check_score
        return score
    except Exception as e:
        return 0.0

def check_slide_bg_exists__6e30323e5f83fac15a6aaf119946e46a(result, expected, **options):
    """Check if a NEW slide background image was added.

    This metric verifies that:
    1. A background image now exists on the slide
    2. The background image is different from the initial state (i.e., it's newly added)

    Args:
        result: Dict from getter with 'has_background', 'bg_image_id', and 'bg_image_data'
        expected: Expected boolean value (should be True)
        **options: Additional options, may contain 'initial_state' for comparison

    Returns:
        float: 1.0 if new background was added, 0.0 otherwise
    """
    if not isinstance(result, dict):
        return 0.0
    if not result.get('has_background', False):
        return 0.0
    initial_state = options.get('initial_state')
    if initial_state:
        initial_has_bg = initial_state.get('has_background', False)
        initial_bg_id = initial_state.get('bg_image_id')
        current_bg_id = result.get('bg_image_id')
        if not initial_has_bg:
            return 1.0
        initial_bg_data = initial_state.get('bg_image_data')
        current_bg_data = result.get('bg_image_data')
        if initial_bg_data is not None and current_bg_data is not None:
            if initial_bg_data != current_bg_data:
                return 1.0
            else:
                return 0.0
        if initial_bg_id != current_bg_id:
            return 1.0
        else:
            return 0.0
    else:
        return 1.0 if result.get('has_background') else 0.0

def check_pptx_table__f4287042fa68d8dbaeefa457a06c60a3(result, expected, **options):
    """
    Check if a PowerPoint slide has a table with expected dimensions.

    Args:
        result: dict from getter with 'has_table', 'rows', 'cols'
        expected: dict with 'rows' and 'cols' (expected table dimensions)
        **options: Additional options

    Returns:
        float: 1.0 if table exists with correct dimensions, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    if not result.get('has_table', False):
        return 0.0
    expected_rows = expected.get('rows', 0)
    expected_cols = expected.get('cols', 0)
    actual_rows = result.get('rows', 0)
    actual_cols = result.get('cols', 0)
    if actual_rows == expected_rows and actual_cols == expected_cols:
        return 1.0
    return 0.0

def check_pptx_para_level__f38803c04234b0b6005fa5d64a1f90e1(result: Dict[str, int], expected: Dict[str, Any], **options) -> float:
    """Check if paragraph indentation levels match expected values.

    Args:
        result: Dict mapping paragraph text to its level (from getter)
        expected: Rules dict with:
            - text_levels: Dict mapping text strings to expected levels
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    text_levels = expected.get('text_levels', {})
    if not text_levels:
        return 0.0
    total_checks = len(text_levels)
    correct = 0
    for (text, expected_level) in text_levels.items():
        for (result_text, result_level) in result.items():
            if text.lower() in result_text.lower():
                if result_level == expected_level:
                    correct += 1
                break
    return correct / total_checks if total_checks > 0 else 0.0

def check_slide_count_and_title__680b196663aaf427a16d93e155ddc42b(result, expected, **options):
    """Check if the slide count and title match expected values.

    Args:
        result: Dict with 'slide_count' and 'title' from getter
        expected: Dict with expected 'slide_count' and 'title'
        **options: Additional comparison options

    Returns:
        float: 1.0 if both match, 0.5 if only count matches, 0.0 otherwise
    """
    expected_count = expected.get('slide_count', 0)
    expected_title = expected.get('title', '')
    count_match = result.get('slide_count', 0) == expected_count
    title_match = result.get('title', '').strip() == expected_title.strip()
    if count_match and title_match:
        return 1.0
    elif count_match:
        return 0.5
    return 0.0

def check_pptx_image_size__e6b29cfda7e055fe712654f4e89e7782(result, expected, **options):
    """Check if a PowerPoint slide contains an image with the expected size and metadata.

    Args:
        result: dict from getter with image information
        expected: dict with 'slide_index', 'expected_width_cm', 'expected_height_cm',
                  and optionally 'expected_checksum'
        **options: Additional options (tolerance, verify_checksum)

    Returns:
        float: Score between 0.0 and 1.0
    """
    tolerance = options.get('tolerance', 0.01)
    verify_checksum = options.get('verify_checksum', True)
    expected_width = expected.get('expected_width_cm')
    expected_height = expected.get('expected_height_cm')
    expected_checksum = expected.get('expected_checksum')
    if not result or 'image_count' not in result:
        return 0.0
    if result['image_count'] == 0:
        return 0.0
    images = result.get('images', [])
    for img in images:
        width_cm = img['width_cm']
        height_cm = img['height_cm']
        width_match = abs(width_cm - expected_width) / expected_width <= tolerance
        height_match = abs(height_cm - expected_height) / expected_height <= tolerance
        if not (width_match and height_match):
            continue
        if verify_checksum and expected_checksum:
            metadata = img.get('metadata', {})
            img_checksum = metadata.get('checksum')
            if img_checksum and img_checksum == expected_checksum:
                return 1.0
            elif img_checksum is None:
                return 0.8
        else:
            return 1.0
    return 0.0

def check_pptx_font_size__1bff8456a9cb83a8068f2dc2e82443fd(result, expected, **options):
    """Compare PowerPoint font size against expected value.

    Args:
        result: Font size in points (float) from getter
        expected: Expected font size in points (float) from rules
        **options: Additional comparison options

    Returns:
        float: 1.0 if sizes match within tolerance, 0.0 otherwise
    """
    if result is None:
        return 0.0
    expected_size = expected.get('font_size')
