def check_pptx_image_size__524afb99(result, expected, **options):
    """
    Check if none.png image with specific dimensions exists in the result.

    Args:
        result: List of image info dicts from getter
        expected: Dict with 'width', 'height' in EMUs, optional 'tolerance', 'source_image_path'
        **options: Additional options

    Returns:
        float: 1.0 if none.png image found with correct size, 0.0 otherwise
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    target_width = expected.get('width')
    target_height = expected.get('height')
    tolerance = expected.get('tolerance', 0.01)
    source_image_path = expected.get('source_image_path')
    source_hash = None
    if source_image_path and os.path.exists(source_image_path):
        try:
            with open(source_image_path, 'rb') as f:
                source_hash = hashlib.md5(f.read()).hexdigest()
        except:
            pass
    for img in result:
        width = img.get('width', 0)
        height = img.get('height', 0)
        if target_width > 0 and target_height > 0:
            width_diff = abs(width - target_width) / target_width
            height_diff = abs(height - target_height) / target_height
            if width_diff <= tolerance and height_diff <= tolerance:
                embedded_name = img.get('embedded_name', '').lower()
                if 'none' in embedded_name:
                    return 1.0
                if source_hash and img.get('image_hash') == source_hash:
                    return 1.0
                matching_images = [i for i in result if target_width > 0 and target_height > 0 and (abs(i.get('width', 0) - target_width) / target_width <= tolerance) and (abs(i.get('height', 0) - target_height) / target_height <= tolerance)]
                if len(matching_images) == 1:
                    return 1.0
    return 0.0

