def check_ppt_title_size__928aede8(result, expected, **options):
    """Check if title font size in specified slides matches expected values.

    Args:
        result: Dict from getter - {slide_idx: {property: value}}
        expected: Dict with expected values per slide
        **options: Additional options (size_tolerance: float)

    Returns:
        float: Score between 0.0 and 1.0
    """
    target_slides = expected.get('target_slides', [])
    expected_size = expected.get('expected_size', 60.0)
    size_tolerance = options.get('size_tolerance', 2.0)
    if not target_slides:
        return 0.0
    correct_count = 0
