def check_pptx_aspect_ratio__38452e24283563a92e35abc383c587f4(result, expected, **options):
    """Check if image maintains specific aspect ratio and minimum width.

    Args:
        result: Dict with 'width', 'height', 'aspect_ratio' from getter
        expected: Dict with 'min_width' and 'target_aspect_ratio'
        **options: Additional options (aspect_tolerance for aspect ratio tolerance)

    Returns:
        float: Partial credit based on width achievement and aspect ratio maintenance
    """
    if not result or not expected:
        return 0.0
    result_width = result.get('width', 0)
    result_aspect = result.get('aspect_ratio', 0.0)
    min_width = expected.get('min_width', 0)
    target_aspect = expected.get('target_aspect_ratio', 0.0)
    aspect_tolerance = options.get('aspect_tolerance', 0.05)
    score = 0.0
    if result_width >= min_width * 0.95:
        score += 0.5
    if target_aspect > 0:
        aspect_diff = abs(result_aspect - target_aspect) / target_aspect
        if aspect_diff <= aspect_tolerance:
            score += 0.5
    return score

def check_ppt_formatting__7a54655e(result_file, expected, **options):
    """
    Check PowerPoint formatting for specific task requirements:
    - Slide 1: subtitle 'Marketing' should be italic and underlined
    - Slide 2: title 'How to Use This Presentation' should be dark blue color

    Args:
        result_file: Path to the PPTX file
        expected: Dict with 'type' and 'rules' containing verification rules
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on partial credit for completed requirements
    """
    try:
        prs = Presentation(result_file)
        slide1_shape_text = expected.get('slide1_shape_text', 'Marketing')
        slide1_italic = expected.get('slide1_italic', True)
        slide1_underline = expected.get('slide1_underline', True)
        slide2_title_text = expected.get('slide2_title_text', 'How to Use This Presentation')
        slide2_color_check = expected.get('slide2_color_check', 'dark_blue')
        score = 0.0
        total_checks = 3
        if len(prs.slides) < 1:
            return 0.0
        slide1 = prs.slides[0]
        marketing_found = False
        marketing_italic = False
        marketing_underline = False
        for shape in slide1.shapes:
            if hasattr(shape, 'text_frame'):
                text = shape.text.strip()
                if slide1_shape_text in text:
                    marketing_found = True
                    all_italic = True
                    all_underline = True
                    has_runs = False
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if slide1_shape_text in run.text:
                                has_runs = True
                                if not run.font.italic is True:
                                    all_italic = False
                                if run.font.underline is None or run.font.underline is False:
                                    all_underline = False
                    if has_runs:
                        if all_italic and slide1_italic:
                            marketing_italic = True
                            score += 1.0 / total_checks
                        if all_underline and slide1_underline:
                            marketing_underline = True
                            score += 1.0 / total_checks
                    break
        if not marketing_found:
            logger.warning(f'Marketing subtitle not found on slide 1')
        if len(prs.slides) < 2:
            return score
        slide2 = prs.slides[1]
        title_color_correct = False
        for shape in slide2.shapes:
            if hasattr(shape, 'text_frame'):
                text = shape.text.strip()
                if slide2_title_text in text:
                    all_dark_blue = True
                    has_runs = False
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.text.strip():
                                has_runs = True
                                if hasattr(run.font.color, 'rgb'):
                                    rgb = run.font.color.rgb
                                    (r, g, b) = (rgb[0], rgb[1], rgb[2])
                                    if slide2_color_check == 'dark_blue':
                                        if not (b > r and b > g and (b > 50) and (r < 100) and (g < 100)):
                                            all_dark_blue = False
                                            break
                                else:
                                    all_dark_blue = False
                                    break
                        if not all_dark_blue:
                            break
                    if has_runs and all_dark_blue:
                        title_color_correct = True
                        score += 1.0 / total_checks
                    break
        if not title_color_correct:
            logger.warning(f'Title on slide 2 does not have dark blue color')
        return score
    except Exception as e:
        logger.error(f'Error checking PPT formatting: {e}')
        return 0.0

