    if not expected_sizes or not result:
        return 0.0
    total_checks = len(expected_sizes)
    correct_count = 0
    for (i, expected_size) in enumerate(expected_sizes):
        if i < len(result) and result[i] is not None:
            if abs(result[i] - expected_size) <= tolerance:
                correct_count += 1
    return correct_count / total_checks if total_checks > 0 else 0.0

