def check_pptx_combined__0b87a6f8(result_file, expected, **options):
    """
    Check multiple conditions on different slides with partial scoring.

    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with 'checks' list containing multiple check definitions
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 based on how many checks pass
    """
    try:
        prs = Presentation(result_file)
        checks = expected.get('checks', [])
        if not checks:
            return 0.0
        passed_checks = 0
        total_checks = len(checks)
        for check in checks:
            check_type = check.get('type', '')
            if check_type == 'picture_height':
                slide_idx = check.get('slide_idx', 0)
                target_height_cm = check.get('target_height_cm', 0)
                if slide_idx < len(prs.slides):
                    slide = prs.slides[slide_idx]
                    pictures = [shape for shape in slide.shapes if shape.shape_type == 13]
                    if pictures:
                        all_match = True
                        tolerance = 0.5
                        for pic in pictures:
                            actual_height_cm = pic.height / 360000.0
                            if abs(actual_height_cm - target_height_cm) > tolerance:
                                all_match = False
                                break
                        if all_match:
                            passed_checks += 1
            elif check_type == 'font_size':
                slide_idx = check.get('slide_idx', 0)
                text_content = check.get('text_content', '')
                target_font_size_pt = check.get('target_font_size_pt', 0)
                if slide_idx < len(prs.slides):
                    slide = prs.slides[slide_idx]

                    def get_all_text_shapes(shapes):
                        results = []
                        for shape in shapes:
                            if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                                results.append(shape)
                            if hasattr(shape, 'shapes'):
                                results.extend(get_all_text_shapes(shape.shapes))
                        return results
                    text_shapes = get_all_text_shapes(slide.shapes)
                    matching_shape = None
                    for shape in text_shapes:
                        if shape.text.strip() == text_content.strip():
                            matching_shape = shape
                            break
                    if matching_shape:
                        all_match = True
                        for para in matching_shape.text_frame.paragraphs:
                            for run in para.runs:
                                if run.font.size:
                                    actual_pt = run.font.size.pt
                                    if abs(actual_pt - target_font_size_pt) > 1.0:
                                        all_match = False
                                        break
                            if not all_match:
                                break
                        if all_match:
                            passed_checks += 1
        return passed_checks / total_checks
    except Exception as e:
        return 0.0

