def check_pptx_textbox_alignments__d39413a216d84867d5d6965b44978f32(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if textbox alignments match expected values.

    Args:
        result: Dict mapping slide_tb keys to alignment strings (e.g., {'slide_3_tb2': 'right', 'slide_5_tb0': 'left'})
        expected: Dict with 'alignments' key containing expected slide_tb->alignment mapping
        **options: Additional options (partial_credit: bool)

    Returns:
        Score between 0.0 and 1.0
    """
    expected_alignments = expected.get('alignments', {})
    partial_credit = options.get('partial_credit', True)
    if not expected_alignments:
        return 0.0
    total_slides = len(expected_alignments)
    correct = 0
    for (slide_key, expected_align) in expected_alignments.items():
        actual_align = result.get(slide_key, '')
        if actual_align == expected_align:
            correct += 1
    if partial_credit:
        return correct / total_slides if total_slides > 0 else 0.0
    else:
        return 1.0 if correct == total_slides else 0.0

