def check_pptx_all_formatting__3a4ba0b3(result, expected, **options):
    """Check if all formatting properties match expected values.

    Args:
        result: List of formatting dicts from getter
        expected: Dict with 'formatting' key
        **options: Additional options

    Returns:
        float: Partial credit based on matching properties
    """
    expected_formatting = expected.get('formatting', [])
    if len(result) != len(expected_formatting):
        return 0.0
    total_checks = 0
    passed_checks = 0
    for (actual, expected_fmt) in zip(result, expected_formatting):
        for key in ['bold', 'italic', 'underline', 'color', 'font_size']:
            if key in expected_fmt:
                total_checks += 1
                if key == 'font_size' and expected_fmt[key] is not None and (actual.get(key) is not None):
                    if abs(actual.get(key) - expected_fmt[key]) <= 0.5:
                        passed_checks += 1
                elif actual.get(key) == expected_fmt[key]:
                    passed_checks += 1
    return passed_checks / total_checks if total_checks > 0 else 0.0

