def check_pptx_duplicated_slides__dcfe9b2a84e70142b88044298f3d84a3(result, expected, **options):
    """Check if specific slides were duplicated correctly.

    Args:
        result: Slide information from getter
        expected: Expected configuration with original_slides and target_positions

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or 'slides' not in result:
        return 0.0
    slides = result['slides']
    original_count = expected.get('original_count', 0)
    duplicated_indices = expected.get('duplicated_indices', [])
    expected_final_count = expected.get('expected_final_count', 0)
    if result['slide_count'] != expected_final_count:
        return 0.0
    score = 0.0
    if result['slide_count'] == expected_final_count:
        score += 0.5
    if len(duplicated_indices) >= 2:
        (idx1, idx2) = (duplicated_indices[0], duplicated_indices[1])
        if idx1 < len(slides) and idx2 < len(slides):
            slide1_orig = slides[idx1]
            slide2_orig = slides[idx2]
            copy1_pos = idx2 + 1
            copy2_pos = idx2 + 2
            if copy1_pos < len(slides) and copy2_pos < len(slides):
                slide1_copy = slides[copy1_pos]
                slide2_copy = slides[copy2_pos]
                texts_match_1 = slide1_orig.get('texts', []) == slide1_copy.get('texts', [])
                texts_match_2 = slide2_orig.get('texts', []) == slide2_copy.get('texts', [])
                if texts_match_1 and texts_match_2:
                    score += 0.5
    return score

def check_pptx_content_align_bold__8f8be55e(result_file, expected, **options):
    """
    Check if the content text in a PowerPoint slide is center-aligned and bold.

    This function verifies that:
    1. ALL content paragraph(s) have center alignment (PP_ALIGN.CENTER = 2)
    2. ALL content text runs are bold (font.bold = True)

    Args:
        result_file: Path to the PPTX file to check
        expected: Rules dictionary containing:
            - 'alignment': Expected alignment value (2 for CENTER)
            - 'bold': Expected bold state (True for bold)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
            - 1.0: All requirements met (all content center-aligned + bold)
            - 0.5: Only one requirement met (either all aligned or all bold)
            - 0.0: No requirements met or missing requirements
    """
    try:
        prs = Presentation(result_file)
        expected_alignment = expected.get('alignment', 2)
        expected_bold = expected.get('bold', True)
        if len(prs.slides) == 0:
            return 0.0
        slide = prs.slides[0]
        content_paragraphs = []
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and hasattr(shape, 'text'):
                if shape.text.strip():
                    for paragraph in shape.text_frame.paragraphs:
                        if paragraph.text.strip():
                            content_paragraphs.append(paragraph)
        if not content_paragraphs:
            return 0.0
        all_aligned = True
        all_bold = True
        for paragraph in content_paragraphs:
            para_alignment = paragraph.alignment
            is_centered = para_alignment == PP_ALIGN.CENTER or (isinstance(expected_alignment, int) and para_alignment == expected_alignment)
            if not is_centered:
                all_aligned = False
            paragraph_is_bold = True
            if paragraph.runs:
                for run in paragraph.runs:
                    if run.text.strip():
                        if run.font.bold is not True:
                            paragraph_is_bold = False
                            break
            else:
                paragraph_is_bold = False
            if not paragraph_is_bold:
                all_bold = False
        score = 0.0
        if all_aligned:
            score += 0.5
        if all_bold:
            score += 0.5
        return score
    except Exception as e:
        logger.error(f'Error checking PPTX content alignment and bold: {e}')
        return 0.0

