def check_pptx_duplicate_slide__e2ea8085(result, expected, **options):
    """Check if a slide has been duplicated at the expected position.

    Args:
        result: Structure dict from getter
        expected: Expected values with slide_count, original_index, duplicate_index, expected_title
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_count = expected.get('slide_count', 0)
    if result.get('slide_count', 0) == expected_count:
        score += 0.5
    titles = result.get('titles', [])
    original_index = expected.get('original_index', -1)
    duplicate_index = expected.get('duplicate_index', -1)
    expected_title = expected.get('expected_title', '')
    if original_index >= 0 and duplicate_index >= 0:
        if original_index < len(titles) and duplicate_index < len(titles):
            original_title = titles[original_index]
            duplicate_title = titles[duplicate_index]
            if expected_title.lower() in original_title.lower() and expected_title.lower() in duplicate_title.lower():
                score += 0.5
    return min(score, 1.0)

def check_ppt_title_color__0789c969(result, expected, **options):
    """Check if title colors in specified slides match expected values.

    Args:
        result: Dict from getter - {slide_idx: {property: value}}
        expected: Dict with expected values per slide
        **options: Additional options (strict: bool, color_tolerance: int)

    Returns:
        float: Score between 0.0 and 1.0
    """
    target_slides = expected.get('target_slides', [])
    expected_color = expected.get('expected_color')
    color_tolerance = options.get('color_tolerance', 20)
    if not target_slides:
        return 0.0
    correct_count = 0
    total_count = len(target_slides)
    for slide_idx in target_slides:
        if slide_idx not in result:
            continue
        actual_color = result[slide_idx].get('color')
        if actual_color == expected_color:
            correct_count += 1
        elif actual_color and expected_color:
            actual_rgb = tuple((int(actual_color[i:i + 2], 16) for i in (1, 3, 5)))
            expected_rgb = tuple((int(expected_color[i:i + 2], 16) for i in (1, 3, 5)))
            diff = sum((abs(a - e) for (a, e) in zip(actual_rgb, expected_rgb)))
            if diff <= color_tolerance * 3:
                correct_count += 1
    return correct_count / total_count if total_count > 0 else 0.0

