def check_pptx_image_size__4238ec90(result_file, expected, **options):
    """
    Check if PPTX file has an image with expected dimensions and name on specified slide.

    Args:
        result_file: Path to the PPTX file
        expected: Dictionary with rules containing:
            - slide_index: 0-based slide index
            - expected_width_cm: Expected width in cm
            - expected_height_cm: Expected height in cm
            - tolerance_cm: Tolerance in cm (default 0.05)
            - expected_image_name: Optional expected image name (e.g., 'none.png')
        **options: Additional options

    Returns:
        float: 1.0 if image found with matching size and name, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_index = expected.get('slide_index', 0)
        expected_width_cm = expected.get('expected_width_cm', 0)
        expected_height_cm = expected.get('expected_height_cm', 0)
        tolerance_cm = expected.get('tolerance_cm', 0.05)
        expected_image_name = expected.get('expected_image_name', None)
        if slide_index >= len(prs.slides):
            logger.error(f'Slide index {slide_index} out of range (presentation has {len(prs.slides)} slides)')
            return 0.0
        slide = prs.slides[slide_index]
        expected_width_emu = expected_width_cm * 360000
        expected_height_emu = expected_height_cm * 360000
        tolerance_emu = tolerance_cm * 360000
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.PICTURE or shape.shape_type == 13:
                width_match = abs(shape.width - expected_width_emu) <= tolerance_emu
                height_match = abs(shape.height - expected_height_emu) <= tolerance_emu
                if width_match and height_match:
                    if expected_image_name:
                        image_name = None
                        try:
                            if hasattr(shape, 'name') and shape.name:
                                image_name = shape.name
                            if hasattr(shape, 'image') and hasattr(shape.image, 'filename'):
                                image_filename = shape.image.filename
                                if image_filename:
                                    image_name = image_filename
                        except Exception as e:
                            logger.warning(f'Could not retrieve image name: {e}')
                        if image_name:
                            if expected_image_name.lower() in image_name.lower():
                                actual_width_cm = shape.width / 360000
                                actual_height_cm = shape.height / 360000
                                logger.info(f"Found matching image '{image_name}' on slide {slide_index + 1}: {actual_width_cm:.2f}cm x {actual_height_cm:.2f}cm (expected {expected_width_cm}cm x {expected_height_cm}cm)")
                                return 1.0
                            else:
                                logger.debug(f"Image dimensions match but name '{image_name}' does not contain '{expected_image_name}'")
                                continue
                        else:
                            logger.debug(f'Image dimensions match but could not retrieve image name')
                            continue
                    else:
                        actual_width_cm = shape.width / 360000
                        actual_height_cm = shape.height / 360000
                        logger.info(f'Found matching image on slide {slide_index + 1}: {actual_width_cm:.2f}cm x {actual_height_cm:.2f}cm (expected {expected_width_cm}cm x {expected_height_cm}cm)')
                        return 1.0
        if expected_image_name:
            logger.error(f"No image named '{expected_image_name}' with dimensions {expected_width_cm}cm x {expected_height_cm}cm found on slide {slide_index + 1}")
        else:
            logger.error(f'No image with dimensions {expected_width_cm}cm x {expected_height_cm}cm found on slide {slide_index + 1}')
        return 0.0
    except Exception as e:
        logger.error(f'Error checking image size: {e}')
        return 0.0

def check_slide_bg_and_notes__3c5b0027(result: Dict, expected: Dict, **options) -> float:
    """
    Check if slide has correct background color and notes text (variation 0).

    Args:
        result: Dict with 'background_rgb' and 'notes_text' from getter
        expected: Dict with 'background_rgb' (tuple) and 'expected_notes' (str)
        **options: Additional options like 'color_tolerance'

    Returns:
        float: Score from 0.0 to 1.0 (0.5 for bg only, 0.5 for notes, 1.0 for both)
    """
    score = 0.0
    expected_rgb = expected.get('background_rgb')
    expected_notes = expected.get('expected_notes', '').strip()
    color_tolerance = options.get('color_tolerance', 10)
    result_rgb = result.get('background_rgb')
    if result_rgb and expected_rgb:
        (r1, g1, b1) = result_rgb
        (r2, g2, b2) = expected_rgb
        distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
        if distance <= color_tolerance:
            score += 0.5
    elif result_rgb == expected_rgb:
        score += 0.5
    result_notes = result.get('notes_text', '').strip()
    if result_notes == expected_notes:
        score += 0.5
    return score

