def check_pptx_table_position__3b2512e8(result_file, expected, **options):
    """
    Check if a table shape in a specific slide is at the expected position.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing 'slide_idx', 'shape_idx', 'min_top', 'max_top'
        **options: Additional options including 'approximately_tolerance'

    Returns:
        float: 1.0 if position matches (within tolerance), 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 0)
        min_top = expected.get('min_top', None)
        max_top = expected.get('max_top', None)
        min_left = expected.get('min_left', None)
        max_left = expected.get('max_left', None)
        approximately_tolerance = options.get('approximately_tolerance', 0.005)

        def is_approximately_equal(val1, val2, tolerance=approximately_tolerance):
            """Compare two values with a tolerance."""
            if val1 == val2:
                return True
            if val1 == 0 and val2 == 0:
                return True
            if val1 == 0 or val2 == 0:
                return False
            return abs(val1 - val2) / max(abs(val1), abs(val2)) <= tolerance
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if min_top is not None and shape.top < min_top:
            if not is_approximately_equal(shape.top, min_top):
                return 0.0
        if max_top is not None and shape.top > max_top:
            if not is_approximately_equal(shape.top, max_top):
                return 0.0
        if min_left is not None and shape.left < min_left:
            if not is_approximately_equal(shape.left, min_left):
                return 0.0
        if max_left is not None and shape.left > max_left:
            if not is_approximately_equal(shape.left, max_left):
                return 0.0
        return 1.0
    except Exception as e:
        return 0.0

def check_pptx_slide2_and_slide6_fonts__83b1733b066f0d4e3751aa29bdc2f040(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if slide 2 instruction fonts match AND slide 6 title font matches.

    This metric checks two conditions with partial credit:
    - 0.5 points: ALL instruction textboxes on slide 2 have the expected font size
    - 0.5 points: "Our Founder" title on slide 6 has the expected font size

    Args:
        result: Dict containing 'slide2_fonts' (list of font sizes) and 'slide6_font' (font size)
        expected: Dict with 'target_slide2_font' and 'target_slide6_font'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    slide2_fonts = result.get('slide2_fonts', [])
    target_slide2 = expected.get('target_slide2_font', 0)
    if slide2_fonts and target_slide2:
        all_match = True
        for font_size in slide2_fonts:
            if abs(font_size - target_slide2) >= 0.1:
                all_match = False
                break
        if all_match:
            score += 0.5
    slide6_font = result.get('slide6_font', 0)
    target_slide6 = expected.get('target_slide6_font', 0)
    if slide6_font and target_slide6:
        if abs(slide6_font - target_slide6) < 0.1:
            score += 0.5
    return score

def check_slide_bg_and_notes__6025dd93(result: Dict, expected: Dict, **options) -> float:
    """
    Check if slide has correct background color and notes text (variation 8).

    Args:
        result: Dict with 'background_rgb' and 'notes_text' from getter
        expected: Dict with 'background_rgb' (tuple) and 'expected_notes' (str)
        **options: Additional options like 'color_tolerance'

    Returns:
        float: Score from 0.0 to 1.0 (0.5 for bg only, 0.5 for notes, 1.0 for both)
    """
    score = 0.0
    expected_rgb = expected.get('background_rgb')
    expected_notes = expected.get('expected_notes', '').strip()
    color_tolerance = options.get('color_tolerance', 10)
    result_rgb = result.get('background_rgb')
    if result_rgb and expected_rgb:
        (r1, g1, b1) = result_rgb
        (r2, g2, b2) = expected_rgb
        distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
        if distance <= color_tolerance:
            score += 0.5
    elif result_rgb == expected_rgb:
        score += 0.5
    result_notes = result.get('notes_text', '').strip()
    if result_notes == expected_notes:
        score += 0.5
    return score

def check_pptx_all_fonts__4525cb8d0a211ea4343ee095274a9830(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if all text in the presentation uses the expected font.
    
    Args:
        result: Dictionary from getter containing font information
        expected: Dictionary with 'target_font' key specifying the expected font name
        **options: Additional options (not used)
        
    Returns:
        float: 1.0 if all text uses the target font, 0.0 otherwise
    """
    if 'error' in result:
        return 0.0
    target_font = expected.get('target_font', '')
    if not target_font:
        return 0.0
