def check_pptx_picture_widths__bcfabaf7(result, expected, **options):
    """Compare picture widths against expected values.

    Args:
        result: dict from getter {slide_number: width_in_cm}
        expected: dict with 'rules' containing expected widths
        **options: tolerance (default 0.1cm)

    Returns:
        float: Score 0.0-1.0 with partial credit
    """
    if result is None:
        return 0.0
    expected_widths = expected.get('widths', {})
    tolerance = options.get('tolerance', 0.1)
    score = 0.0
    total_checks = len(expected_widths)
    for (slide_num, expected_width) in expected_widths.items():
        actual_width = result.get(slide_num)
        if actual_width is None:
            continue
        if abs(actual_width - expected_width) <= tolerance:
            score += 1.0 / total_checks
    return score

def check_slide_size_letter__4bd70d76(result_state, expected_state, **options):
    """
    Check if the slide size is Letter (8.5in x 11in).
    Letter in EMUs: width=7772400, height=9906000

    Args:
        result_state: Path to the PPTX file from vm_file getter
        expected_state: Expected state (rules list like ['slide_size_is_letter'])
        **options: Additional options

    Returns:
        float: 1.0 if slide size is Letter, 0.0 otherwise
    """
    try:
        file_path = result_state
        if not isinstance(file_path, str):
            return 0.0
        if not os.path.exists(file_path):
            return 0.0
        presentation = Presentation(file_path)
        actual_width = presentation.slide_width
        actual_height = presentation.slide_height
        if isinstance(expected_state, list) and 'slide_size_is_letter' in expected_state:
            letter_width = 7772400
            letter_height = 9906000
            tolerance = 0.01
            width_match = abs(actual_width - letter_width) / letter_width <= tolerance
            height_match = abs(actual_height - letter_height) / letter_height <= tolerance
            if width_match and height_match:
                return 1.0
            return 0.0
        else:
            letter_width = 7772400
            letter_height = 9906000
            tolerance = 0.01
            width_match = abs(actual_width - letter_width) / letter_width <= tolerance
            height_match = abs(actual_height - letter_height) / letter_height <= tolerance
            if width_match and height_match:
                return 1.0
            return 0.0
    except Exception as e:
        return 0.0

