def check_pptx_text_colors__1f4273f47ac63784ed95be4edfc1a7eb(result: Dict[str, Optional[str]], expected: Dict[str, Any], **options) -> float:
    """Compare actual text colors against expected colors with tolerance.

    This metric validates that:
    1. Each text element is uniformly colored (all runs have the same color)
    2. The color matches the expected color within the specified tolerance

    Args:
        result: Dict mapping shape index (str) to RGB color string or None
                - RGB string (e.g., "FF0000") if all runs have the same color
                - None if no color found or runs have inconsistent colors
        expected: Dict from config["rules"] containing "color_map"
                  Maps shape_idx (str) -> expected_rgb_string (e.g., "00008B")
        **options: Additional options:
                  - color_tolerance: Maximum allowed difference per RGB channel (default: 0)

    Returns:
        float: Score between 0.0 and 1.0
               - Partial credit: 1/total_count for each correctly colored element
               - 0.0 if a text element has None (inconsistent coloring)

    Example:
        result = {"0": "00008B", "1": "FF00FF", "4": None}  # Shape 4 has mixed colors
        expected = {"color_map": {"0": "00008B", "1": "FF00FF", "4": "00FF00"}}
        Returns: 2/3 = 0.67 (shapes 0 and 1 correct, shape 4 fails due to inconsistent colors)
    """
    color_map = expected.get('color_map', {})
    color_tolerance = options.get('color_tolerance', 0)
    if not color_map:
        return 0.0
    correct_count = 0
    total_count = len(color_map)
    for (shape_idx, expected_color) in color_map.items():
        actual_color = result.get(str(shape_idx))
        if actual_color is None or not actual_color:
            continue
        if color_tolerance == 0:
            if actual_color.upper() == expected_color.upper():
                correct_count += 1
        else:
            try:
                actual_r = int(actual_color[0:2], 16)
                actual_g = int(actual_color[2:4], 16)
                actual_b = int(actual_color[4:6], 16)
                expected_r = int(expected_color[0:2], 16)
                expected_g = int(expected_color[2:4], 16)
                expected_b = int(expected_color[4:6], 16)
                if abs(actual_r - expected_r) <= color_tolerance and abs(actual_g - expected_g) <= color_tolerance and (abs(actual_b - expected_b) <= color_tolerance):
                    correct_count += 1
            except:
                pass
    return correct_count / total_count if total_count > 0 else 0.0

def check_pptx_title_font_size__3daa6928(result, expected, **options):
    """Check if the title has the specified font size.

    Args:
        result: Path to the PPTX file
        expected: Dict with 'slide_index', 'title_text', and 'font_size_pt' keys
        **options: Additional options

    Returns:
        float: 1.0 if title has the expected font size, 0.0 otherwise
    """
    slide_index = expected.get('slide_index', 2)
    title_text = expected.get('title_text', 'Movie List')
    font_size_pt = expected.get('font_size_pt', 32)
    expected_size = Pt(font_size_pt)
    try:
        prs = Presentation(result)
        slide = prs.slides[slide_index]
        title_shape = None
        for shape in slide.shapes:
            if hasattr(shape, 'text') and title_text in shape.text:
                title_shape = shape
                break
        if title_shape is None:
            return 0.0
        for paragraph in title_shape.text_frame.paragraphs:
            for run in paragraph.runs:
                if run.font.size != expected_size:
                    return 0.0
        return 1.0
    except Exception as e:
        return 0.0

def check_ppt_body_bullet__411b97ea(result_file, expected, **options):
    """
    Check if text in specified shape has bullet points.
    
    Args:
        result_file: Path to PPTX file
        expected: Dict with slide_index, shape_index, should_have_bullet
        
    Returns:
        float: 1.0 if bullet matches expectation, 0.0 otherwise
    """
    slide_index = expected.get('slide_index', 0)
    shape_index = expected.get('shape_index', 0)
    should_have_bullet = expected.get('should_have_bullet', True)
    try:
        prs = Presentation(result_file)
        slide = prs.slides[slide_index]
        shape = slide.shapes[shape_index]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        has_bullet = False
        for paragraph in shape.text_frame.paragraphs:
            if hasattr(paragraph, '_element'):
                pPr = paragraph._element.pPr
                if pPr is not None:
                    for child in pPr:
                        if 'buChar' in child.tag:
                            has_bullet = True
                            break
                if has_bullet:
                    break
        return 1.0 if has_bullet == should_have_bullet else 0.0
    except Exception as e:
        print(f'Error checking bullet: {e}')
        return 0.0

def check_pptx_combined_notes__4ec81c89(result, expected, **options):
    """Check if slide 2 has combined notes and slide 3 is empty"""
    slide2_original = expected.get('slide2_original', '')
    slide3_original = expected.get('slide3_original', '')
    slide2_note = result.get('slide1', '')
    slide3_note = result.get('slide2', '')
    score = 0.0
    if not slide3_note.strip():
        score += 0.3
    slide2_original_stripped = slide2_original.strip()
    slide3_original_stripped = slide3_original.strip()
    has_slide2_content = slide2_original_stripped in slide2_note
    has_slide3_content = slide3_original_stripped in slide2_note
    if has_slide2_content and has_slide3_content:
        idx_slide2 = slide2_note.find(slide2_original_stripped)
        idx_slide3 = slide2_note.find(slide3_original_stripped)
        if idx_slide2 < idx_slide3:
            end_of_slide2 = idx_slide2 + len(slide2_original_stripped)
            between_text = slide2_note[end_of_slide2:idx_slide3]
            if '\n\n' in between_text:
                score += 0.7
            elif between_text.count('\n') >= 1:
                score += 0.5
            else:
                score += 0.4
        else:
            score += 0.35
    elif has_slide2_content or has_slide3_content:
        score += 0.2
    return score

def check_pptx_image_size__1d908c97(result, expected, **options):
    """
    Check if an image with specific dimensions exists in the result, and verify it's the expected image.

    Args:
        result: List of image info dicts from getter
        expected: Dict with 'width', 'height' in EMUs, optional 'tolerance', optional 'expected_image_path'
        **options: Additional options

    Returns:
        float: 1.0 if image found with correct size and identity, 0.0 otherwise
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    target_width = expected.get('width')
    target_height = expected.get('height')
    tolerance = expected.get('tolerance', 0.01)
    expected_image_path = expected.get('expected_image_path')
    expected_hash = None
    if expected_image_path:
        try:
            with open(expected_image_path, 'rb') as f:
                expected_hash = hashlib.md5(f.read()).hexdigest()
        except Exception:
            pass
    for img in result:
        width = img.get('width', 0)
        height = img.get('height', 0)
        if target_width > 0 and target_height > 0:
            width_diff = abs(width - target_width) / target_width
            height_diff = abs(height - target_height) / target_height
            if width_diff <= tolerance and height_diff <= tolerance:
                if expected_hash:
                    image_hash = img.get('image_hash')
                    if image_hash and image_hash == expected_hash:
                        return 1.0
                    elif image_hash:
                        continue
                if expected_image_path:
                    import os
                    expected_basename = os.path.splitext(os.path.basename(expected_image_path))[0].lower()
                    shape_name = img.get('name', '').lower()
                    if expected_basename in shape_name:
                        return 1.0
                else:
                    return 1.0
    return 0.0

