def check_pptx_font_size__1452cc07b597787abfe241ee1d6bb8ed(result, expected, **options):
    """Check if font sizes in specified slides match the expected size.

    Args:
        result: Dict from getter with slide indices mapping to list of font sizes
        expected: Dict with expected font size configuration
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    slides_to_check = expected.get('slides', [])
    target_size = expected.get('font_size', 18)
    tolerance = options.get('size_tolerance', 0.5)
    total_textboxes = 0
    matching_textboxes = 0
    for slide_idx in slides_to_check:
        if slide_idx not in result:
            continue
        textbox_font_sizes = result[slide_idx]
        for font_size in textbox_font_sizes:
            if font_size is None:
                continue
            total_textboxes += 1
            if abs(font_size - target_size) <= tolerance:
                matching_textboxes += 1
    if total_textboxes == 0:
        return 0.0
    return matching_textboxes / total_textboxes

