def check_ppt_background_color__4b272171bb4b7d46506f8b8d095c33b3(result, expected, **options):
    """Compare background color against expected RGB.

    Args:
        result: RGB tuple from getter
        expected: Dict with 'rgb' key containing expected RGB tuple
        **options: Additional comparison options (e.g., 'tolerance')

    Returns:
        float: 1.0 if colors match within tolerance, 0.0 otherwise
    """
    if result is None:
        return 0.0
    expected_rgb = expected.get('rgb', None)
    if expected_rgb is None:
        return 0.0
    if hasattr(result, '__iter__'):
        (r1, g1, b1) = (result[0], result[1], result[2])
    else:
        return 0.0
    (r2, g2, b2) = expected_rgb
    tolerance = options.get('color_tolerance', 0)
    if tolerance > 0:
        distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
        max_distance = sqrt(255 ** 2 + 255 ** 2 + 255 ** 2)
        similarity = 1 - distance / max_distance
        if distance <= tolerance:
            return 1.0
        else:
            return 0.0
    elif r1 == r2 and g1 == g2 and (b1 == b2):
        return 1.0
    else:
        return 0.0

def check_ppt_body_alignment__b66fc465(result_file, expected, **options):
    """
    Check if text in specified shape has correct alignment.
    
    Args:
        result_file: Path to PPTX file
        expected: Dict with slide_index, shape_index, alignment ("left", "center", "right")
        
    Returns:
        float: 1.0 if alignment matches expectation, 0.0 otherwise
    """
    slide_index = expected.get('slide_index', 0)
    shape_index = expected.get('shape_index', 0)
    expected_alignment = expected.get('alignment', 'left').lower()
    alignment_map = {'left': PP_ALIGN.LEFT, 'center': PP_ALIGN.CENTER, 'right': PP_ALIGN.RIGHT}
    expected_align_enum = alignment_map.get(expected_alignment)
    if expected_align_enum is None:
        return 0.0
    try:
        prs = Presentation(result_file)
        slide = prs.slides[slide_index]
        shape = slide.shapes[shape_index]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        for paragraph in shape.text_frame.paragraphs:
            if paragraph.alignment != expected_align_enum:
                return 0.0
        return 1.0
    except Exception as e:
        print(f'Error checking alignment: {e}')
        return 0.0

