def check_pptx_slide_title_color__9c5062f3(result_file, expected, **options):
    """
    Check if a specific slide has the expected title with the expected color.
    
    Args:
        result_file: Path to the PPTX file
        expected: Dict with 'slide_idx' (0-indexed), 'expected_title', and 'expected_color_rgb' tuple
        **options: Additional options
        
    Returns:
        float: Score (0.5 for title match only, 1.0 for title and color match, 0.0 otherwise)
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        expected_title = expected.get('expected_title', '')
        expected_color = expected.get('expected_color_rgb', None)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        title_shape = None
        for shape in slide.shapes:
            if shape.is_placeholder:
                try:
                    if shape.placeholder_format.type == 1:
                        title_shape = shape
                        break
                except:
                    pass
        if title_shape is None:
            for shape in slide.shapes:
                if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                    if shape.text.strip():
                        title_shape = shape
                        break
        if title_shape is None:
            return 0.0
        actual_title = title_shape.text.strip()
        if actual_title != expected_title:
            return 0.0
        score = 0.5
        if expected_color is not None:
            try:
                if title_shape.text_frame.paragraphs:
                    first_para = title_shape.text_frame.paragraphs[0]
                    if first_para.runs:
                        first_run = first_para.runs[0]
                        if hasattr(first_run.font.color, 'rgb') and first_run.font.color.rgb is not None:
                            actual_color = first_run.font.color.rgb
                            actual_rgb_tuple = (actual_color[0], actual_color[1], actual_color[2])
                            expected_rgb_tuple = tuple(expected_color)
                            if actual_rgb_tuple == expected_rgb_tuple:
                                score = 1.0
            except Exception:
                pass
        else:
            score = 1.0
        return score
    except Exception as e:
        return 0.0

def check_slide_background_match__024272f6(result_state, expected_state, **options):
    """
    Check if the saved image matches the background from the slide.

    This verifies:
    1. The saved image exists
    2. The saved image is in JPEG format
    3. The saved image content matches the slide background (via pixel similarity)
    4. The image dimensions are similar (allowing for compression/format conversion)

    Args:
        result_state: Dictionary from getter with hash, width, height, format info, and image data
        expected_state: Dictionary with expected criteria (format requirement)
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 based on match quality
    """
    if result_state is None:
        logger.warning('Result state is None, could not extract slide background or saved image')
        return 0.0
    saved_hash = result_state.get('saved_hash')
    saved_format = result_state.get('saved_format')
    saved_width = result_state.get('saved_width')
    saved_height = result_state.get('saved_height')
    saved_image_data = result_state.get('saved_image_data')
    expected_jpeg_hash = result_state.get('expected_jpeg_hash')
    expected_width = result_state.get('expected_width')
    expected_height = result_state.get('expected_height')
    expected_image_data = result_state.get('expected_image_data')
    if saved_hash is None or saved_image_data is None:
        logger.warning('Saved image not found')
        return 0.0
    required_format = expected_state.get('format', 'JPEG')
    if saved_format is None or saved_format.upper() != required_format.upper():
        logger.warning(f'Saved image format {saved_format} does not match required format {required_format}')
        return 0.0
    score = 0.0
    score += 0.2
    logger.info(f'Saved image is in correct format: {saved_format}')
    if saved_width and saved_height and expected_width and expected_height:
        width_ratio = min(saved_width, expected_width) / max(saved_width, expected_width)
        height_ratio = min(saved_height, expected_height) / max(saved_height, expected_height)
        if width_ratio >= 0.95 and height_ratio >= 0.95:
            score += 0.1
            logger.info(f'Image dimensions match closely: saved={saved_width}x{saved_height}, expected={expected_width}x{expected_height}')
        elif width_ratio >= 0.8 and height_ratio >= 0.8:
            score += 0.05
            logger.info(f'Image dimensions somewhat similar: saved={saved_width}x{saved_height}, expected={expected_width}x{expected_height}')
        else:
            logger.warning(f'Image dimensions differ significantly: saved={saved_width}x{saved_height}, expected={expected_width}x{expected_height}')
    try:
        expected_img = Image.open(BytesIO(expected_image_data)).convert('RGB')
        saved_img = Image.open(BytesIO(saved_image_data)).convert('RGB')
        if saved_img.size != expected_img.size:
            saved_img = saved_img.resize(expected_img.size, Image.LANCZOS)
            logger.info(f'Resized saved image to {expected_img.size} for comparison')
        expected_array = np.array(expected_img).astype(np.float32)
        saved_array = np.array(saved_img).astype(np.float32)
        mse = np.mean((expected_array - saved_array) ** 2)
        if mse < 100:
            content_score = 0.7
            logger.info(f'Excellent content match (MSE={mse:.2f})')
        elif mse < 500:
            content_score = 0.5
            logger.info(f'Good content match (MSE={mse:.2f})')
        elif mse < 1000:
            content_score = 0.3
            logger.info(f'Fair content match (MSE={mse:.2f})')
        else:
            content_score = 0.0
            logger.warning(f'Poor content match (MSE={mse:.2f})')
        score += content_score
    except Exception as e:
        logger.error(f'Error comparing image content: {e}')
        logger.warning('Could not perform content verification')
    logger.info(f'Final score: {score}')
    return score

def check_pptx_title_alignment__aac2cc9f(result, expected, **options):
    """Check if the title has the expected alignment and text.

    Args:
        result: Dict with 'alignment' and 'text' from getter
        expected: Dict with expected 'alignment' and 'text'
        **options: Additional options

    Returns:
        float: 1.0 if both alignment and text match, 0.5 if only one matches, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    result_alignment = result.get('alignment')
    result_text = result.get('text')
    expected_alignment = expected.get('alignment')
    expected_text = expected.get('text')
    if result_alignment is None or result_alignment == 'None':
        result_alignment = 'LEFT'
    if expected_alignment is None or expected_alignment == 'None':
        expected_alignment = 'LEFT'
    alignment_match = result_alignment == expected_alignment
    text_match = result_text == expected_text
    if alignment_match and text_match:
        return 1.0
    elif alignment_match or text_match:
        return 0.5
    else:
        return 0.0

