def check_ppt_title_formatting__7a68a4daba903cf2aa527fc4ca0f41c5(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if title formatting matches expected values for specified slides.

    Args:
        result: Dict from getter with slide formatting info
        expected: Dict with 'slides', 'color', 'bold', 'italic', 'underline' keys
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    slides = expected.get('slides', [])
    expected_color = expected.get('color')
    expected_bold = expected.get('bold')
    expected_italic = expected.get('italic')
    expected_underline = expected.get('underline')
    if not slides:
        return 0.0
    score = 0.0
    for slide_idx in slides:
        if slide_idx not in result:
            continue
        slide_info = result[slide_idx]
        slide_score = 0.0
        checks = 0
        if expected_color is not None:
            checks += 1
            actual_color = slide_info.get('color')
            if actual_color == expected_color:
                slide_score += 1.0
        if expected_bold is not None:
            checks += 1
            actual_bold = slide_info.get('bold')
            if expected_bold is True:
                if actual_bold is True:
                    slide_score += 1.0
            elif actual_bold is None or actual_bold is False:
                slide_score += 1.0
        if expected_italic is not None:
            checks += 1
            actual_italic = slide_info.get('italic')
            if expected_italic is True:
                if actual_italic is True:
                    slide_score += 1.0
            elif actual_italic is None or actual_italic is False:
                slide_score += 1.0
        if expected_underline is not None:
            checks += 1
            actual_underline = slide_info.get('underline')
            if expected_underline is True:
                if actual_underline is True:
                    slide_score += 1.0
            elif actual_underline is None or actual_underline is False:
                slide_score += 1.0
        if checks > 0:
            score += slide_score / checks
    return score / len(slides) if slides else 0.0

def check_pptx_bold_italic__55228546(file_path, expected, **options):
    """
    Check if all text (including table text) in the PowerPoint is bold and italic.

    Args:
        file_path: Path to the modified PPTX file
        expected: Expected rules (not used for this check, should be empty dict)
        **options: Additional options (not used)

    Returns:
        float: 1.0 if all text is bold and italic, 0.0 otherwise
    """
    try:
        prs = Presentation(file_path)
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                    if shape.text.strip():
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                if run.text.strip():
                                    if not run.font.bold:
                                        return 0.0
                                    if not run.font.italic:
                                        return 0.0
                if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
                    table = shape.table
                    for row in table.rows:
                        for cell in row.cells:
                            if cell.text.strip():
                                for paragraph in cell.text_frame.paragraphs:
                                    for run in paragraph.runs:
                                        if run.text.strip():
                                            if not run.font.bold:
                                                return 0.0
                                            if not run.font.italic:
                                                return 0.0
        return 1.0
    except Exception as e:
        return 0.0

