def check_pptx_title_props__203d7ee2(result, expected, **options):
    """Check if PowerPoint title(s) have expected font properties.

    Args:
        result: Font properties dict/list from getter
        expected: Expected properties dict
        **options: Additional options (color_tolerance)

    Returns:
        float: Score between 0.0 and 1.0 (partial credit for each property)
    """
    if isinstance(result, list):
        if not result or None in result:
            return 0.0
        total_score = 0.0
        for title_props in result:
            total_score += check_single_title(title_props, expected, **options)
        return total_score / len(result)
