def check_pptx_formatting__b78d2c08(result, expected, **options):
    """Check if text formatting matches expected values.
    
    Args:
        result: Dict of formatting data from getter
        expected: Dict with 'slide_indices' and format-specific expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    check_type = expected.get('check_type', 'bold')
    expected_value = expected.get('expected_value')
    slide_indices = expected.get('slide_indices', [])
    total_runs = 0
    matching_runs = 0
    for (key, fmt) in result.items():
        (slide_idx, shape_idx, para_idx, run_idx) = key
        if slide_idx not in slide_indices:
            continue
        if not fmt['text'].strip():
            continue
        total_runs += 1
        if check_type == 'bold':
            if fmt['bold'] == expected_value:
                matching_runs += 1
        elif check_type == 'italic':
            if fmt['italic'] == expected_value:
                matching_runs += 1
        elif check_type == 'underline':
            actual = fmt['underline']
            if expected_value is True:
                if actual is True:
                    matching_runs += 1
            elif actual is None or actual is False:
                matching_runs += 1
        elif check_type == 'font_size':
            if fmt['size'] is not None and abs(fmt['size'] - expected_value) < 0.5:
                matching_runs += 1
        elif check_type == 'color':
            if fmt['color'] == expected_value:
                matching_runs += 1
        elif check_type == 'alignment':
            align_map = {'CENTER': PP_ALIGN.CENTER, 'RIGHT': PP_ALIGN.RIGHT, 'LEFT': PP_ALIGN.LEFT}
            expected_align = align_map.get(expected_value)
            actual_align = fmt['alignment']
            if actual_align is None:
                actual_align = PP_ALIGN.LEFT
            if actual_align == expected_align:
                matching_runs += 1
        elif check_type == 'bold_italic':
            if fmt['bold'] == expected_value and fmt['italic'] == expected_value:
                matching_runs += 1
        elif check_type == 'size_underline':
            size_match = fmt['size'] is not None and abs(fmt['size'] - expected_value['size']) < 0.5
            underline_match = fmt['underline'] is True if expected_value['underline'] else fmt['underline'] is None or fmt['underline'] is False
            if size_match and underline_match:
                matching_runs += 1
        elif check_type == 'bold_color':
            bold_match = fmt['bold'] == expected_value['bold']
            color_match = fmt['color'] == expected_value['color']
            if bold_match and color_match:
                matching_runs += 1
    if total_runs == 0:
        return 0.0
    return matching_runs / total_runs

def check_pptx_modifications__4028451d(result_file, expected, **options):
    """
    Check PowerPoint modifications for variation 6.

    Verifies:
    - ALL image dimensions (width/height) on specified slides must match
    - ALL text font sizes on specified slides must match

    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with slide indices and expected values
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (0.5 for images, 0.5 for text)
    """
    try:
        prs = Presentation(result_file)
        score = 0.0
        total_checks = 0
        tolerance_cm = options.get('tolerance_cm', 0.5)
        tolerance_pt = options.get('tolerance_pt', 2.0)
        if 'image_slide_idx' in expected:
            total_checks += 1
            image_slide_idx = expected['image_slide_idx']
            if image_slide_idx < len(prs.slides):
                slide = prs.slides[image_slide_idx]
                images = [shape for shape in slide.shapes if shape.shape_type == 13]
                if not images:
                    print(f'Image check: No images found on slide {image_slide_idx + 1}')
                else:
                    all_images_match = True
                    images_checked = 0
                    images_passed = 0
                    for img in images:
                        images_checked += 1
                        img_match = True
                        if 'expected_width_cm' in expected:
                            width_cm = img.width / 360000
                            expected_width = expected['expected_width_cm']
                            if abs(width_cm - expected_width) > tolerance_cm:
                                print(f'Image check: Image {images_checked} width {width_cm:.2f}cm != expected {expected_width:.2f}cm')
                                img_match = False
                                all_images_match = False
                        if 'expected_height_cm' in expected:
                            height_cm = img.height / 360000
                            expected_height = expected['expected_height_cm']
                            if abs(height_cm - expected_height) > tolerance_cm:
                                print(f'Image check: Image {images_checked} height {height_cm:.2f}cm != expected {expected_height:.2f}cm')
                                img_match = False
                                all_images_match = False
                        if img_match:
                            images_passed += 1
                    print(f'Image check: {images_passed}/{images_checked} images passed on slide {image_slide_idx + 1}')
                    if all_images_match:
                        score += 0.5
                        print(f'Image check: PASSED - All images match expected dimensions')
                    else:
                        print(f'Image check: FAILED - Not all images match expected dimensions ({images_passed}/{images_checked})')
            else:
                print(f'Image check: Slide index {image_slide_idx} out of range (total slides: {len(prs.slides)})')
        if 'text_slide_idx' in expected:
            total_checks += 1
            text_slide_idx = expected['text_slide_idx']
            if text_slide_idx < len(prs.slides):
                slide = prs.slides[text_slide_idx]
                expected_font_size = expected.get('expected_font_size', None)
                if expected_font_size:
                    text_shapes = [shape for shape in slide.shapes if hasattr(shape, 'text_frame')]
                    if not text_shapes:
                        print(f'Text check: No text shapes found on slide {text_slide_idx + 1}')
                    else:
                        total_runs = 0
                        matching_runs = 0
                        text_found = False
                        for shape in text_shapes:
                            for paragraph in shape.text_frame.paragraphs:
                                for run in paragraph.runs:
                                    if run.font.size:
                                        text_found = True
                                        total_runs += 1
                                        font_size_pt = run.font.size.pt
                                        if abs(font_size_pt - expected_font_size) <= tolerance_pt:
                                            matching_runs += 1
                                        else:
                                            print(f'Text check: Found text with font size {font_size_pt:.1f}pt != expected {expected_font_size:.1f}pt')
                        if not text_found:
                            print(f'Text check: No text with font size found on slide {text_slide_idx + 1}')
                        else:
                            print(f'Text check: {matching_runs}/{total_runs} text runs with expected font size on slide {text_slide_idx + 1}')
                            if matching_runs == total_runs:
                                score += 0.5
                                print(f'Text check: PASSED - All text matches expected font size')
                            else:
                                print(f'Text check: FAILED - Not all text matches expected font size ({matching_runs}/{total_runs})')
            else:
                print(f'Text check: Slide index {text_slide_idx} out of range (total slides: {len(prs.slides)})')
        print(f'Final score: {score:.2f}')
        return score
    except Exception as e:
        print(f'Error checking PPTX: {e}')
        import traceback
        traceback.print_exc()
        return 0.0

