def check_slide_summary__ad193ef5756ae344b25ad0ec2621d4b0(result, expected, **options):
    """Check if extracted slide summary matches expected summary.

    Args:
        result: List of tuples (slide_number, title) from getter
        expected: Dict with 'expected_summary' key containing list of expected (number, title) tuples
        **options: Additional options (not used)

    Returns:
        float: Score based on how many entries match (0.0 to 1.0)
    """
    if not isinstance(result, list):
        return 0.0
    expected_summary = expected.get('expected_summary', [])
    if not expected_summary:
        return 0.0
    if len(result) != len(expected_summary):
        pass
    matched = 0
    for (exp_num, exp_title) in expected_summary:
        for (res_num, res_title) in result:
            if res_num == exp_num:
                res_title_norm = ' '.join(res_title.lower().split())
                exp_title_norm = ' '.join(exp_title.lower().split())
                if res_title_norm == exp_title_norm:
                    matched += 1
                break
    return matched / len(expected_summary) if expected_summary else 0.0

