def check_slide_duplication__41578a1e(result_file, expected, **options):
    """
    Check if a slide was duplicated by verifying total slide count and comparing slide content.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing 'expected_total_slides' and 'duplicate_slide_idx'
        **options: Additional options

    Returns:
        float: 1.0 if duplication is correct, partial credit for partial success, 0.0 for failure
    """
    try:
        prs = Presentation(result_file)
        actual_count = len(prs.slides)
        expected_count = expected.get('expected_total_slides', 0)
        duplicate_idx = expected.get('duplicate_slide_idx', 0)
        score = 0.0
        if actual_count == expected_count:
            score += 0.5
        else:
            return 0.0
        if duplicate_idx + 1 < len(prs.slides):
            slide1 = prs.slides[duplicate_idx]
            slide2 = prs.slides[duplicate_idx + 1]
            text1 = []
            text2 = []
            for shape in slide1.shapes:
                if hasattr(shape, 'text'):
                    text1.append(shape.text.strip())
            for shape in slide2.shapes:
                if hasattr(shape, 'text'):
                    text2.append(shape.text.strip())
            if sorted(text1) == sorted(text2) and len(text1) > 0:
                score += 0.5
        return score
    except Exception as e:
        return 0.0

def check_pptx_text_colors__a2fe0faa332aa822166f451f641c8ac6(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Compare actual text colors against expected colors.

    Args:
        result: Dict mapping shape index to RGB color string
        expected: Dict from config["rules"] containing "color_map"
                  (dict of shape_idx -> expected_rgb_string)
        **options: Additional options (e.g., color_tolerance)

    Returns:
        float: Score between 0.0 and 1.0 (partial credit for each correct color)
    """
    color_map = expected.get('color_map', {})
    color_tolerance = options.get('color_tolerance', 0)
    if not color_map:
        return 0.0
    correct_count = 0
    total_count = len(color_map)
    for (shape_idx, expected_color) in color_map.items():
        actual_color = result.get(str(shape_idx), '')
        if not actual_color:
            continue
        if color_tolerance == 0:
            if actual_color.upper() == expected_color.upper():
                correct_count += 1
        else:
            try:
                actual_r = int(actual_color[0:2], 16)
                actual_g = int(actual_color[2:4], 16)
                actual_b = int(actual_color[4:6], 16)
                expected_r = int(expected_color[0:2], 16)
                expected_g = int(expected_color[2:4], 16)
                expected_b = int(expected_color[4:6], 16)
                if abs(actual_r - expected_r) <= color_tolerance and abs(actual_g - expected_g) <= color_tolerance and (abs(actual_b - expected_b) <= color_tolerance):
                    correct_count += 1
            except:
                pass
    return correct_count / total_count if total_count > 0 else 0.0

