def check_pptx_property__f8098831(result, expected, **options):
    """
    Compare paragraph property against expected value.

    Args:
        result: Property value from getter
        expected: Expected value or dict of expected values
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass)
    """
    if result is None:
        return 0.0
    property_type = expected.get('property', 'italic')
    expected_value = expected.get('value')
    if property_type in ['level', 'alignment']:
        if isinstance(result, int):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type in ['bold', 'italic', 'underline']:
        if isinstance(result, bool):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type == 'color':
        if isinstance(result, list) and len(result) == 3:
            expected_rgb = expected_value
            if isinstance(expected_rgb, list) and len(expected_rgb) == 3:
                return 1.0 if result == expected_rgb else 0.0
        return 0.0
    elif property_type == 'bold_italic':
        if isinstance(result, dict):
            bold_match = result.get('bold', False) == expected_value
            italic_match = result.get('italic', False) == expected_value
            return 1.0 if bold_match and italic_match else 0.0
        return 0.0
    return 0.0

def check_ppt_body_italic__444c9c6d(result_file, expected, **options):
    """
    Check if text in specified shape is italic.
    
    Args:
        result_file: Path to PPTX file
        expected: Dict with slide_index, shape_index, should_be_italic
        
    Returns:
        float: 1.0 if italic matches expectation, 0.0 otherwise
    """
    slide_index = expected.get('slide_index', 0)
    shape_index = expected.get('shape_index', 0)
    should_be_italic = expected.get('should_be_italic', True)
    try:
        prs = Presentation(result_file)
        slide = prs.slides[slide_index]
        shape = slide.shapes[shape_index]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        has_any_text = False
        all_italic = True
        for paragraph in shape.text_frame.paragraphs:
            for run in paragraph.runs:
                if not run.text or run.text.strip() == '':
                    continue
                has_any_text = True
                if not run.font.italic:
                    all_italic = False
                    break
            if not all_italic:
                break
        if not has_any_text:
            all_italic = False
        return 1.0 if all_italic == should_be_italic else 0.0
    except Exception as e:
        print(f'Error checking italic: {e}')
        return 0.0

def check_pptx_slide_images__612fc9a7(result: Dict[str, Any], expected: Any, **options) -> float:
    """Check if PowerPoint has correct number of slides and images per slide.

    Args:
        result: Dict from getter with 'slide_count' and 'images_per_slide'
        expected: Dict with 'slide_count' and 'images_per_slide' (expected list)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    expected_slides = expected.get('slide_count', 0)
    actual_slides = result.get('slide_count', 0)
    if actual_slides == expected_slides:
        score += 0.5
    expected_images = expected.get('images_per_slide', [])
    actual_images = result.get('images_per_slide', [])
    if len(expected_images) > 0:
        matching_slides = 0
        for i in range(min(len(expected_images), len(actual_images))):
            if actual_images[i] == expected_images[i]:
                matching_slides += 1
        image_score = matching_slides / len(expected_images)
        score += 0.5 * image_score
    return score

