def check_pptx_property__9c1760d9(result, expected, **options):
    """
    Compare paragraph property against expected value.

    Args:
        result: Property value from getter
        expected: Expected value or dict of expected values
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass)
    """
    if result is None:
        return 0.0
    property_type = expected.get('property', 'level')
    expected_value = expected.get('value')
    if property_type in ['level', 'alignment']:
        if isinstance(result, int):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type in ['bold', 'italic', 'underline']:
        if isinstance(result, bool):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type == 'color':
        if isinstance(result, list) and len(result) == 3:
            expected_rgb = expected_value
            if isinstance(expected_rgb, list) and len(expected_rgb) == 3:
                return 1.0 if result == expected_rgb else 0.0
        return 0.0
    elif property_type == 'bold_italic':
        if isinstance(result, dict):
            bold_match = result.get('bold', False) == expected_value
            italic_match = result.get('italic', False) == expected_value
            return 1.0 if bold_match and italic_match else 0.0
        return 0.0
    return 0.0

def check_ppt_properties__8824138a(result, expected, **options):
    """
    Check if PPT properties match expected values.

    Args:
        result: Dict with properties from getter
        expected: Dict with expected properties
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    score = 0.0
    total_checks = 0
    for (key, expected_value) in expected.items():
        total_checks += 1
        if key in result:
            actual_value = result[key]
            if key.endswith('_color'):
                if actual_value == expected_value:
                    score += 1.0
            elif isinstance(expected_value, bool):
                actual_normalized = actual_value if actual_value is not None else False
                expected_normalized = expected_value if expected_value is not None else False
                if actual_normalized == expected_normalized:
                    score += 1.0
            elif actual_value == expected_value:
                score += 1.0
    if total_checks == 0:
        return 0.0
    return score / total_checks

def check_pptx_specific_slides__a7147238(result, expected, **options):
    """Check if presentation has correct slides with expected content.
    
    Args:
        result: Path to the PPTX file
        expected: Dict with 'slide_count', 'slide_0_title', 'slide_1_title', 'slide_2_text'
        **options: Additional options
        
    Returns:
        float: Partial credit based on correctness (0.33, 0.67, or 1.0)
    """
    try:
        slide_count = expected.get('slide_count', 0)
        slide_0_title = expected.get('slide_0_title', '')
        slide_1_title = expected.get('slide_1_title', '')
        slide_2_text = expected.get('slide_2_text', '')
        prs = Presentation(result)
        actual_count = len(prs.slides)
        if actual_count != slide_count:
            return 0.0
        score = 0.33
        if actual_count >= 2:
            slide_0 = prs.slides[0]
            slide_1 = prs.slides[1]
            found_slide_0 = any((slide_0_title in shape.text for shape in slide_0.shapes if hasattr(shape, 'text')))
            found_slide_1 = any((slide_1_title in shape.text for shape in slide_1.shapes if hasattr(shape, 'text')))
            if found_slide_0 and found_slide_1:
                score = 0.67
        if actual_count >= 3:
            slide_2 = prs.slides[2]
            found_slide_2 = any((slide_2_text in shape.text for shape in slide_2.shapes if hasattr(shape, 'text')))
            if score >= 0.67 and found_slide_2:
                score = 1.0
        return score
    except Exception as e:
        print(f'Error checking specific slides: {e}')
        return 0.0

