def check_pptx_text_color__461d3947(result_state, expected_state, **options):
    """
    Check if the text color of a specific text on a specific slide matches the expected RGB value.
    This function searches for a shape containing the target text 'ADD AN AGENDA PAGE' instead of
    using a hardcoded shape index.

    Args:
        result_state: Path to the result PPTX file
        expected_state: Dictionary containing:
            - slide_index: The slide index (0-indexed)
            - shape_index: The shape index (0-indexed) - used as fallback only
            - expected_rgb: The expected RGB color as a list [R, G, B] (0-255)
        **options: Additional options

    Returns:
        float: 1.0 if text color matches expected RGB value, 0.0 otherwise
    """
    try:
        from pptx.enum.dml import MSO_COLOR_TYPE
        slide_index = expected_state.get('slide_index')
        shape_index = expected_state.get('shape_index')
        expected_rgb = expected_state.get('expected_rgb')
        if slide_index is None or expected_rgb is None:
            logger.error(f'Missing required parameters: slide_index={slide_index}, expected_rgb={expected_rgb}')
            return 0.0
        if not isinstance(expected_rgb, list) or len(expected_rgb) != 3:
            logger.error(f'Invalid expected_rgb format: {expected_rgb}, expected [R, G, B]')
            return 0.0
        presentation = Presentation(result_state)
        if slide_index < 0 or slide_index >= len(presentation.slides):
            logger.error(f'Invalid slide index: {slide_index}, total slides: {len(presentation.slides)}')
            return 0.0
        slide = presentation.slides[slide_index]
        target_text = 'ADD AN AGENDA PAGE'
        target_shape = None
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                shape_text = shape.text_frame.text.strip()
                if target_text in shape_text.upper():
                    target_shape = shape
                    logger.debug(f"Found target text '{target_text}' in shape with text: {shape_text}")
                    break
        if target_shape is None:
            if shape_index is not None:
                logger.warning(f"Target text '{target_text}' not found, using fallback shape_index={shape_index}")
                if shape_index < 0 or shape_index >= len(slide.shapes):
                    logger.error(f'Invalid shape index: {shape_index}, total shapes on slide {slide_index}: {len(slide.shapes)}')
                    return 0.0
                target_shape = slide.shapes[shape_index]
            else:
                logger.error(f"Target text '{target_text}' not found on slide {slide_index} and no shape_index provided")
                return 0.0
        if not hasattr(target_shape, 'text_frame'):
            logger.error(f'Target shape on slide {slide_index} does not have a text frame')
            return 0.0
        text_frame = target_shape.text_frame
        total_runs = 0
        runs_with_expected_color = 0
        runs_checked = 0
        for paragraph in text_frame.paragraphs:
            for run in paragraph.runs:
                total_runs += 1
                run_text = run.text.strip()
                if not run_text:
                    continue
                runs_checked += 1
                if run.font.color.type == MSO_COLOR_TYPE.RGB:
                    rgb_color = run.font.color.rgb
                    actual_rgb = [rgb_color[0], rgb_color[1], rgb_color[2]]
                    if actual_rgb == expected_rgb:
                        runs_with_expected_color += 1
                        logger.debug(f"Run with text '{run_text[:30]}...' has expected color {expected_rgb}")
                    else:
                        logger.debug(f"Run with text '{run_text[:30]}...' has color {actual_rgb}, expected {expected_rgb}")
                else:
                    logger.debug(f"Run with text '{run_text[:30]}...' has non-RGB color type: {run.font.color.type}")
        if runs_checked == 0:
            logger.error(f'No non-empty text runs found in target shape on slide {slide_index}')
            return 0.0
        if runs_with_expected_color > 0:
            logger.debug(f'Found {runs_with_expected_color} out of {runs_checked} runs with expected color')
            return 1.0
        else:
            logger.debug(f'No runs have the expected RGB color {expected_rgb}')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking text color: {e}')
        return 0.0

def check_slide_b5_size__125b9c8e(result_state, expected_state, **options):
    """Check if slides are set to B5 paper size (176mm x 250mm).

    Args:
        result_state: Path to the PowerPoint file
        expected_state: Expected slide dimensions dict with 'width' and 'height' in EMU
        **options: Additional options

    Returns:
        1.0 if slide size matches B5, 0.0 otherwise
    """
    try:
        presentation = Presentation(result_state)
        slide_width = presentation.slide_width
        slide_height = presentation.slide_height
        expected_width = expected_state.get('width')
        expected_height = expected_state.get('height')
        tolerance = 0.01
        width_match = abs(slide_width - expected_width) / expected_width < tolerance
        height_match = abs(slide_height - expected_height) / expected_height < tolerance
        if width_match and height_match:
            return 1.0
        return 0.0
    except Exception as e:
        print(f'Error checking B5 size: {e}')
        return 0.0

