    if check_all:
        correct_count = 0
        for fs in font_sizes:
            if fs['size_pt'] is not None and abs(fs['size_pt'] - expected_size) <= tolerance:
                correct_count += 1
            elif fs['size_pt'] is None and expected_size is None:
                correct_count += 1
        return 1.0 if correct_count == len(font_sizes) else 0.0
    else:
        for fs in font_sizes:
            if fs['size_pt'] is not None and abs(fs['size_pt'] - expected_size) <= tolerance:
                return 1.0
            elif fs['size_pt'] is None and expected_size is None:
                return 1.0
        return 0.0

