def check_pptx_all_text_font_size__0c922880(result_file, expected, **options):
    """
    Check if all text boxes on a specific slide have the target font size.

    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with slide_idx and target_font_size_pt
        **options: Additional options

    Returns:
        float: 1.0 if all text has target font size, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        target_font_size_pt = expected.get('target_font_size_pt', 0)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]

        def get_all_text_shapes(shapes):
            results = []
            for shape in shapes:
                if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                    results.append(shape)
                if hasattr(shape, 'shapes'):
                    results.extend(get_all_text_shapes(shape.shapes))
            return results
        text_shapes = get_all_text_shapes(slide.shapes)
        if not text_shapes:
            return 0.0
        all_match = True
        for shape in text_shapes:
            for para in shape.text_frame.paragraphs:
                for run in para.runs:
                    if not run.text.strip():
                        continue
                    if run.font.size is None:
                        all_match = False
                        break
                    actual_pt = run.font.size.pt
                    if abs(actual_pt - target_font_size_pt) > 1.0:
                        all_match = False
                        break
                if not all_match:
                    break
            if not all_match:
                break
        return 1.0 if all_match else 0.0
    except Exception as e:
        return 0.0

