def check_slide_contains_text__8e36c760(result_file, expected, **options):
    """
    Check if a specific slide contains specific text anywhere in the slide.

    Args:
        result_file: Path to the PowerPoint file
        expected: Dict with 'type' and 'rules' containing 'slide_index' and 'text'
        **options: Additional options (case_sensitive, etc.)

    Returns:
        float: 1.0 if text is found, 0.0 otherwise
    """
    try:
        rules = expected.get('rules', expected)
        slide_index = rules.get('slide_index', 0)
        search_text = rules.get('text', '')
        case_sensitive = options.get('case_sensitive', False)
        prs = Presentation(result_file)
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if hasattr(shape, 'text'):
                text = shape.text
                if case_sensitive:
                    if search_text in text:
                        return 1.0
                elif search_text.lower() in text.lower():
                    return 1.0
        return 0.0
    except Exception as e:
        print(f'Error checking slide text: {e}')
        return 0.0

