def check_pptx_image_position__3b06647c(result_file, expected, **options):
    """
    Check if a specific image on a slide was moved to the left side.

    Verifies that an image originally at a specific position (original_left_position)
    has been moved to the left side (left <= max_left_position).

    To prevent false positives where a different image is moved or the target is deleted:
    1. We verify no image remains at the original position (with tolerance)
    2. We verify at least one image exists on the left side
    3. We count total images to detect additions/deletions
    4. We verify the original position was NOT already on the left

    This multi-condition check significantly reduces false positive scenarios while
    working within the constraint of only seeing the result state (no before/after).

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing:
            - slide_idx: Index of the slide (0-based)
            - shape_type: Type of shape to check (13 = PICTURE)
            - max_left_position: Maximum left position for "left side"
            - original_left_position: Original left position of the target image
            - tolerance: Tolerance for matching original position (default: 100000 EMUs)
            - expected_image_count: Optional - expected total count of images (for validation)
        **options: Additional options

    Returns:
        float: 1.0 if the specific image was moved to left side, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_type = expected.get('shape_type', 13)
        max_left = expected.get('max_left_position', 0)
        original_left = expected.get('original_left_position')
        tolerance = expected.get('tolerance', 100000)
        expected_count = expected.get('expected_image_count')
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if original_left is not None:
            images = [shape for shape in slide.shapes if shape.shape_type == shape_type]
            if original_left <= max_left:
                images_at_original = sum((1 for shape in images if abs(shape.left - original_left) <= tolerance))
                return 1.0 if images_at_original == 0 else 0.0
            images_at_original = sum((1 for shape in images if abs(shape.left - original_left) <= tolerance))
            images_on_left = sum((1 for shape in images if shape.left <= max_left))
            total_images = len(images)
            if images_at_original > 0:
                return 0.0
            if images_on_left < 1:
                return 0.0
            if expected_count is not None and total_images != expected_count:
                return 0.0
            return 1.0
        for shape in slide.shapes:
            if shape.shape_type == shape_type:
                if shape.left <= max_left:
                    return 1.0
        return 0.0
    except Exception as e:
        return 0.0

def check_pptx_image_size__026906b5ba895ae173ac3e52167d6e42(result, expected, **options):
    """Check if a PowerPoint slide contains an image with the expected size.

    Args:
        result: dict from getter with image information
        expected: dict with 'slide_index', 'expected_width_cm', 'expected_height_cm'
        **options: Additional options (tolerance)

    Returns:
        float: Score between 0.0 and 1.0
    """
    tolerance = options.get('tolerance', 0.01)
    expected_width = expected.get('expected_width_cm')
    expected_height = expected.get('expected_height_cm')
    if not result or 'image_count' not in result:
        return 0.0
    if result['image_count'] == 0:
        return 0.0
    images = result.get('images', [])
    for img in images:
        width_cm = img['width_cm']
        height_cm = img['height_cm']
        width_match = abs(width_cm - expected_width) / expected_width <= tolerance
        height_match = abs(height_cm - expected_height) / expected_height <= tolerance
        if width_match and height_match:
            return 1.0
    return 0.0

