def check_slide_background_color__d5361c4c(result_file, expected, **options):
    """
    Check if a specific slide has the expected background color.

    Args:
        result_file: Path to the PPTX file
        expected: Dict with 'slide_idx' (0-indexed) and 'target_rgb' (list of [R, G, B])
        **options: Additional options

    Returns:
        float: 1.0 if background color matches, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        target_rgb = expected.get('target_rgb', [0, 0, 0])
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        fill = slide.background.fill
        if fill.type == 1:
            if hasattr(fill.fore_color, 'rgb'):
                actual_rgb = fill.fore_color.rgb
                (r, g, b) = actual_rgb
                if r == target_rgb[0] and g == target_rgb[1] and (b == target_rgb[2]):
                    return 1.0
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                if hasattr(master_fill.fore_color, 'rgb'):
                    actual_rgb = master_fill.fore_color.rgb
                    (r, g, b) = actual_rgb
                    if r == target_rgb[0] and g == target_rgb[1] and (b == target_rgb[2]):
                        return 1.0
        return 0.0
    except Exception as e:
        return 0.0

def check_pptx_slide_images__c8043a75(result: Dict[str, Any], expected: Any, **options) -> float:
    """Check if PowerPoint has correct number of slides and images per slide.

    Args:
        result: Dict from getter with 'slide_count' and 'images_per_slide'
        expected: Dict with 'slide_count' and 'images_per_slide' (expected list)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    expected_slides = expected.get('slide_count', 0)
    actual_slides = result.get('slide_count', 0)
    if actual_slides == expected_slides:
        score += 0.5
    expected_images = expected.get('images_per_slide', [])
    actual_images = result.get('images_per_slide', [])
    if len(expected_images) > 0:
        matching_slides = 0
        for i in range(min(len(expected_images), len(actual_images))):
            if actual_images[i] == expected_images[i]:
                matching_slides += 1
        image_score = matching_slides / len(expected_images)
        score += 0.5 * image_score
    return score

