def check_pptx_slide_font_size__1173e255(result, expected, **options):
    """
    Check if all text in a specific slide has the expected font size.

    Args:
        result: Path to the PPTX file
        expected: Expected rules dict with font_size (e.g., {'font_size': 28})
        **options: Additional options

    Returns:
        float: 1.0 if all text has expected font size, 0.0 otherwise
    """
    try:
        prs = Presentation(result)
        if isinstance(expected, dict):
            expected_font_size = expected.get('font_size')
        else:
            expected_font_size = expected
        if expected_font_size is None:
            return 0.0
        expected_size_emu = expected_font_size * 12700
        if len(prs.slides) < 5:
            return 0.0
        slide = prs.slides[4]
        found_any_text = False
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if not run.text or not run.text.strip():
                            continue
                        found_any_text = True
                        if run.font.size is None:
                            return 0.0
                        if run.font.size != expected_size_emu:
                            return 0.0
        if not found_any_text:
            return 0.0
        return 1.0
    except Exception as e:
        return 0.0

def check_pptx_text_font_size__c297c1d45172bc3b68466f8145d67fd8(result, expected, **options):
    """Check if text runs have the expected font size.

    Args:
        result: dict of slide_index -> list of font sizes (from getter)
        expected: dict with keys:
            - slide_index: int, the slide to check
            - expected_size: float, the expected font size in points
        **options: Additional options
            - tolerance: float, tolerance for size comparison (default 0.5)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    slide_idx = expected.get('slide_index', 1)
    expected_size = expected.get('expected_size', 24.0)
    tolerance = options.get('tolerance', 0.5)
    if slide_idx not in result:
        return 0.0
    font_sizes = result[slide_idx]
    if not font_sizes:
        return 0.0
    for size in font_sizes:
        if size is None:
            return 0.0
        if abs(size - expected_size) > tolerance:
            return 0.0
    return 1.0

