def check_pptx_text_format__424abafa04d7febe70daadac89c5d778(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Compare PowerPoint slide text and formatting against expected values.
    
    Args:
        result: Data from getter function (slide text and formatting info)
        expected: Expected values from rules (slide_index, expected_text, formatting)
        **options: Additional comparison options
        
    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass)
    """
    if 'error' in result:
        return 0.0
    slide_index = expected.get('slide_index', 0)
    expected_text = expected.get('expected_text', '')
    expected_font_size = expected.get('expected_font_size')
    expected_color = expected.get('expected_color')
    expected_bold = expected.get('expected_bold')
    expected_font_name = expected.get('expected_font_name')
    expected_italic = expected.get('expected_italic')
    slides = result.get('slides', [])
    if slide_index >= len(slides):
        return 0.0
    slide = slides[slide_index]
    text_found = False
    formatting_correct = True
    for shape in slide.get('shapes', []):
        shape_text = shape.get('text', '')
        if expected_text in shape_text:
            text_found = True
            for run in shape.get('runs', []):
                run_text = run.get('text', '')
                if expected_text in run_text or run_text in expected_text:
                    if expected_font_size is not None:
                        actual_size = run.get('font_size')
                        if actual_size is None or abs(actual_size - expected_font_size) > 1:
                            formatting_correct = False
                            break
                    if expected_font_name is not None:
                        actual_font = run.get('font_name')
                        if actual_font != expected_font_name:
                            formatting_correct = False
                            break
                    if expected_bold is not None:
                        actual_bold = run.get('bold')
                        if actual_bold != expected_bold:
                            formatting_correct = False
                            break
                    if expected_italic is not None:
                        actual_italic = run.get('italic')
                        if actual_italic != expected_italic:
                            formatting_correct = False
                            break
                    if expected_color is not None:
                        actual_color = run.get('color')
                        if actual_color is None:
                            formatting_correct = False
                            break
                        tolerance = 20
                        r_diff = abs(actual_color.get('r', 0) - expected_color.get('r', 0))
                        g_diff = abs(actual_color.get('g', 0) - expected_color.get('g', 0))
                        b_diff = abs(actual_color.get('b', 0) - expected_color.get('b', 0))
                        if r_diff > tolerance or g_diff > tolerance or b_diff > tolerance:
                            formatting_correct = False
                            break
            break
    if not text_found:
        return 0.0
    if not formatting_correct:
        return 0.5
    return 1.0

def check_impress_config__41469e13(config_file_path, rules):
    """
    Check LibreOffice Impress configuration setting in registrymodifications.xcu.
    
    Args:
        config_file_path: Path to registrymodifications.xcu file
        rules: Dictionary containing:
            - xpath: XML path to the configuration item (e.g., '/org.openoffice.Office.Impress/Misc/Start')
            - setting_name: Name of the setting property (e.g., 'EnablePresenterScreen')
            - expected_value: Expected value of the setting (string, 'true'/'false' or numeric)
    
    Returns:
        1.0 if setting matches expected value, 0.0 otherwise
    """
    try:
        tree = ET.parse(config_file_path)
        root = tree.getroot()
        namespaces = {'oor': 'http://openoffice.org/2001/registry'}
        xpath = rules.get('xpath', '')
        setting_name = rules.get('setting_name', '')
        expected_value = str(rules.get('expected_value', ''))
        xpath_query = f".//item[@oor:path='{xpath}']/prop[@oor:name='{setting_name}']"
        for item in root.findall(xpath_query, namespaces):
            value_elem = item.find('value')
            if value_elem is not None:
                actual_value = value_elem.text
                if actual_value is not None:
                    if actual_value.lower() == expected_value.lower():
                        return 1.0
                    else:
                        logger.info(f"Setting {setting_name} has value '{actual_value}', expected '{expected_value}'")
                        return 0.0
        logger.info(f'Setting {setting_name} not found in configuration file')
        return 0.0
    except Exception as e:
        logger.error(f'Error checking configuration: {e}')
        return 0.0

