def check_pptx_image_size__910a8869(result, expected, **options):
    """
    Check if an image with specific dimensions exists in the result.

    Args:
        result: List of image info dicts from getter
        expected: Dict with 'width', 'height' in EMUs, optional 'tolerance'
        **options: Additional options

    Returns:
        float: 1.0 if image found with correct size, 0.0 otherwise
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    target_width = expected.get('width')
    target_height = expected.get('height')
    tolerance = expected.get('tolerance', 0.01)
    for img in result:
        width = img.get('width', 0)
        height = img.get('height', 0)
        if target_width > 0 and target_height > 0:
            width_diff = abs(width - target_width) / target_width
            height_diff = abs(height - target_height) / target_height
            if width_diff <= tolerance and height_diff <= tolerance:
                return 1.0
    return 0.0

def check_master_slides_panel__fd2eb8c7122c74d2a02f51527fe62007(accessibility_tree, expected, **options):
    """
    Check if the Master Slides panel is visible in LibreOffice Impress.
    The Master Slides view shows the master slide templates.

    Args:
        accessibility_tree: XML string of the accessibility tree
        expected: Expected rules dict (not used, but required by framework)
        **options: Additional options

    Returns:
        float: 1.0 if Master Slides panel is visible, 0.0 otherwise
    """
    namespaces = {'st': 'uri:deskat:state.at-spi.gnome.org', 'cp': 'uri:deskat:component.at-spi.gnome.org'}
    try:
        root = ET.fromstring(accessibility_tree)
        for doc_frame in root.iter('document-frame'):
            name = doc_frame.attrib.get('name', '')
            if 'Master' in name and ('Slides' in name or 'View' in name):
                return 1.0
            if name == 'Master View':
                return 1.0
        for panel in root.iter('panel'):
            name = panel.attrib.get('name', '')
            if 'Master' in name:
                return 1.0
        return 0.0
    except Exception as e:
        logger.error(f'Error checking master slides panel: {e}')
        return 0.0

def check_slide_sorter_view__5e26492558933e6cbf3164a71a0d0003(accessibility_tree, expected, **options):
    """
    Check if Slide Sorter view is active in LibreOffice Impress.
    Slide Sorter is a view mode that shows all slides in a grid for easy reordering.

    Args:
        accessibility_tree: XML string of the accessibility tree
        expected: Expected rules dict (not used, but required by framework)
        **options: Additional options

    Returns:
        float: 1.0 if Slide Sorter view is active, 0.0 otherwise
    """
    namespaces = {'st': 'uri:deskat:state.at-spi.gnome.org', 'cp': 'uri:deskat:component.at-spi.gnome.org'}
    try:
        root = ET.fromstring(accessibility_tree)
        for doc_frame in root.iter('document-frame'):
            name = doc_frame.attrib.get('name', '')
            if 'Slide Sorter' in name or 'slide sorter' in name.lower():
                return 1.0
        for panel in root.iter('panel'):
            name = panel.attrib.get('name', '')
            if 'Slide Sorter' in name:
                return 1.0
        for frame in root.iter('frame'):
            name = frame.attrib.get('name', '')
            if 'Slide Sorter' in name:
                return 1.0
        return 0.0
    except Exception as e:
        logger.error(f'Error checking slide sorter view: {e}')
        return 0.0

