def check_pptx_font_size__712c355d(result_file, expected, **options):
    """
    Check if text containing specific content has the target font size.

    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with slide_idx, text_contains, and target_font_size_pt
        **options: Additional options

    Returns:
        float: 1.0 if font size matches for all matching text, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        text_contains = expected.get('text_contains', '')
        target_font_size_pt = expected.get('target_font_size_pt', 0)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]

        def get_all_text_shapes(shapes):
            results = []
            for shape in shapes:
                if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                    results.append(shape)
                if hasattr(shape, 'shapes'):
                    results.extend(get_all_text_shapes(shape.shapes))
            return results
        text_shapes = get_all_text_shapes(slide.shapes)
        matching_shapes = [shape for shape in text_shapes if text_contains in shape.text]
        if not matching_shapes:
            return 0.0
        for shape in matching_shapes:
            runs_checked = 0
            for para in shape.text_frame.paragraphs:
                for run in para.runs:
                    if not run.text.strip():
                        continue
                    runs_checked += 1
                    if run.font.size is None:
                        return 0.0
                    actual_pt = run.font.size.pt
                    if abs(actual_pt - target_font_size_pt) > 1.0:
                        return 0.0
            if runs_checked == 0:
                return 0.0
        return 1.0
    except Exception as e:
        return 0.0

def check_slide_images__360e07ae(result, expected, **options):
    """
    Verify that the presentation has the correct structure with required images.

    This function checks:
    1. Total slide count matches expected
    2. The correct 4 images (pic3.png, pic4.png, pic5.png, pic6.png) are present
    3. Each of the 4 new slides contains exactly 1 image
    4. All required images are found in the presentation

    Args:
        result: Dictionary with slide_count and slide_images from getter
            {
                'slide_count': int,
                'slide_images': [
                    {'slide_num': int, 'image_count': int, 'image_names': [str]},
                    ...
                ]
            }
        expected: Dictionary with expected configuration
            {
                'total_slides': int,
                'required_images': [str],  # List of required image filenames
                'images_per_slide': int    # Expected images per new slide
            }
        **options: Additional options (not used)

    Returns:
        float: Score between 0.0 and 1.0
            1.0 if all requirements met
            Partial score if some requirements met
            0.0 if major requirements failed
    """
    slide_count = result.get('slide_count', 0)
    slide_images = result.get('slide_images', [])
    expected_total_slides = expected.get('total_slides', 5)
    required_images = expected.get('required_images', ['pic3.png', 'pic4.png', 'pic5.png', 'pic6.png'])
    images_per_slide = expected.get('images_per_slide', 1)
    score = 0.0
    max_score = 4.0
    if slide_count == expected_total_slides:
        score += 1.0
    elif abs(slide_count - expected_total_slides) <= 1:
        score += 0.5
    all_images_in_presentation = []
    slides_with_images = []
    for slide_info in slide_images:
        image_names = slide_info.get('image_names', [])
        all_images_in_presentation.extend(image_names)
        if slide_info.get('image_count', 0) > 0:
            slides_with_images.append(slide_info)
    found_images = []
    for required_image in required_images:
        if any((required_image in img_name for img_name in all_images_in_presentation)):
            found_images.append(required_image)
    if len(found_images) == len(required_images):
        score += 1.0
    else:
        score += len(found_images) / len(required_images)
    expected_slides_with_images = len(required_images)
    actual_slides_with_images = len(slides_with_images)
    if actual_slides_with_images == expected_slides_with_images:
        score += 1.0
    elif abs(actual_slides_with_images - expected_slides_with_images) <= 1:
        score += 0.5
    correct_distribution_count = 0
    for slide_info in slides_with_images:
        if slide_info.get('image_count', 0) == images_per_slide:
            correct_distribution_count += 1
    if correct_distribution_count == expected_slides_with_images:
        score += 1.0
    else:
        score += correct_distribution_count / expected_slides_with_images
    final_score = score / max_score
    return final_score

