def check_pptx_images_alignment__5c52fa32f4afbad45cc35ec0aef8bab1(result, expected, **options):
    """Check if multiple images are horizontally aligned.

    Args:
        result: Dict mapping image names to their properties
        expected: Dict with 'image_names' list and 'alignment_type' ('top', 'center', or 'bottom')
        **options: Additional options (tolerance for alignment in EMUs)

    Returns:
        float: 1.0 if all images are aligned within tolerance, 0.0 otherwise
    """
    if not result or not expected:
        return 0.0
    image_names = expected.get('image_names', [])
    alignment_type = expected.get('alignment_type', 'top')
    tolerance = options.get('tolerance', 91440)
    if len(image_names) < 2:
        return 0.0
    alignment_values = []
    for name in image_names:
        if name not in result:
            return 0.0
        img_data = result[name]
        if alignment_type == 'top':
            alignment_values.append(img_data['top'])
        elif alignment_type == 'center':
            alignment_values.append(img_data['top'] + img_data['height'] // 2)
        elif alignment_type == 'bottom':
            alignment_values.append(img_data['top'] + img_data['height'])
        else:
            return 0.0
    reference = alignment_values[0]
    for value in alignment_values[1:]:
        if abs(value - reference) > tolerance:
            return 0.0
    return 1.0

