def check_pptx_slides__15ef8d4a(result_state, expected_state, **options):
    """
    Check if PPTX slides meet expected criteria for duplication task.

    This function verifies:
    1. Total slide count matches expected
    2. All specified slides exist with expected text fragments
    3. Duplicate slides exist and match originals (if verify_duplication is provided)

    Args:
        result_state: Dict with 'total_slides' and 'slides' from getter
        expected_state: Dict with 'type'='rule' and 'rules' containing:
            - 'expected_total_slides': int
            - 'verify_slides': dict mapping slide indices to expected text fragments
            - 'verify_duplication': optional dict mapping original index to duplicate index
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    try:
        rules = expected_state.get('rules', {})
        expected_total = rules.get('expected_total_slides')
        verify_slides = rules.get('verify_slides', {})
        verify_duplication = rules.get('verify_duplication', {})
        actual_total = result_state.get('total_slides', 0)
        if actual_total != expected_total:
            return 0.0
        slides_dict = result_state.get('slides', {})
        for (slide_idx_str, expected_text) in verify_slides.items():
            slide_idx = int(slide_idx_str)
            if str(slide_idx) not in slides_dict:
                return 0.0
            actual_text = slides_dict[str(slide_idx)]
            if expected_text not in actual_text:
                return 0.0
        if verify_duplication:
            for (orig_idx_str, dup_idx_str) in verify_duplication.items():
                orig_idx = int(orig_idx_str)
                dup_idx = int(dup_idx_str)
                if str(orig_idx) not in slides_dict or str(dup_idx) not in slides_dict:
                    return 0.0
                orig_text = slides_dict[str(orig_idx)]
                dup_text = slides_dict[str(dup_idx)]
                expected_text = verify_slides.get(str(orig_idx), '')
                if expected_text:
                    if expected_text not in orig_text or expected_text not in dup_text:
                        return 0.0
        return 1.0
    except Exception as e:
        return 0.0

def check_pptx_duplicated_appended__63c5ecc1546db5bcb0fccda77189e75e(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if slides 15-17 were duplicated and appended to the end.

    Args:
        result: Dict with 'slide_count', 'slides_15_17_text', and 'last_3_slides_text'
        expected: Dict with 'expected_slide_count'
        **options: Additional options

    Returns:
        float: 1.0 if slide count matches AND last 3 slides match slides 15-17, 0.0 otherwise
    """
    expected_count = expected.get('expected_slide_count', 0)
    actual_count = result.get('slide_count', 0)
    if actual_count != expected_count:
        return 0.0
    slides_15_17 = result.get('slides_15_17_text', [])
    last_3_slides = result.get('last_3_slides_text', [])
    if len(slides_15_17) != 3 or len(last_3_slides) != 3:
        return 0.0
    similarity_threshold = 0.85
    for (original, duplicate) in zip(slides_15_17, last_3_slides):
        if not original and (not duplicate):
            continue
        if not original or not duplicate:
            return 0.0
        similarity = SequenceMatcher(None, original, duplicate).ratio()
        if similarity < similarity_threshold:
            return 0.0
    return 1.0

