def check_pptx_slide_notes_content__051bf4eec2b0ad106992ce108dbf1e28(result, expected, **options):
    """Check if specific slides have expected notes content.

    Args:
        result: dict from getter - {slide_index: notes_text}
        expected: dict with 'expected_notes' key mapping slide_index to expected text
        **options: Additional options

    Returns:
        float: Proportion of slides with correct notes (0.0 to 1.0)
    """
    if not isinstance(result, dict):
        return 0.0
    expected_notes = expected.get('expected_notes', {})
    if not expected_notes:
        return 0.0
    total_slides = len(expected_notes)
    correct_count = 0
    for (slide_idx_str, expected_text) in expected_notes.items():
        slide_idx = int(slide_idx_str)
        actual_text = result.get(slide_idx, '')
        actual_normalized = ' '.join(actual_text.split())
        expected_normalized = ' '.join(expected_text.split())
        if actual_normalized == expected_normalized:
            correct_count += 1
    return correct_count / total_slides if total_slides > 0 else 0.0

def check_pptx_image_size__b2189dbb(result, expected, **options):
    """
    Check if an image with specific dimensions and name exists in the result.

    Args:
        result: List of image info dicts from getter
        expected: Dict with 'width', 'height' in EMUs, optional 'tolerance', optional 'image_name_pattern'
        **options: Additional options

    Returns:
        float: 1.0 if image found with correct size and name, 0.0 otherwise
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    target_width = expected.get('width')
    target_height = expected.get('height')
    tolerance = expected.get('tolerance', 0.01)
    image_name_pattern = expected.get('image_name_pattern', None)
    for img in result:
        width = img.get('width', 0)
        height = img.get('height', 0)
        name = img.get('name', '')
        if target_width > 0 and target_height > 0:
            width_diff = abs(width - target_width) / target_width
            height_diff = abs(height - target_height) / target_height
            dimensions_match = width_diff <= tolerance and height_diff <= tolerance
            if image_name_pattern:
                name_matches = image_name_pattern.lower() in name.lower()
                if dimensions_match and name_matches:
                    return 1.0
            elif dimensions_match:
                return 1.0
    return 0.0

