def check_pptx_contains_text__fad5be94(result_file, expected, **options):
    """Check if a PPTX slide contains specific text in a subtitle placeholder.

    Args:
        result_file: Path to the PPTX file
        expected: Dict with 'slide_index' and 'target_text'

    Returns:
        float: 1.0 if text found in subtitle placeholder, 0.0 otherwise
    """
    try:
        slide_index = expected.get('slide_index', 0)
        target_text = expected.get('target_text', '')
        prs = Presentation(result_file)
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        title_shape = None
        title_top = 0
        for shape in slide.shapes:
            if shape.is_placeholder:
                try:
                    if shape.placeholder_format.idx == 0:
                        title_shape = shape
                        title_top = shape.top
                        break
                except:
                    pass
        for shape in slide.shapes:
            if not hasattr(shape, 'text'):
                continue
            if shape.is_placeholder:
                try:
                    if shape.placeholder_format.idx == 0:
                        continue
                except:
                    pass
            if target_text in shape.text:
                if title_shape is not None:
                    if shape.top > title_top:
                        if shape.is_placeholder:
                            try:
                                if shape.placeholder_format.idx == 1:
                                    return 1.0
                            except:
                                pass
                        return 1.0
                elif shape.is_placeholder:
                    try:
                        if shape.placeholder_format.idx >= 1:
                            return 1.0
                    except:
                        pass
        return 0.0
    except Exception as e:
        print(f'Error checking PPTX text: {e}')
        return 0.0

