def check_pptx_references_slide__b306c553(result, expected, **options):
    """Check if presentation has correct slide count and a references slide with expected content.

    Args:
        result: Structure dict from getter
        expected: Expected values with slide_count, slide_index, title, contains_text
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_count = expected.get('slide_count', 0)
    if result.get('slide_count', 0) == expected_count:
        score += 0.33
    slide_index = expected.get('slide_index', -1)
    expected_title = expected.get('title', '')
    slides_info = result.get('slides_info', [])
    if slide_index >= 0 and slide_index < len(slides_info):
        actual_title = slides_info[slide_index].get('title', '')
        if expected_title.lower() in actual_title.lower() or actual_title.lower() in expected_title.lower():
            score += 0.34
            expected_text = expected.get('contains_text', '')
            all_text = ' '.join(slides_info[slide_index].get('all_text', [])).lower()
            if expected_text.lower() in all_text:
                score += 0.33
    return min(score, 1.0)

