def check_slide_titles_extracted__87f6c353(result, expected, **options):
    """
    Check if extracted slide titles match expected titles.

    This metric evaluates the quality of slide title extraction by comparing
    the extracted titles against the required titles. It provides granular
    partial credit based on how many titles match correctly.

    Args:
        result: List of lines from the result file
        expected: Dict with 'required_titles' key containing list of expected titles,
                  and optional 'expected_count' key for total title count
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on title match percentage
    """
    if not isinstance(result, list):
        return 0.0
    required_titles = expected.get('required_titles', [])
    expected_count = expected.get('expected_count', None)
    if not required_titles:
        return 0.0
    result_normalized = [line.strip() for line in result if line.strip()]
    result_lower = [line.lower() for line in result_normalized]
    required_title_counts = {}
    for title in required_titles:
        title_lower = title.lower()
        required_title_counts[title_lower] = required_title_counts.get(title_lower, 0) + 1
    result_title_counts = {}
    for title in result_lower:
        result_title_counts[title] = result_title_counts.get(title, 0) + 1
    matches = 0
    for (title_lower, required_count) in required_title_counts.items():
        result_count = result_title_counts.get(title_lower, 0)
        if result_count >= required_count:
            matches += required_count
        else:
            matches += result_count
    title_score = matches / len(required_titles) if len(required_titles) > 0 else 0.0
    return title_score

def check_pptx_table_row__35f132f23861957336ab390db528f16e(result, expected, **options):
    """Compare a table row against expected values.

    Args:
        result: List of cell values from the getter
        expected: Dictionary with 'expected_values' key containing list of expected values
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('expected_values', [])
    if not isinstance(result, list):
        return 0.0
    if len(result) != len(expected_values):
        return 0.0
    for (actual, expected_val) in zip(result, expected_values):
        if str(actual).strip() != str(expected_val).strip():
            return 0.0
    return 1.0

