def check_pptx_content_italic__61fa6cb60dfc8b0005cfed16659a40c0(result, expected, **options):
    """Check if content text is italicized.

    Args:
        result: Dictionary from getter with slide data
        expected: Expected configuration with slide_idx key
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (percentage of italic content items)
    """
    slide_idx = expected.get('slide_idx', 0)
    if slide_idx not in result:
        return 0.0
    slide_data = result[slide_idx]
    if not slide_data:
        return 0.0
    total_count = len(slide_data)
    italic_count = sum((1 for item in slide_data if item.get('is_italic', False)))
    return italic_count / total_count if total_count > 0 else 0.0

def check_pptx_last_slide__d4bcfe2b(result, expected, **options):
    """Check if presentation has correct slide count and last slide title/content.

    Args:
        result: Structure dict from getter
        expected: Expected values dict with slide_count, title, contains_text
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_count = expected.get('slide_count', 0)
    if result.get('slide_count', 0) == expected_count:
        score += 0.33
    expected_title = expected.get('title', '')
    actual_title = result.get('last_slide', {}).get('title', '')
    if expected_title.lower() in actual_title.lower() or actual_title.lower() in expected_title.lower():
        score += 0.34
    expected_text = expected.get('contains_text', '')
    text_content = result.get('last_slide', {}).get('text_content', [])
    all_text = ' '.join(text_content).lower()
    if expected_text.lower() in all_text:
        score += 0.33
    return min(score, 1.0)

def check_pptx_title_format__26d86cf313d44464bf1449221f3619a9(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if PowerPoint title formatting matches expected values.

    Args:
        result: Formatting info from getter
        expected: Expected formatting (rules dict)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (partial credit)
    """
    if not result or not isinstance(result, dict):
        return 0.0
    score = 0.0
    checks = 0
    if 'font_color_rgb' in expected:
        checks += 1
        expected_color = expected['font_color_rgb']
        actual_color = result.get('font_color_rgb', None)
        if actual_color is not None and expected_color is not None:
            if isinstance(actual_color, tuple) and isinstance(expected_color, tuple):
                if len(actual_color) >= 3 and len(expected_color) >= 3:
                    tolerance = options.get('color_tolerance', 10)
                    if all((abs(actual_color[i] - expected_color[i]) <= tolerance for i in range(3))):
                        score += 1.0
    if 'font_size' in expected:
        checks += 1
        expected_size = expected['font_size']
        actual_size = result.get('font_size', None)
        if actual_size is not None:
            tolerance = options.get('size_tolerance', expected_size * 0.05)
            if abs(actual_size - expected_size) <= tolerance:
                score += 1.0
    for prop in ['bold', 'italic', 'underline']:
        if prop in expected:
            checks += 1
            if result.get(prop, None) == expected[prop]:
                score += 1.0
    if checks == 0:
        return 0.0
    return score / checks

