def check_pptx_slide_notes__2d4ac67d(result, expected, **options):
    """Check if PowerPoint slide notes match expected content.

    Args:
        result: Dict mapping slide number to actual notes text
        expected: Dict with 'slide_notes' mapping slide number to expected text
        **options: Additional options (e.g., 'fuzzy_match' for partial matching)

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_notes = expected.get('slide_notes', {})
    use_fuzzy = options.get('fuzzy_match', False)
    if not expected_notes:
        return 0.0
    total_slides = len(expected_notes)
    correct_slides = 0
    for (slide_num, expected_text) in expected_notes.items():
        actual_text = result.get(slide_num, '').strip()
        expected_text = expected_text.strip()
        if use_fuzzy:
            if expected_text.lower() in actual_text.lower():
                correct_slides += 1
        elif actual_text == expected_text:
            correct_slides += 1
    return correct_slides / total_slides if total_slides > 0 else 0.0

