def check_pptx_image_size__36f3a256718394f2d1e1606ab56777d7(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if a PPTX file contains an image with the expected dimensions and identity.

    Args:
        result: Image info from getter with structure:
            {
                "image_count": int,
                "images": [{"width_cm": float, "height_cm": float, "image_hash": str, ...}, ...]
            }
        expected: Expected values (passed via rules):
            {
                "min_images": int (minimum number of images expected),
                "width_cm": float (expected width),
                "height_cm": float (expected height),
                "tolerance_cm": float (tolerance for size matching, default: 0.05),
                "image_path": str (path to expected image file for hash comparison, optional)
            }
        **options: Additional options (includes 'env' for file access)

    Returns:
        float: 1.0 if at least one image matches the expected size and identity, 0.0 otherwise
    """
    min_images = expected.get('min_images', 1)
    expected_width = expected.get('width_cm')
    expected_height = expected.get('height_cm')
    tolerance = expected.get('tolerance_cm', 0.05)
    expected_image_path = expected.get('image_path')
    if result.get('image_count', 0) < min_images:
        return 0.0
    expected_hash = None
    if expected_image_path and 'env' in options:
        try:
            env = options['env']
            image_bytes = env.controller.get_file(expected_image_path)
            if image_bytes:
                expected_hash = hashlib.sha256(image_bytes).hexdigest()
        except Exception:
            pass
    for img in result.get('images', []):
        width_match = abs(img['width_cm'] - expected_width) <= tolerance
        height_match = abs(img['height_cm'] - expected_height) <= tolerance
        if not (width_match and height_match):
            continue
        if expected_hash:
            if img.get('image_hash') == expected_hash:
                return 1.0
        else:
            return 1.0
    return 0.0

