def check_ppt_title_color_size__3080ad51(result, expected, **options):
    """Check if title color and size in specified slides match expected values.

    Args:
        result: Dict from getter - {slide_idx: {property: value}}
        expected: Dict with expected values per slide
        **options: Additional options (color_tolerance: int, size_tolerance: float)

    Returns:
        float: Score between 0.0 and 1.0 (partial credit for color or size alone)
    """
    target_slides = expected.get('target_slides', [])
    expected_color = expected.get('expected_color')
    expected_size = expected.get('expected_size', 80.0)
    color_tolerance = options.get('color_tolerance', 20)
    size_tolerance = options.get('size_tolerance', 2.0)
    if not target_slides:
        return 0.0
    score = 0.0
    total_points = len(target_slides) * 2
    for slide_idx in target_slides:
        if slide_idx not in result:
            continue
        actual_color = result[slide_idx].get('color')
        if actual_color == expected_color:
            score += 1.0
        elif actual_color and expected_color:
            actual_rgb = tuple((int(actual_color[i:i + 2], 16) for i in (1, 3, 5)))
            expected_rgb = tuple((int(expected_color[i:i + 2], 16) for i in (1, 3, 5)))
            diff = sum((abs(a - e) for (a, e) in zip(actual_rgb, expected_rgb)))
            if diff <= color_tolerance * 3:
                score += 1.0
        actual_size = result[slide_idx].get('size')
        if actual_size is not None and abs(actual_size - expected_size) <= size_tolerance:
            score += 1.0
    return score / total_points if total_points > 0 else 0.0

def check_slide_size_a4__3534800b(result_state, expected_state, **options):
    """
    Check if the slide size matches expected dimensions.
    Expected dimensions come from config (e.g., A4: 210mm x 297mm = 7772400 x 10826700 EMUs).

    Args:
        result_state: Path to the PPTX file (from vm_file getter)
        expected_state: Expected values dict with 'width', 'height', and 'tolerance'
        **options: Additional options

    Returns:
        float: 1.0 if slide size matches expected dimensions, 0.0 otherwise
    """
    try:
        presentation = Presentation(result_state)
        expected_width = expected_state.get('width')
        expected_height = expected_state.get('height')
        tolerance = expected_state.get('tolerance', 0.01)
        if expected_width is None or expected_height is None:
            return 0.0
        actual_width = presentation.slide_width
        actual_height = presentation.slide_height
        width_match = abs(actual_width - expected_width) / expected_width <= tolerance
        height_match = abs(actual_height - expected_height) / expected_height <= tolerance
        if width_match and height_match:
            return 1.0
        return 0.0
    except Exception as e:
        return 0.0

def check_pptx_left_position__6a6a802f(file1_path, file2_path, **options):
    """
    Check if an image on a specific slide has been moved to the left position.

    Args:
        file1_path: Path to result PPTX file
        file2_path: Path to expected/original PPTX file (not used, kept for compatibility)
        **options: Options including slide_index, shape_index, and position tolerance

    Returns:
        float: 1.0 if image is on the left, 0.0 otherwise
    """
    slide_index = options.get('slide_index', 1)
    shape_index = options.get('shape_index', 2)
    tolerance = options.get('tolerance', 100000)
    try:
        prs = Presentation(file1_path)
        if len(prs.slides) <= slide_index:
            logger.error(f'Slide {slide_index} does not exist')
            return 0.0
        slide = prs.slides[slide_index]
        if len(slide.shapes) <= shape_index:
            logger.error(f'Shape {shape_index} does not exist on slide {slide_index}')
            return 0.0
        shape = slide.shapes[shape_index]
        if shape.shape_type != 13:
            logger.error(f'Shape {shape_index} is not a picture')
            return 0.0
        expected_left = 457200
        if abs(shape.left - expected_left) <= tolerance:
            logger.info(f'Image is positioned on the left (left={shape.left})')
            return 1.0
        else:
            logger.info(f'Image is not on the left (left={shape.left}, expected={expected_left})')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking PPTX left position: {e}')
        return 0.0

