def check_ppt_slide_title__9732e237356c3d66867cd7ef7074217c(result, expected, **options):
    """Check if PowerPoint slide title matches expected values.

    Args:
        result: Dict from getter with 'text', 'color_rgb', 'bold', etc.
        expected: Dict with expected values (from rules)
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not expected:
        return 0.0
    score = 0.0
    checks = 0
    if 'text' in expected:
        checks += 1
        if result.get('text', '').strip().lower() == expected['text'].strip().lower():
            score += 1.0
    if 'color_rgb' in expected:
        checks += 1
        result_rgb = result.get('color_rgb')
        expected_rgb = expected['color_rgb']
        if result_rgb and expected_rgb:
            if result_rgb[0] == expected_rgb[0] and result_rgb[1] == expected_rgb[1] and (result_rgb[2] == expected_rgb[2]):
                score += 1.0
    if 'bold' in expected:
        checks += 1
        result_bold = result.get('bold')
        expected_bold = expected['bold']
        if result_bold is True and expected_bold is True or ((result_bold is None or result_bold is False) and (expected_bold is None or expected_bold is False)):
            score += 1.0
    if checks == 0:
        return 0.0
    return score / checks

def check_pptx_note_and_bg__3b49735e(result, expected, **options):
    """Compare PowerPoint note and background color with partial credit.
    
    Args:
        result: dict with "note" and "bg_color" keys from getter
        expected: dict with "note" (str) and "bg_color" (tuple of RGB) keys
        **options: Additional options (unused)
        
    Returns:
        float: Score between 0.0 and 1.0
            - 0.5 if note matches
            - 0.5 if background color matches
            - 1.0 if both match
            - 0.0 if neither matches
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    result_note = result.get('note', '')
    expected_note = expected.get('note', '')
    if result_note == expected_note:
        score += 0.5
    result_bg = result.get('bg_color')
