def check_pptx_slide1_subtitle_red__a2d93212(result_file, expected, **options):
    """
    Check if slide 1 subtitle 'Marketing' is colored red.

    Args:
        result_file: Path to the PPTX file
        expected: Expected RGB color (red)
        **options: Additional options

    Returns:
        float: 1.0 if subtitle is red, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        if len(prs.slides) < 1:
            return 0.0
        slide = prs.slides[0]
        subtitle_shape = None
        for shape in slide.shapes:
            if hasattr(shape, 'placeholder_format'):
                if shape.placeholder_format.idx == 2:
                    subtitle_shape = shape
                    break
        if subtitle_shape is None:
            for shape in slide.shapes:
                if hasattr(shape, 'text') and shape.text.strip() == 'Marketing':
                    subtitle_shape = shape
                    break
        if subtitle_shape is None:
            return 0.0
        if not hasattr(subtitle_shape, 'text_frame'):
            return 0.0
        subtitle_text = subtitle_shape.text.strip()
        if subtitle_text != 'Marketing':
            return 0.0
        found_marketing_run = False
        all_runs_red = True
        for para in subtitle_shape.text_frame.paragraphs:
            for run in para.runs:
                run_text = run.text.strip()
                if not run_text:
                    continue
                found_marketing_run = True
                if hasattr(run.font.color, 'rgb') and run.font.color.rgb is not None:
                    rgb = run.font.color.rgb
                    if not (rgb.r > 200 and rgb.g < 50 and (rgb.b < 50)):
                        all_runs_red = False
                        break
                else:
                    all_runs_red = False
                    break
            if not all_runs_red:
                break
        if found_marketing_run and all_runs_red:
            return 1.0
        return 0.0
    except Exception as e:
        return 0.0

