def check_pptx_image_size__bfde88d0(result_file, expected, **options):
    """
    Check if PPTX file has the specific image 'none.png' with expected dimensions on specified slide.

    Args:
        result_file: Path to the PPTX file
        expected: Dictionary with rules containing:
            - slide_index: 0-based slide index
            - expected_width_cm: Expected width in cm
            - expected_height_cm: Expected height in cm
            - tolerance_cm: Tolerance in cm (default 0.05)
        **options: Additional options

    Returns:
        float: 1.0 if the correct image found with matching size, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_index = expected.get('slide_index', 0)
        expected_width_cm = expected.get('expected_width_cm', 0)
        expected_height_cm = expected.get('expected_height_cm', 0)
        tolerance_cm = expected.get('tolerance_cm', 0.05)
        if slide_index >= len(prs.slides):
            logger.error(f'Slide index {slide_index} out of range (presentation has {len(prs.slides)} slides)')
            return 0.0
        slide = prs.slides[slide_index]
        expected_width_emu = expected_width_cm * 360000
        expected_height_emu = expected_height_cm * 360000
        tolerance_emu = tolerance_cm * 360000
        reference_image_path = '/home/user/Desktop/none.png'
        reference_hash = None
        if os.path.exists(reference_image_path):
            try:
                with open(reference_image_path, 'rb') as f:
                    reference_hash = hashlib.md5(f.read()).hexdigest()
                logger.info(f'Reference image hash: {reference_hash}')
            except Exception as e:
                logger.warning(f'Could not read reference image: {e}')
        else:
            logger.warning(f'Reference image not found at {reference_image_path}')
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.PICTURE or shape.shape_type == 13:
                width_match = abs(shape.width - expected_width_emu) <= tolerance_emu
                height_match = abs(shape.height - expected_height_emu) <= tolerance_emu
                if width_match and height_match:
                    actual_width_cm = shape.width / 360000
                    actual_height_cm = shape.height / 360000
                    logger.info(f'Found image with matching dimensions on slide {slide_index + 1}: {actual_width_cm:.2f}cm x {actual_height_cm:.2f}cm (expected {expected_width_cm}cm x {expected_height_cm}cm)')
                    if reference_hash:
                        try:
                            image_blob = shape.image.blob
                            image_hash = hashlib.md5(image_blob).hexdigest()
                            logger.info(f'Inserted image hash: {image_hash}')
                            if image_hash == reference_hash:
                                logger.info('Image identity verified: this is none.png')
                                return 1.0
                            else:
                                logger.warning(f'Found image with correct dimensions but different content (hash mismatch: {image_hash} vs {reference_hash})')
                        except Exception as e:
                            logger.error(f'Error verifying image identity: {e}')
                            return 1.0
                    else:
                        logger.info('Reference image not available, accepting based on dimensions')
                        return 1.0
        logger.error(f"No image 'none.png' with dimensions {expected_width_cm}cm x {expected_height_cm}cm found on slide {slide_index + 1}")
        return 0.0
    except Exception as e:
        logger.error(f'Error checking image size: {e}')
        return 0.0

