def check_slide_text_contains__ec78028f(result_file, expected, **options):
    """
    Check if specific slides contain expected text and verify text replacements.

    This function verifies that text replacements have been made correctly
    in LibreOffice Impress slides. It checks each slide specified in the rules
    to ensure it contains the expected text and that the original text has been removed.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing 'checks' list. When expected.type='rule', the framework's
                  get_rule returns config['rules'] directly, so expected IS the rules dictionary.
                  Each check has:
                  - 'slide_idx' (0-indexed)
                  - 'text_contains' (text that should be present)
                  - 'text_not_contains' (optional, text that should be absent)
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        checks = expected.get('checks', [])
        if not checks:
            return 0.0
        for check in checks:
            slide_idx = check.get('slide_idx', 0)
            text_contains = check.get('text_contains', '')
            text_not_contains = check.get('text_not_contains', '')
            if slide_idx >= len(prs.slides):
                logger.error(f'Slide {slide_idx} does not exist (total slides: {len(prs.slides)})')
                return 0.0
            slide = prs.slides[slide_idx]
            slide_text = ''
            for shape in slide.shapes:
                if hasattr(shape, 'text'):
                    slide_text += shape.text + ' '
            if text_contains and text_contains.lower() not in slide_text.lower():
                logger.error(f"Slide {slide_idx} does not contain '{text_contains}'. Slide text: {slide_text.strip()}")
                return 0.0
            if text_not_contains and text_not_contains.lower() in slide_text.lower():
                logger.error(f"Slide {slide_idx} still contains '{text_not_contains}' which should have been removed. Slide text: {slide_text.strip()}")
                return 0.0
        return 1.0
    except Exception as e:
        logger.error(f'Error checking slide text: {e}')
        return 0.0

