def check_pptx_title_format__c33d5d35(result_file, expected, **options):
    """
    Check if the title text in the first slide has the expected bold and font size formatting.

    The task requires making the title text bold and increasing its font size to 72 points (914400 EMUs).

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing:
            - 'font_size': Expected font size in EMUs (914400 for 72pt)
            - 'bold': Expected bold status (True)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
            - 1.0 if both font size and bold are correct for ALL runs
            - 0.5 if only one is correct
            - 0.0 if neither is correct
    """
    try:
        prs = Presentation(result_file)
        expected_font_size = expected.get('font_size', 914400)
        expected_bold = expected.get('bold', True)
        if len(prs.slides) == 0:
            logger.error('No slides found in presentation')
            return 0.0
        slide = prs.slides[0]
        title_shape = None
        for shape in slide.shapes:
            if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                if hasattr(shape, 'is_placeholder') and shape.is_placeholder:
                    if shape.text.strip():
                        title_shape = shape
                        break
                elif title_shape is None and shape.text.strip():
                    title_shape = shape
        if title_shape is None:
            logger.error('Title shape not found in first slide')
            return 0.0
        all_runs = []
        for paragraph in title_shape.text_frame.paragraphs:
            for run in paragraph.runs:
                if run.text.strip():
                    all_runs.append(run)
        if not all_runs:
            logger.error('No text runs found in title shape')
            return 0.0
        font_size_correct = all((run.font.size == expected_font_size for run in all_runs))
        bold_correct = all((run.font.bold == expected_bold for run in all_runs))
        score = 0.0
        if font_size_correct:
            score += 0.5
        if bold_correct:
            score += 0.5
        return score
    except Exception as e:
        logger.error(f'Error checking PPTX title format: {e}')
        return 0.0

