def check_pptx_slide_order__21f0ef93(result, expected, **options):
    """Check if presentation has correct slide count and last slide contains expected text.
    
    Args:
        result: Path to the PPTX file
        expected: Dict with 'total_slides' and 'last_slide_text'
        **options: Additional options
        
    Returns:
        float: 0.5 if slide count correct, 1.0 if last slide has expected text
    """
    try:
        total_slides = expected.get('total_slides', 0)
        last_slide_text = expected.get('last_slide_text', '')
        prs = Presentation(result)
        actual_count = len(prs.slides)
        if actual_count != total_slides:
            return 0.0
        score = 0.5
        if actual_count > 0:
            last_slide = prs.slides[-1]
            found_text = any((last_slide_text in shape.text for shape in last_slide.shapes if hasattr(shape, 'text')))
            if found_text:
                score = 1.0
        return score
    except Exception as e:
        print(f'Error checking slide order: {e}')
        return 0.0

def check_pptx_table_larger__9e1f27421b5976ffe8c97d6f5248ed0c(result, expected, **options):
    """
    Check if table has been resized to be larger.

    Args:
        result: Dict with table size from getter
        expected: Dict with rules {'min_width': int, 'min_height': int}
        **options: Additional options

    Returns:
        float: 1.0 if table is larger than specified dimensions, 0.0 otherwise
    """
    if result is None:
        return 0.0
    min_width = expected.get('min_width', 8000000)
