    result_text = result.get('text', '').strip()
    result_color = result.get('color')
    expected_text = expected.get('text', '').strip()
    expected_color = expected.get('color')
    text_match = result_text == expected_text
    color_match = result_color == expected_color
    if text_match and color_match:
        return 1.0
    elif text_match or color_match:
        return 0.5
    else:
        return 0.0

