def check_slides_with_notes__f84e3848c788254387c79a0944166381(result, expected, **options):
    """Check if list of slides with notes matches expected list.

    Args:
        result: List of integers from getter (slide numbers with notes)
        expected: Dict with 'expected_slides' key containing list of expected slide numbers
        **options: Additional options (not used)

    Returns:
        float: 1.0 if lists match exactly, partial credit for partial match
    """
    if not isinstance(result, list):
        return 0.0
    expected_slides = expected.get('expected_slides', [])
    if not expected_slides:
        return 0.0
    result_sorted = sorted(result)
    expected_sorted = sorted(expected_slides)
    if result_sorted == expected_sorted:
        return 1.0
    correct = len(set(result_sorted) & set(expected_sorted))
    false_positives = len(set(result_sorted) - set(expected_sorted))
    score = max(0.0, (correct - false_positives) / len(expected_sorted))
    return score

