def check_pptx_slide_all_text_centered__8e12333f(result_state, expected_state, **options):
    """
    Check if all textboxes on a specific slide are center-aligned.

    Args:
        result_state: Path to the PPTX file
        expected_state: Dict with 'slide_index' key specifying which slide to check (0-indexed)
        **options: Additional options

    Returns:
        float: 1.0 if all text is centered, 0.0 otherwise
    """
    try:
        pptx_file = result_state
        slide_index = expected_state.get('slide_index', 0)
        if not os.path.exists(pptx_file):
            logger.error(f'PPTX file not found: {pptx_file}')
            return 0.0
        prs = Presentation(pptx_file)
        if slide_index >= len(prs.slides):
            logger.error(f'Slide index {slide_index} out of range (total slides: {len(prs.slides)})')
            return 0.0
        slide = prs.slides[slide_index]

        def get_all_text_shapes(shape):
            results = []
            if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                results.append(shape)
            if hasattr(shape, 'shapes'):
                for sub_shape in shape.shapes:
                    results.extend(get_all_text_shapes(sub_shape))
            return results
        all_text_shapes = []
        for shape in slide.shapes:
            all_text_shapes.extend(get_all_text_shapes(shape))
        if not all_text_shapes:
            logger.info(f'No text shapes found on slide {slide_index}')
            return 1.0
        for shape in all_text_shapes:
            if not hasattr(shape, 'text_frame'):
                continue
            for paragraph in shape.text_frame.paragraphs:
                if not paragraph.text.strip():
                    continue
                alignment = paragraph.alignment
                if alignment != PP_ALIGN.CENTER:
                    logger.debug(f"Found non-centered text: '{paragraph.text.strip()}' with alignment: {alignment}")
                    return 0.0
        return 1.0
    except Exception as e:
        logger.error(f'Error checking slide text alignment: {e}')
        return 0.0

def check_pptx_property__cfed666e(result, expected, **options):
    """
    Compare paragraph property against expected value.

    Args:
        result: Property value from getter
        expected: Expected value or dict of expected values
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass)
    """
    if result is None:
        return 0.0
    property_type = expected.get('property', 'level')
    expected_value = expected.get('value')
    if property_type in ['level', 'alignment']:
        if isinstance(result, int):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type in ['bold', 'italic', 'underline']:
        if isinstance(result, bool):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type == 'color':
        if isinstance(result, list) and len(result) == 3:
            expected_rgb = expected_value
            if isinstance(expected_rgb, list) and len(expected_rgb) == 3:
                return 1.0 if result == expected_rgb else 0.0
        return 0.0
    elif property_type == 'bold_italic':
        if isinstance(result, dict):
            bold_match = result.get('bold', False) == expected_value
            italic_match = result.get('italic', False) == expected_value
            return 1.0 if bold_match and italic_match else 0.0
        return 0.0
    return 0.0

def check_pptx_duplicate_slide__bf5f7d35(result, expected, **options):
    """Check if presentation has correct slide count and specific slides contain expected text.
    
    Args:
        result: Path to the PPTX file
        expected: Dict with 'total_slides', 'slide_index_1', 'slide_index_2', 'text_to_match'
        **options: Additional options
        
    Returns:
        float: 0.5 if slide count correct, 1.0 if both slides have matching text
    """
    try:
        total_slides = expected.get('total_slides', 0)
        idx1 = expected.get('slide_index_1', 1)
        idx2 = expected.get('slide_index_2', 2)
        text_to_match = expected.get('text_to_match', '')
        prs = Presentation(result)
        actual_count = len(prs.slides)
        if actual_count != total_slides:
            return 0.0
        score = 0.5
        if idx1 < actual_count and idx2 < actual_count:
            slide1 = prs.slides[idx1]
            slide2 = prs.slides[idx2]
            found_in_slide1 = any((text_to_match in shape.text for shape in slide1.shapes if hasattr(shape, 'text')))
            found_in_slide2 = any((text_to_match in shape.text for shape in slide2.shapes if hasattr(shape, 'text')))
            if found_in_slide1 and found_in_slide2:
                score = 1.0
        return score
    except Exception as e:
        print(f'Error checking duplicate slide: {e}')
        return 0.0

def check_pptx_bullets__d9336aa8(result, expected, **options):
    """Check if slide contains all expected bullet points.

    Args:
        result: Content dict from getter with text_items
        expected: Expected bullets list
        **options: Additional options (partial_match: bool)

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_bullets = expected.get('bullets', [])
    partial_match = options.get('partial_match', True)
    if not expected_bullets:
        return 1.0
    all_text = ' '.join(result.get('text_items', [])).lower()
    found_count = 0
    for bullet in expected_bullets:
        bullet_lower = bullet.lower()
        if partial_match:
            if bullet_lower in all_text:
                found_count += 1
        else:
            text_items = result.get('text_items', [])
            if any((bullet_lower == item.lower().strip() for item in text_items)):
                found_count += 1
    score = found_count / len(expected_bullets) if expected_bullets else 1.0
    return min(score, 1.0)

def check_pptx_slide4_font_and_slide5_height__2475be345212f79e06adf01ec38a2749(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if slide 4 title fonts match expected size AND slide 5 has a picture with expected height.

    This metric checks two conditions with partial credit:
    - 0.5 points: Title textboxes on slide 4 have the expected font size
    - 0.5 points: At least one picture on slide 5 has the expected height

    Args:
        result: Dict containing 'slide4_fonts' (list) and 'slide5_heights' (list of heights in cm)
        expected: Dict with 'target_font_size' and 'target_height_cm'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    tolerance = options.get('tolerance', 0.1)
    slide4_fonts = result.get('slide4_fonts', [])
    target_font = expected.get('target_font_size', 0)
    if slide4_fonts and target_font:
        if all((abs(font - target_font) < 0.1 for font in slide4_fonts)):
            score += 0.5
    slide5_heights = result.get('slide5_heights', [])
    target_height = expected.get('target_height_cm', 0)
    if slide5_heights and target_height:
        if any((abs(height - target_height) <= tolerance for height in slide5_heights)):
            score += 0.5
    return score

def check_pptx_text_replacement__17fe2a8956c7b5ec3c559f223d885d05(result, expected, **options):
    """Check if text replacement was performed correctly on a slide.

    Args:
        result: List of lists, where each inner list contains all text from one slide
        expected: Dict with keys:
            - slide_index: Index of the slide to check (0-based)
            - should_contain: Text that should be present after replacement
            - should_not_contain: Text that should NOT be present after replacement

    Returns:
        float: 0.5 if new text is present, 1.0 if new text is present AND old text is gone
    """
    if not isinstance(result, list):
        return 0.0
    slide_index = expected.get('slide_index', 0)
    should_contain = expected.get('should_contain', '')
    should_not_contain = expected.get('should_not_contain', '')
    if slide_index >= len(result):
        return 0.0
    slide_texts = result[slide_index]
    combined_text = ' '.join(slide_texts).lower()
    has_new_text = should_contain.lower() in combined_text
    has_old_text = should_not_contain.lower() in combined_text
    if has_new_text and (not has_old_text):
        return 1.0
    elif has_new_text:
        return 0.5
    else:
        return 0.0

