def check_pptx_table_row__0226bb33(result, expected, **options):
    """Check if table row values match expected.

    Args:
        result: List of actual cell texts
        expected: List of expected cell texts
        **options: Additional options

    Returns:
        float: 1.0 if all match, 0.0 otherwise
    """
    if result is None or not isinstance(result, list):
        return 0.0
    if not isinstance(expected, list) or len(result) != len(expected):
        return 0.0
