def check_pptx_modifications__e0ca1d72(result_file, expected, **options):
    """
    Check PowerPoint modifications for variation 3.

    Verifies:
    - Image dimensions (width/height) on specified slides with proportional partial credit
    - Body text font sizes on specified slides with proportional partial credit

    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with slide indices and expected values
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (proportional partial credit for each requirement)
    """
    try:
        prs = Presentation(result_file)
        score = 0.0
        tolerance_cm = options.get('tolerance_cm', 0.5)
        tolerance_pt = options.get('tolerance_pt', 2.0)
        if 'image_slide_idx' in expected:
            image_slide_idx = expected['image_slide_idx']
            if image_slide_idx < len(prs.slides):
                slide = prs.slides[image_slide_idx]
                images = [shape for shape in slide.shapes if shape.shape_type == MSO_SHAPE_TYPE.PICTURE]
                if not images:
                    pass
                else:
                    matching_images = 0
                    for img in images:
                        matches = True
                        if 'expected_width_cm' in expected:
                            width_cm = img.width / 360000
                            expected_width = expected['expected_width_cm']
                            if abs(width_cm - expected_width) > tolerance_cm:
                                matches = False
                        if matches and 'expected_height_cm' in expected:
                            height_cm = img.height / 360000
                            expected_height = expected['expected_height_cm']
                            if abs(height_cm - expected_height) > tolerance_cm:
                                matches = False
                        if matches:
                            matching_images += 1
                    score += 0.5 * (matching_images / len(images))
        if 'text_slide_idx' in expected:
            text_slide_idx = expected['text_slide_idx']
            if text_slide_idx < len(prs.slides):
                slide = prs.slides[text_slide_idx]
                expected_font_size = expected.get('expected_font_size', None)
                if expected_font_size:
                    body_text_shapes = []
                    for shape in slide.shapes:
                        if hasattr(shape, 'text_frame'):
                            is_title = False
                            if hasattr(shape, 'placeholder_format'):
                                try:
                                    if shape.placeholder_format.type in [1, 3]:
                                        is_title = True
                                except:
                                    pass
                            if not is_title:
                                body_text_shapes.append(shape)
                    if not body_text_shapes:
                        pass
                    else:
                        total_runs = 0
                        matching_runs = 0
                        for shape in body_text_shapes:
                            for paragraph in shape.text_frame.paragraphs:
                                for run in paragraph.runs:
                                    if run.text.strip() and run.font.size:
                                        total_runs += 1
                                        font_size_pt = run.font.size.pt
                                        if abs(font_size_pt - expected_font_size) <= tolerance_pt:
                                            matching_runs += 1
                        if total_runs == 0:
                            pass
                        else:
                            score += 0.5 * (matching_runs / total_runs)
        return score
    except Exception as e:
        print(f'Error checking PPTX: {e}')
        return 0.0

def check_slide_dimensions__76b25b299b0f99df101b8296ac321ee4(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if slide dimensions match expected values.

    Args:
        result: Dict with slide dimensions from getter
        expected: Dict with expected orientation or dimensions

    Returns:
        float: 1.0 if dimensions match, 0.0 otherwise
    """
    if not result:
        logger.error('No slide dimension data received')
        return 0.0
    expected_orientation = expected.get('orientation')
    expected_width = expected.get('width')
    expected_height = expected.get('height')
    result_orientation = result.get('orientation')
    result_width = result.get('width')
    result_height = result.get('height')
    if expected_orientation:
        if result_orientation == expected_orientation:
            logger.info(f'Slide orientation matches: {expected_orientation}')
            return 1.0
        else:
            logger.warning(f'Slide orientation mismatch: expected {expected_orientation}, got {result_orientation}')
            return 0.0
    if expected_width and expected_height:
        tolerance = options.get('dimension_tolerance', 1000)
        width_match = abs(result_width - expected_width) <= tolerance
        height_match = abs(result_height - expected_height) <= tolerance
        if width_match and height_match:
            logger.info(f'Slide dimensions match: {result_width}x{result_height}')
            return 1.0
        else:
            logger.warning(f'Slide dimensions mismatch: expected {expected_width}x{expected_height}, got {result_width}x{result_height}')
            return 0.0
    logger.warning('No orientation or dimensions specified in expected config')
    return 0.0

def check_pptx_slide5_font_and_slide4_pics__ba8f3d84f3c877fa2fe00194eab7f5ec(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if slide 5 title font matches AND slide 4 has a picture with expected width.

    This metric checks two conditions with partial credit:
    - 0.5 points: "Our Products" title on slide 5 has the expected font size
    - 0.5 points: At least one picture on slide 4 has the expected width

    Args:
        result: Dict containing 'slide5_font' (font size) and 'slide4_widths' (list of widths in cm)
        expected: Dict with 'target_font_size' and 'target_width_cm'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    tolerance = options.get('tolerance', 0.1)
    slide5_font = result.get('slide5_font', 0)
    target_font = expected.get('target_font_size', 0)
    if slide5_font and target_font:
        if abs(slide5_font - target_font) < 0.1:
            score += 0.5
    slide4_widths = result.get('slide4_widths', [])
    target_width = expected.get('target_width_cm', 0)
    if slide4_widths and target_width:
        if any((abs(width - target_width) <= tolerance for width in slide4_widths)):
            score += 0.5
    return score

