def check_slide_background_color__d1d6f3e1(result_file, expected, **options):
    """
    Check if a specific slide has the expected background color.

    Args:
        result_file: Path to the PPTX file
        expected: Dict with 'slide_idx' (0-indexed) and 'target_rgb' (list of [R, G, B])
        **options: Additional options

    Returns:
        float: 1.0 if background color matches, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        target_rgb = expected.get('target_rgb', [0, 0, 0])
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        fill = slide.background.fill
        if fill.type == 1:
            if hasattr(fill.fore_color, 'rgb'):
                actual_rgb = fill.fore_color.rgb
                (r, g, b) = actual_rgb
                if r == target_rgb[0] and g == target_rgb[1] and (b == target_rgb[2]):
                    return 1.0
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                if hasattr(master_fill.fore_color, 'rgb'):
                    actual_rgb = master_fill.fore_color.rgb
                    (r, g, b) = actual_rgb
                    if r == target_rgb[0] and g == target_rgb[1] and (b == target_rgb[2]):
                        return 1.0
        return 0.0
    except Exception as e:
        return 0.0

def check_slide_title_alignment__c5ce7bacd6c2e3efaa5ab726c35e3ecf(result_state, expected, **options):
    """
    Check if a specific slide has the expected title text with the expected alignment.

    Args:
        result_state: Path to the PowerPoint file (from vm_file)
        expected: Dict with keys:
            - slide_index: 0-based slide index
            - text: Expected title text
            - alignment: Expected alignment (e.g., "LEFT", "CENTER", "RIGHT")
        **options: Additional options

    Returns:
        float: 1.0 if title matches text and alignment, 0.0 otherwise
    """
    try:
        file_path = result_state
        prs = Presentation(file_path)
        slide_index = expected.get('slide_index', 0)
        expected_text = expected.get('text', '')
        expected_alignment = expected.get('alignment', 'LEFT')
        alignment_map = {'LEFT': PP_ALIGN.LEFT, 'CENTER': PP_ALIGN.CENTER, 'RIGHT': PP_ALIGN.RIGHT, 'JUSTIFY': PP_ALIGN.JUSTIFY, 1: PP_ALIGN.LEFT, 2: PP_ALIGN.CENTER, 3: PP_ALIGN.RIGHT, 4: PP_ALIGN.JUSTIFY}
        if isinstance(expected_alignment, str):
            expected_alignment = alignment_map.get(expected_alignment.upper(), PP_ALIGN.LEFT)
        elif isinstance(expected_alignment, int):
            expected_alignment = alignment_map.get(expected_alignment, PP_ALIGN.LEFT)
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        title_shape = None
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and hasattr(shape, 'text'):
                text_content = shape.text.strip()
                if text_content == expected_text.strip():
                    if hasattr(shape, 'is_placeholder') and shape.is_placeholder:
                        title_shape = shape
                        break
                    elif title_shape is None:
                        title_shape = shape
        if title_shape is None:
            return 0.0
        if title_shape.text.strip() != expected_text.strip():
            return 0.0
        if len(title_shape.text_frame.paragraphs) == 0:
            return 0.0
        para = title_shape.text_frame.paragraphs[0]
        actual_alignment = para.alignment
        if actual_alignment is None:
            actual_alignment = PP_ALIGN.LEFT
        if actual_alignment != expected_alignment:
            return 0.0
        return 1.0
    except Exception as e:
        print(f'Error checking slide title: {e}')
        return 0.0

def check_pptx_duplicated_slides__34252707cc931e8d38a7d24b270d326d(result, expected, **options):
    """Check if specific slides were duplicated correctly.

    Args:
        result: Slide information from getter
        expected: Expected configuration with original_slides and target_positions

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or 'slides' not in result:
        return 0.0
    slides = result['slides']
    original_count = expected.get('original_count', 0)
    duplicated_indices = expected.get('duplicated_indices', [])
    expected_final_count = expected.get('expected_final_count', 0)
    if result['slide_count'] != expected_final_count:
        return 0.0
    score = 0.0
    if result['slide_count'] == expected_final_count:
        score += 0.5
    if len(duplicated_indices) >= 2:
        (idx1, idx2) = (duplicated_indices[0], duplicated_indices[1])
        if idx1 < len(slides) and idx2 < len(slides):
            slide1_orig = slides[idx1]
            slide2_orig = slides[idx2]
            copy1_pos = idx2 + 1
            copy2_pos = idx2 + 2
            if copy1_pos < len(slides) and copy2_pos < len(slides):
                slide1_copy = slides[copy1_pos]
                slide2_copy = slides[copy2_pos]
                texts_match_1 = slide1_orig.get('texts', []) == slide1_copy.get('texts', [])
                texts_match_2 = slide2_orig.get('texts', []) == slide2_copy.get('texts', [])
                if texts_match_1 and texts_match_2:
                    score += 0.5
    return score

