    if result_bg is not None and expected_bg is not None:
        if hasattr(result_bg, '__iter__'):
            result_rgb = tuple(result_bg)
        else:
            result_rgb = result_bg
        if hasattr(expected_bg, '__iter__'):
            expected_rgb = tuple(expected_bg)
        else:
            expected_rgb = expected_bg
        if result_rgb == expected_rgb:
            score += 0.5
    return score

