def check_slide2_bg_color__6f6009a16d6153d7939a21c7c2e8d528(result, expected, **options):
    """Check if slide 2 has the expected background color.

    Args:
        result: Path to the PPTX file
        expected: Dict with 'rgb' key containing target RGB color and 'slide_index' for the slide

    Returns:
        float: Score between 0.0 and 1.0 based on color distance
    """
    if not result:
        return 0.0
    slide_index = expected.get('slide_index', 1)
    target_rgb = expected['rgb']

    def get_rgb_from_color(color):
        try:
            if hasattr(color, 'rgb'):
                return color.rgb
            else:
                return None
        except:
            return None
    try:
        prs = Presentation(result)
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        fill = slide.background.fill
        if fill.type == 1:
            color_rgb = get_rgb_from_color(fill.fore_color)
            if color_rgb is None:
                return 0.0
            (r1, g1, b1) = color_rgb
            (r2, g2, b2) = target_rgb
            distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
            max_distance = sqrt(255 ** 2 + 255 ** 2 + 255 ** 2)
            similarity = 1 - distance / max_distance
            threshold = options.get('threshold', 0.9)
            return 1.0 if similarity >= threshold else similarity
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                color_rgb = get_rgb_from_color(master_fill.fore_color)
                if color_rgb is None:
                    return 0.0
                (r1, g1, b1) = color_rgb
                (r2, g2, b2) = target_rgb
                distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
                max_distance = sqrt(255 ** 2 + 255 ** 2 + 255 ** 2)
                similarity = 1 - distance / max_distance
                threshold = options.get('threshold', 0.9)
                return 1.0 if similarity >= threshold else similarity
        return 0.0
    except Exception as e:
        return 0.0

def check_slide_bg_color__8cae14f23c457da246291dab85df0b39(result: Optional[Tuple[int, int, int]], expected: dict, **options) -> float:
    """Check if slide background color matches expected RGB value.

    Args:
        result: RGB tuple from getter (r, g, b) or None
        expected: Dict from rules containing:
            - target_rgb: Target RGB tuple (r, g, b)
            - tolerance: Max Euclidean distance to accept (default: 30)
        **options: Additional options

    Returns:
        1.0 if color matches within tolerance, 0.0 otherwise
    """
    target_rgb = expected.get('target_rgb')
    tolerance = expected.get('tolerance', 30)
    if result is None:
        return 0.0
    if target_rgb is None:
        return 0.0
    (r1, g1, b1) = result
    (r2, g2, b2) = target_rgb
    distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
    return 1.0 if distance <= tolerance else 0.0

def check_slides_pane_restored__2889450c(accessibility_tree, expected, **options):
    """
    Verify that the slides pane has been restored in LibreOffice Impress.

    Args:
        accessibility_tree: XML string of the accessibility tree
        expected: Dict with required_panel name
        **options: Additional options

    Returns:
        float: 1.0 if pane is restored, 0.0 otherwise
    """
    try:
        root = ET.fromstring(accessibility_tree)
        required_panel = expected.get('required_panel', 'Slides View')
        for element in root.iter():
            element_name = element.attrib.get('name', '')
            if element_name == required_panel or required_panel in element_name:
                showing = element.attrib.get('showing', '').lower()
                visible = element.attrib.get('visible', '').lower()
                if showing in ('', 'true', '1') and visible in ('', 'true', '1'):
                    return 1.0
            text = element.text or ''
            if required_panel in text:
                showing = element.attrib.get('showing', '').lower()
                visible = element.attrib.get('visible', '').lower()
                if showing in ('', 'true', '1') and visible in ('', 'true', '1'):
                    return 1.0
        return 0.0
    except Exception as e:
        logger.error(f'Error parsing accessibility tree: {e}')
        return 0.0

