def check_pptx_bold_textboxes__96b3b1ae(result_file, expected, **options):
    """
    Check if all textboxes on specified slides have bold formatting.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing slides list and check_bold flag
        **options: Additional options

    Returns:
        float: 1.0 if all text is bold on specified slides, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slides_to_check = expected.get('slides', [])
        for slide_idx in slides_to_check:
            if slide_idx >= len(prs.slides):
                return 0.0
            slide = prs.slides[slide_idx]
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame') and hasattr(shape, 'text'):
                    text_frame = shape.text_frame
                    for paragraph in text_frame.paragraphs:
                        for run in paragraph.runs:
                            if not run.text.strip():
                                continue
                            if run.font.bold is not True:
                                return 0.0
        return 1.0
    except Exception as e:
        return 0.0

def check_pptx_slide_font__3497c1fc(result_path, expected, **options):
    """
    Check if slide 0 has font Arial.
    
    Args:
        result_path: Path to the result PPTX file
        expected: Expected configuration (dict with slide_index and font_name)
        **options: Additional options
        
    Returns:
        float: 1.0 if all text in the slide has the expected font, 0.0 otherwise
    """
    try:
        prs = Presentation(result_path)
        slide_index = expected.get('slide_index', 0)
        expected_font = expected.get('font_name', 'Arial')
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        found_text = False
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                text_frame = shape.text_frame
                for paragraph in text_frame.paragraphs:
                    for run in paragraph.runs:
                        found_text = True
                        if run.font.name and run.font.name != expected_font:
                            return 0.0
        return 1.0 if found_text else 0.0
    except Exception as e:
        print(f'Error checking slide font: {e}')
        return 0.0

def check_pptx_picture_position__24cf51635919752587d60bc50fdfd904(result, expected, **options):
    """Compare picture position to verify it's on the left side of the slide.

    Args:
        result: Position dict from getter
        expected: Expected position from rules with:
            - left_side_max: Maximum left position to be considered "left side" (in EMUs)
            - tolerance: Allowed tolerance for the position check (in EMUs)
        **options: Additional comparison options

    Returns:
        float: 1.0 if picture is on the left side of the slide, 0.0 otherwise
    """
    if result is None:
        return 0.0
    tolerance = expected.get('tolerance', 100000)
