def check_pptx_shape_size__3b2512e8(result_file, expected, **options):
    """
    Check if a shape in a specific slide has the expected size.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing 'slide_idx', 'shape_idx', 'expected_width', 'expected_height'
        **options: Additional options including 'approximately_tolerance'

    Returns:
        float: 1.0 if size matches (within tolerance), 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 0)
        expected_width = expected.get('expected_width', None)
        expected_height = expected.get('expected_height', None)
        min_width = expected.get('min_width', None)
        max_width = expected.get('max_width', None)
        min_height = expected.get('min_height', None)
        max_height = expected.get('max_height', None)
        approximately_tolerance = options.get('approximately_tolerance', 0.005)

        def is_approximately_equal(val1, val2, tolerance=approximately_tolerance):
            """Compare two values with a tolerance."""
            if val1 == val2:
                return True
            if val1 == 0 and val2 == 0:
                return True
            if val1 == 0 or val2 == 0:
                return False
            return abs(val1 - val2) / max(abs(val1), abs(val2)) <= tolerance
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if expected_width is not None:
            if not is_approximately_equal(shape.width, expected_width):
                return 0.0
        if expected_height is not None:
            if not is_approximately_equal(shape.height, expected_height):
                return 0.0
        if min_width is not None and shape.width < min_width:
            if not is_approximately_equal(shape.width, min_width):
                return 0.0
        if max_width is not None and shape.width > max_width:
            if not is_approximately_equal(shape.width, max_width):
                return 0.0
        if min_height is not None and shape.height < min_height:
            if not is_approximately_equal(shape.height, min_height):
                return 0.0
        if max_height is not None and shape.height > max_height:
            if not is_approximately_equal(shape.height, max_height):
                return 0.0
        return 1.0
    except Exception as e:
        return 0.0

def check_pptx_image_size__ca0cb440(result_file, expected, **options):
    """
    Check if PPTX file has an image with expected dimensions and filename on specified slide.

    Args:
        result_file: Path to the PPTX file
        expected: Dictionary with rules containing:
            - slide_index: 0-based slide index
            - expected_width_cm: Expected width in cm
            - expected_height_cm: Expected height in cm
            - tolerance_cm: Tolerance in cm (default 0.05)
            - expected_image_name: Expected image filename (optional, e.g., 'none.png')
        **options: Additional options

    Returns:
        float: 1.0 if image found with matching size and name, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_index = expected.get('slide_index', 0)
        expected_width_cm = expected.get('expected_width_cm', 0)
        expected_height_cm = expected.get('expected_height_cm', 0)
        tolerance_cm = expected.get('tolerance_cm', 0.05)
        expected_image_name = expected.get('expected_image_name', None)
        if slide_index >= len(prs.slides):
            logger.error(f'Slide index {slide_index} out of range (presentation has {len(prs.slides)} slides)')
            return 0.0
        slide = prs.slides[slide_index]
        expected_width_emu = expected_width_cm * 360000
        expected_height_emu = expected_height_cm * 360000
        tolerance_emu = tolerance_cm * 360000
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.PICTURE or shape.shape_type == 13:
                width_match = abs(shape.width - expected_width_emu) <= tolerance_emu
                height_match = abs(shape.height - expected_height_emu) <= tolerance_emu
                if width_match and height_match:
                    actual_width_cm = shape.width / 360000
                    actual_height_cm = shape.height / 360000
                    if expected_image_name:
                        shape_name = shape.name.lower() if hasattr(shape, 'name') else ''
                        expected_name_lower = expected_image_name.lower()
                        image_filename = ''
                        if hasattr(shape, 'image') and hasattr(shape.image, 'filename'):
                            image_filename = shape.image.filename.lower() if shape.image.filename else ''
                        name_match = expected_name_lower in shape_name or expected_name_lower in image_filename or shape_name.endswith(expected_name_lower) or image_filename.endswith(expected_name_lower)
                        if not name_match:
                            logger.debug(f"Image dimensions match but name doesn't match: shape_name='{shape_name}', image_filename='{image_filename}', expected='{expected_image_name}'")
                            continue
                        logger.info(f"Found matching image '{expected_image_name}' on slide {slide_index + 1}: {actual_width_cm:.2f}cm x {actual_height_cm:.2f}cm (expected {expected_width_cm}cm x {expected_height_cm}cm)")
                    else:
                        logger.info(f'Found matching image on slide {slide_index + 1}: {actual_width_cm:.2f}cm x {actual_height_cm:.2f}cm (expected {expected_width_cm}cm x {expected_height_cm}cm)')
                    return 1.0
        if expected_image_name:
            logger.error(f"No image '{expected_image_name}' with dimensions {expected_width_cm}cm x {expected_height_cm}cm found on slide {slide_index + 1}")
        else:
            logger.error(f'No image with dimensions {expected_width_cm}cm x {expected_height_cm}cm found on slide {slide_index + 1}')
        return 0.0
    except Exception as e:
        logger.error(f'Error checking image size: {e}')
        return 0.0

def check_pptx_picture_size__756a7e4fc1309a419ce1f8647e44df35(result, expected, **options):
    """Check if picture has the expected dimensions.

    Args:
        result: dict with 'width' and 'height' keys (from getter)
        expected: dict with keys:
            - expected_width: int, expected width in EMU
            - expected_height: int, expected height in EMU
        **options: Additional options
            - tolerance: float, relative tolerance for comparison (default 0.05 = 5%)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    if result is None or 'width' not in result or 'height' not in result:
        return 0.0
    expected_width = expected.get('expected_width')
    expected_height = expected.get('expected_height')
    tolerance = options.get('tolerance', 0.05)
    if expected_width is None or expected_height is None:
        return 0.0
    actual_width = result['width']
    actual_height = result['height']
    width_diff = abs(actual_width - expected_width) / expected_width
    if width_diff > tolerance:
        return 0.0
    height_diff = abs(actual_height - expected_height) / expected_height
    if height_diff > tolerance:
        return 0.0
    return 1.0

def check_pptx_property__fa89fdd6(result, expected, **options):
    """
    Compare paragraph property against expected value.

    Args:
        result: Property value from getter
        expected: Expected value or dict of expected values
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass)
    """
    if result is None:
        return 0.0
    property_type = expected.get('property', 'alignment')
    expected_value = expected.get('value')
    if property_type in ['level', 'alignment']:
        if isinstance(result, int):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type in ['bold', 'italic', 'underline']:
        if isinstance(result, bool):
            return 1.0 if result == expected_value else 0.0
        elif isinstance(result, dict):
            all_match = all((val == expected_value for val in result.values()))
            return 1.0 if all_match else 0.0
    elif property_type == 'color':
        if isinstance(result, list) and len(result) == 3:
            expected_rgb = expected_value
            if isinstance(expected_rgb, list) and len(expected_rgb) == 3:
                return 1.0 if result == expected_rgb else 0.0
        return 0.0
    elif property_type == 'bold_italic':
        if isinstance(result, dict):
            bold_match = result.get('bold', False) == expected_value
            italic_match = result.get('italic', False) == expected_value
            return 1.0 if bold_match and italic_match else 0.0
        return 0.0
    return 0.0

