def check_pptx_background_color__ad551c61(result_file, expected, **options):
    """
    Check if a slide has a background color matching the expected color criteria.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing slide_idx and color criteria
        **options: Additional options

    Returns:
        float: 1.0 if background color matches criteria, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        is_blue_color = expected.get('is_blue_color', False)
        blue_threshold = expected.get('blue_threshold', 150)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        fill = slide.background.fill
        if fill.type == 1:
            if hasattr(fill.fore_color, 'rgb'):
                (r, g, b) = fill.fore_color.rgb
                if is_blue_color:
                    if b > blue_threshold and b > r and (b > g):
                        return 1.0
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                if hasattr(master_fill.fore_color, 'rgb'):
                    (r, g, b) = master_fill.fore_color.rgb
                    if is_blue_color:
                        if b > blue_threshold and b > r and (b > g):
                            return 1.0
        return 0.0
    except Exception as e:
        return 0.0

