def check_pptx_slide_notes__b333e93e44c3945bb7801a1c8890f27d(result, expected, **options):
    """Check if slide notes contain expected keywords.

    Args:
        result: Dictionary from getter with notes text
        expected: Dictionary with expected_keywords list
        **options: Additional options

    Returns:
        float: Score based on how many keywords are found
    """
    expected_keywords = expected.get('expected_keywords', [])
    if not expected_keywords:
        return 1.0
    notes_text = result.get('notes', '').lower()
    found_keywords = sum((1 for keyword in expected_keywords if keyword.lower() in notes_text))
    return found_keywords / len(expected_keywords)

