def check_pptx_slides__77575b83(result, expected, **options):
    """
    Check if first and last slides were swapped.

    Args:
        result: Dict from getter with 'slides' list
        expected: Dict with 'total_slides', 'original_first_hash', 'original_last_hash'

    Returns:
        Score from 0.0 to 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    result_count = result.get('total_slides', 0)
    expected_count = expected.get('total_slides', 0)
    original_first_hash = expected.get('original_first_hash')
