def check_slide_bg_color__77e3a30f18ab24b0ea45cfea7905a718(result: Optional[Tuple[int, int, int]], expected: dict, **options) -> float:
    """Check if slide background color matches expected RGB value.

    Args:
        result: RGB tuple from getter (r, g, b) or None
        expected: Dict from rules containing:
            - target_rgb: Target RGB tuple (r, g, b)
            - tolerance: Max Euclidean distance to accept (default: 30)
        **options: Additional options

    Returns:
        1.0 if color matches within tolerance, 0.0 otherwise
    """
    target_rgb = expected.get('target_rgb')
    tolerance = expected.get('tolerance', 30)
    if result is None:
        return 0.0
    if target_rgb is None:
        return 0.0
    (r1, g1, b1) = result
    (r2, g2, b2) = target_rgb
    distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
    return 1.0 if distance <= tolerance else 0.0

def check_pptx_text_italic__b14c37c09762994669c122489eecf454(result, expected, **options):
    """Check if text in specified slides has been made italic.

    Args:
        result: Dict from getter with slide indices mapping to list of italic statuses
        expected: Dict with expected italic configuration
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    slides_to_check = expected.get('slides', [])
    total_textboxes = 0
    italic_textboxes = 0
    for slide_idx in slides_to_check:
        if slide_idx not in result:
            continue
        textbox_italic_statuses = result[slide_idx]
        total_textboxes += len(textbox_italic_statuses)
        italic_textboxes += sum(textbox_italic_statuses)
    if total_textboxes == 0:
        return 0.0
    return italic_textboxes / total_textboxes

