def check_slide_title_full__a58a38b7(result, expected, **options):
    """Check if slide title text, font, and size match expected values.

    Args:
        result: dict with 'text', 'font_name', 'font_size' from getter
        expected: dict with expected values
        **options: Additional comparison options (size_tolerance)

    Returns:
        float: Progressive score (0.4 text, 0.3 font, 0.3 size)
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    if result.get('text', '') == expected.get('text', ''):
        score += 0.4
    if result.get('font_name', '') == expected.get('font_name', ''):
        score += 0.3
