def check_ppt_table_text_format__7139c08d16e850f154ac11f8c51f088c(result, expected, **options):
    """Compare table text formatting against expected values.

    Args:
        result: Dict with row_formats from getter
        expected: Dict with expected formatting from rules
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0 based on matching cells
    """
    if not result or not isinstance(result, dict):
        return 0.0
    result_formats = result.get('row_formats', [])
    expected_formats = expected.get('row_formats', [])
    if not expected_formats or not result_formats:
        return 0.0
    score = 0.0
    total_cells = len(expected_formats)
    for (idx, expected_cell) in enumerate(expected_formats):
        if idx >= len(result_formats):
            continue
        result_cell = result_formats[idx]
        cell_score = 0.0
        checks = 0
        if 'text' in expected_cell:
            checks += 1
            if result_cell.get('text', '') == expected_cell['text']:
                cell_score += 1.0
        if 'bold' in expected_cell:
            checks += 1
            expected_bold = expected_cell['bold']
            result_bold = result_cell.get('bold', False)
            if (expected_bold is None or expected_bold is False) and (result_bold is None or result_bold is False):
                cell_score += 1.0
            elif expected_bold == result_bold:
                cell_score += 1.0
        if 'italic' in expected_cell:
            checks += 1
            expected_italic = expected_cell['italic']
            result_italic = result_cell.get('italic', False)
            if (expected_italic is None or expected_italic is False) and (result_italic is None or result_italic is False):
                cell_score += 1.0
            elif expected_italic == result_italic:
                cell_score += 1.0
        if checks > 0:
            score += cell_score / checks
    if total_cells == 0:
        return 0.0
    return score / total_cells

