def check_pptx_slide_position__30eb4ff0(result, expected, **options):
    """Check if a specific slide is at the expected position.

    Args:
        result: Structure dict from getter
        expected: Expected values with slide_count, position, expected_title
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_count = expected.get('slide_count', 0)
    if result.get('slide_count', 0) == expected_count:
        score += 0.5
    titles = result.get('titles', [])
    position = expected.get('position', -1)
    expected_title = expected.get('expected_title', '')
    if position >= 0 and position < len(titles):
        actual_title = titles[position]
        if expected_title.lower() in actual_title.lower() or actual_title.lower() in expected_title.lower():
            score += 0.5
    return min(score, 1.0)

