def check_slide_transition__c688587a(pptx_file, rules):
    """
    Check if a specific slide has the expected transition effect.

    Args:
        pptx_file: Path to the PPTX file
        rules: Dict with 'slide_idx' (0-indexed) and 'transition_type' (e.g., 'fade', 'dissolve', 'push')

    Returns:
        float: 1.0 if transition matches, 0.0 otherwise
    """
    try:
        slide_idx = rules.get('slide_idx', 0)
        transition_type = rules.get('transition_type', 'fade')
        with zipfile.ZipFile(pptx_file, 'r') as zip_ref:
            slide_name = 'ppt/slides/slide{}.xml'.format(slide_idx + 1)
            try:
                zip_ref.getinfo(slide_name)
            except KeyError:
                return 0.0
            with zip_ref.open(slide_name) as slide_file:
                tree = ET.parse(slide_file)
                root = tree.getroot()
                namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
                transition = root.find('.//p:transition', namespaces)
                if transition is not None:
                    expected_transition = transition.find('.//p:{}'.format(transition_type), namespaces)
                    if expected_transition is not None:
                        return 1.0
                    else:
                        return 0.0
                else:
                    return 0.0
    except Exception as e:
        return 0.0

def check_impress_sidebar_panel__60d2a788(accessibility_tree, expected, **options):
    """
    Check if a specific sidebar panel is visible in LibreOffice Impress.

    Args:
        accessibility_tree: XML string of the accessibility tree
        expected: Dict with panel_type to search for
        **options: Additional options

    Returns:
        float: 1.0 if panel is visible, 0.0 otherwise
    """
    try:
        root = ET.fromstring(accessibility_tree)
        panel_type = expected.get('panel_type', 'Slides View')
        for element in root.iter('document-frame'):
            if element.attrib.get('name') == panel_type:
                return 1.0
        return 0.0
    except Exception as e:
        return 0.0

