def check_pptx_para_level__2f7d454ffebcc69bdbaa46df6745791e(result: Dict[str, int], expected: Dict[str, Any], **options) -> float:
    """Check if paragraph indentation levels match expected values.

    Args:
        result: Dict mapping paragraph text to its level (from getter)
        expected: Rules dict with:
            - text_levels: Dict mapping text strings to expected levels
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    text_levels = expected.get('text_levels', {})
    if not text_levels:
        return 0.0
    total_checks = len(text_levels)
    correct = 0
    for (text, expected_level) in text_levels.items():
        for (result_text, result_level) in result.items():
            if text.lower() in result_text.lower():
                if result_level == expected_level:
                    correct += 1
                break
    return correct / total_checks if total_checks > 0 else 0.0

