def check_pptx_table_color__b2f4e6a9(result_file, expected, **options):
    """
    Check if all text in table has the specified color.
    
    Args:
        result_file: Path to the PPTX file
        expected: Rules dict with 'slide_idx', 'shape_idx', and 'rgb' (list of 3 ints)
        **options: Additional options
        
    Returns:
        float: 1.0 if all table text has correct color, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 0)
        rgb_expected = tuple(expected.get('rgb', [255, 0, 0]))
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if shape.shape_type != MSO_SHAPE_TYPE.TABLE:
            return 0.0
        table = shape.table
        for row_idx in range(len(table.rows)):
            for col_idx in range(len(table.columns)):
                cell = table.cell(row_idx, col_idx)
                for para in cell.text_frame.paragraphs:
                    for run in para.runs:
                        if not run.text.strip():
                            continue
                        if hasattr(run.font.color, 'rgb') and run.font.color.rgb is not None:
                            rgb_actual = (run.font.color.rgb.red, run.font.color.rgb.green, run.font.color.rgb.blue)
                            if rgb_actual != rgb_expected:
                                return 0.0
                        else:
                            return 0.0
        return 1.0
    except Exception as e:
        return 0.0

