def check_pptx_bullet_points__1604a405(result_file, expected, **options):
    """Check if specific bullet points exist in the slide.
    
    Args:
        result_file: Path to the PPTX file
        expected: Dict with 'slide_index' and 'expected_bullets' (list of strings)
        
    Returns:
        float: Proportion of bullets found (0.0-1.0)
    """
    try:
        slide_index = expected.get('slide_index', 0)
        expected_bullets = expected.get('expected_bullets', [])
        if not expected_bullets:
            return 0.0
        prs = Presentation(result_file)
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        all_text = ''
        for shape in slide.shapes:
            if hasattr(shape, 'text'):
                all_text += shape.text + ' '
        found_count = 0
        for bullet in expected_bullets:
            if bullet in all_text:
                found_count += 1
        return found_count / len(expected_bullets)
    except Exception as e:
        print(f'Error checking PPTX bullets: {e}')
        return 0.0

def check_pptx_title_alignment__9a174f14601a961feee9e56852bcd022(result, expected, **options):
    """Check if titles in specified slides have the target alignment.

    Args:
        result: dict mapping slide_index -> alignment_value (int)
        expected: dict with keys:
            - slides: list of slide indices
            - alignment: target alignment (2 for CENTER, 1 for LEFT, 3 for RIGHT)
        **options: Additional options (unused)

    Returns:
        float: Score between 0.0 and 1.0 (partial credit for each correct slide)
    """
    target_slides = expected.get('slides', [])
    target_alignment = expected.get('alignment', 2)
    if not target_slides:
        return 0.0
    correct_count = 0
    for slide_idx in target_slides:
        actual_alignment = result.get(slide_idx)
