def check_ppt_background_text__40902a34(result, expected, **options):
    """Check PowerPoint background colors and text content.

    Args:
        result: dict from getter with background_colors, first_slide_texts
        expected: dict with expected values (from rules)
        **options: Additional options

    Returns:
        float: Score 0.0-1.0 with partial credit
    """
    score = 0.0
    background_colors = result.get('background_colors', [])
    if background_colors:
        blue_count = 0
        for color in background_colors:
            if color is not None:
                (r, g, b) = color
                if b > r and b > g:
                    blue_count += 1
        if len(background_colors) > 0 and blue_count / len(background_colors) >= 0.5:
            score += 0.5
    expected_text = expected.get('text_content', '').strip()
    first_slide_texts = result.get('first_slide_texts', [])
    for text in first_slide_texts:
        if expected_text in text or text == expected_text:
            score += 0.5
            break
    return min(score, 1.0)

