def check_pptx_duplicated_slides__d3ab68c90a12326ec4e4004c444118f8(result, expected, **options):
    """Check if specific slides were duplicated correctly.

    Args:
        result: Slide information from getter
        expected: Expected configuration with original_slides and target_positions

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or 'slides' not in result:
        return 0.0
    slides = result['slides']
    original_count = expected.get('original_count', 0)
    duplicated_indices = expected.get('duplicated_indices', [])
    expected_final_count = expected.get('expected_final_count', 0)
    if result['slide_count'] != expected_final_count:
        return 0.0
    score = 0.0
    if result['slide_count'] == expected_final_count:
        score += 0.4
    else:
        return 0.0
    if len(duplicated_indices) >= 2:
        (idx1, idx2) = (duplicated_indices[0], duplicated_indices[1])
        if idx1 < len(slides) and idx2 < len(slides):
            slide1_orig = slides[idx1]
            slide2_orig = slides[idx2]
            copy1_pos = idx2 + 1
            copy2_pos = idx2 + 2
            if copy1_pos < len(slides) and copy2_pos < len(slides):
                slide1_copy = slides[copy1_pos]
                slide2_copy = slides[copy2_pos]
                texts_match_1 = texts_match_fuzzy(slide1_orig.get('texts', []), slide1_copy.get('texts', []))
                texts_match_2 = texts_match_fuzzy(slide2_orig.get('texts', []), slide2_copy.get('texts', []))
                layout_match_1 = slide1_orig.get('layout') == slide1_copy.get('layout')
                layout_match_2 = slide2_orig.get('layout') == slide2_copy.get('layout')
                count_match_1 = slide1_orig.get('text_count') == slide1_copy.get('text_count')
                count_match_2 = slide2_orig.get('text_count') == slide2_copy.get('text_count')
                preservation_valid = True
                if len(slides) > copy2_pos + 1:
                    for check_pos in range(copy2_pos + 1, min(len(slides), copy2_pos + 5)):
                        slide_to_check = slides[check_pos]
                        if texts_match_fuzzy(slide_to_check.get('texts', []), slide1_orig.get('texts', [])) or texts_match_fuzzy(slide_to_check.get('texts', []), slide2_orig.get('texts', [])):
                            preservation_valid = False
                            break
                if texts_match_1 and texts_match_2 and layout_match_1 and layout_match_2 and count_match_1 and count_match_2 and preservation_valid:
                    score += 0.6
    return score

