def check_pptx_new_slide__fb7ec5ee(result_file, expected, **options):
    """
    Check if presentation has correct slide count and a specific slide has expected title at the correct position.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing 'expected_count', 'slide_idx', 'expected_title'
        **options: Additional options

    Returns:
        float: 1.0 if all conditions met, partial scores for partial completion
    """
    try:
        prs = Presentation(result_file)
        expected_count = expected.get('expected_count', 0)
        slide_idx = expected.get('slide_idx', 0)
        expected_title = expected.get('expected_title', '')
        actual_count = len(prs.slides)
        score = 0.0
        if actual_count == expected_count:
            score += 0.33
        else:
            return 0.0
        if slide_idx < len(prs.slides):
            slide = prs.slides[slide_idx]
            title_text = ''
            if slide.shapes.title:
                title_text = slide.shapes.title.text.strip()
            if title_text == expected_title.strip():
                score += 0.34
            else:
                return score
        else:
            return score
        prev_slide_idx = slide_idx - 1
        if prev_slide_idx >= 0 and prev_slide_idx < len(prs.slides):
            prev_slide = prs.slides[prev_slide_idx]
            prev_title_text = ''
            if prev_slide.shapes.title:
                prev_title_text = prev_slide.shapes.title.text.strip()
            if prev_title_text == 'Writing':
                score += 0.33
        return score
    except Exception as e:
        return 0.0

