def check_ppt_properties__616b635f(result, expected, **options):
    """
    Check if PPT properties match expected values.

    Args:
        result: Dict with properties from getter
        expected: Dict with expected properties
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    score = 0.0
    total_checks = 0
    for (key, expected_value) in expected.items():
        total_checks += 1
        if key in result:
            actual_value = result[key]
            if key.endswith('_color'):
                if actual_value == expected_value:
                    score += 1.0
            elif isinstance(expected_value, bool):
                actual_normalized = actual_value if actual_value is not None else False
                expected_normalized = expected_value if expected_value is not None else False
                if actual_normalized == expected_normalized:
                    score += 1.0
            elif actual_value == expected_value:
                score += 1.0
    if total_checks == 0:
        return 0.0
    return score / total_checks

def check_pptx_image_size__fa78320f77f752690c6f86477606b047(result, expected, **options):
    """Check if a PowerPoint slide contains an image with the expected size.

    Args:
        result: dict from getter with image information
        expected: dict with 'slide_index', 'expected_width_cm', 'expected_height_cm'
        **options: Additional options (tolerance)

    Returns:
        float: Score between 0.0 and 1.0
    """
    tolerance = options.get('tolerance', 0.01)
    expected_width = expected.get('expected_width_cm')
    expected_height = expected.get('expected_height_cm')
    if not result or 'image_count' not in result:
        return 0.0
    if result['image_count'] == 0:
        return 0.0
    images = result.get('images', [])
    for img in images:
        width_cm = img['width_cm']
        height_cm = img['height_cm']
        width_match = abs(width_cm - expected_width) / expected_width <= tolerance
        height_match = abs(height_cm - expected_height) / expected_height <= tolerance
        if width_match and height_match:
            return 1.0
    return 0.0

