def check_pptx_picture_height__3e520ec8(result_file, expected, **options):
    """
    Check if the largest picture on a specific slide has the target height.

    Args:
        result_file: Path to the PPTX file
        expected: Expected height in cm (from rules dict)
        **options: Additional options

    Returns:
        float: 1.0 if height matches (within 0.5cm tolerance), 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        target_height_cm = expected.get('target_height_cm', 0)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        pictures = [shape for shape in slide.shapes if shape.shape_type == 13]
        if not pictures:
            return 0.0
        largest_pic = max(pictures, key=lambda p: p.width * p.height)
        actual_height_cm = largest_pic.height / 360000.0
        tolerance = 0.5
        if abs(actual_height_cm - target_height_cm) <= tolerance:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        return 0.0

